// Offline interactive spatial model; presented separately from the concept renderings.
function skyModelScene(space){
 const base=space==='全部空间'?composeHouse3D():(CQ_3D_SCENES[space]||CQ_3D_SCENES['客厅']);
 const items=base.items.filter(it=>!(it.label&&it.w===.04)).map(it=>({...it,label:null}));
 const [fw,fd]=base.floor;
 const add=(x,y,w,d,h,c,z=0)=>items.push({t:'box',x,y,w,d,h,c,z});
 // Low cutaway perimeter walls preserve the layout while orbiting.
 add(0,-fd/2,fw,.12,.8,'#eef0ee');add(-fw/2,0,.12,fd,.8,'#eef0ee');
 if(space!=='全部空间'){
  if(space==='客厅'){add(-2.5,-.3,5,3.8,.02,'#d8d4c9');add(-3.2,-2.3,3.6,.2,.38,'#c5b4a1',.7);for(let i=0;i<3;i++)add(-4.35+i*1.15,-1.8,1.04,.93,.12,'#ded1bf',.73);add(-4.1,-.2,.95,1.9,.13,'#ded1bf',.73);for(const x of [1.1,2.5])for(const y of [-1.15,1.15]){add(x,y,.35,.35,.12,'#c6b497',.45);add(x,y+(y>0?.19:-.19),.42,.08,.52,'#a88a61',.42);}add(-2.1,.2,.28,.2,.03,'#7e8e91',.4);}
  if(space==='主卧'){add(-1.4,0,4,4,.022,'#d8d6cc');add(-1.4,-.85,2.6,.18,1,'#c3b198');add(-1.9,-.4,.7,.48,.14,'#fff9ef',.73);add(-.9,-.4,.7,.48,.14,'#fff9ef',.73);add(-1.4,.5,2.05,.7,.035,'#99aeb7',.71);for(let i=0;i<5;i++)add(2.77,-1.2+i*.6,.02,.015,1.3,'#8a785e',.35);}
  if(space==='儿童房'){add(-1.1,.4,3.5,3,.025,'#e0ddcd');add(-2.1,.4,1.65,.95,.08,'#f3eee4',.49);add(-2.55,.4,.45,.7,.12,'#fff8ee',.57);add(.7,.2,1.5,.65,.07,'#d6c1a2',.72);add(.7,1.24,.42,.07,.42,'#c4ab87',.46);}
  if(space==='主卫'){add(1.8,.1,2.1,2.4,.02,'#c4dce3');for(let i=0;i<items.length;i++){if(items[i].h===1.85)items[i].h=.18;}add(-1.6,-.7,1.14,.49,.05,'#ffffff',.78);add(-1.6,-.65,.54,.29,.08,'#d4e4e9',.83);}
 }
 return {floor:base.floor,items};
}
renderSpace3D=function(ctx,space,yaw,zoom=1){
 const scene=skyModelScene(space),W=ctx.canvas.width,H=ctx.canvas.height,[fw,fd]=scene.floor;
 ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#fbfdff');bg.addColorStop(1,'#edf3f8');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
 const scale=Math.min(W/(fw+fd)*1.0,H/(fw+fd)*1.7)*zoom;const cx=W/2,cy=H*.52,c=Math.cos(yaw),s=Math.sin(yaw);
 const project=([x,y,z])=>{const a=x*c-y*s,b=x*s+y*c;return [cx+(a-b)*scale*.9,cy+(a+b)*scale*.46-z*scale,(a+b)-z*.5];};
 const polygon=(pts,fill,stroke)=>{ctx.beginPath();pts.forEach((p,i)=>{const q=project(p);if(i)ctx.lineTo(q[0],q[1]);else ctx.moveTo(q[0],q[1]);});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=Math.max(1,W/1800);ctx.stroke();}};
 ctx.save();ctx.shadowColor='#64819928';ctx.shadowBlur=scale*.7;ctx.shadowOffsetY=scale*.3;polygon([[-fw/2,-fd/2,-.06],[fw/2,-fd/2,-.06],[fw/2,fd/2,-.06],[-fw/2,fd/2,-.06]],'#d7dde0');ctx.restore();
 polygon([[-fw/2,-fd/2,0],[fw/2,-fd/2,0],[fw/2,fd/2,0],[-fw/2,fd/2,0]],'#e8e4dc','#cdd6dc');
 for(let y=-fd/2;y<fd/2;y+=.45){const a=project([-fw/2,y,.002]),b=project([fw/2,y,.002]);ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.strokeStyle='#b6ad971c';ctx.lineWidth=1;ctx.stroke();}
 const faces=[];const push=(p,color)=>faces.push({p,color,depth:p.reduce((n,v)=>n+project(v)[2],0)/p.length});
 scene.items.forEach(it=>{const {x,y,h,c:color}=it,z=it.z||0;
  if(it.t==='cyl'){const n=32;const top=[];for(let k=0;k<n;k++){const a=k/n*Math.PI*2,b=(k+1)/n*Math.PI*2;const v=[x+Math.cos(a)*it.r,y+Math.sin(a)*it.r,z],w=[x+Math.cos(b)*it.r,y+Math.sin(b)*it.r,z];push([v,w,[w[0],w[1],z+h],[v[0],v[1],z+h]],shade(color,-10+Math.round(Math.cos(a+yaw)*12)));top.push([v[0],v[1],z+h]);}push(top,shade(color,12));}
  else{const w=it.w/2,d=it.d/2;const a=[x-w,y-d,z],b=[x+w,y-d,z],c1=[x+w,y+d,z],e=[x-w,y+d,z],top=p=>[p[0],p[1],p[2]+h];push([a,b,top(b),top(a)],shade(color,-12));push([b,c1,top(c1),top(b)],shade(color,-18));push([c1,e,top(e),top(c1)],shade(color,-5));push([e,a,top(a),top(e)],shade(color,0));push([top(a),top(b),top(c1),top(e)],shade(color,14));}
 });faces.sort((a,b)=>a.depth-b.depth).forEach(f=>polygon(f.p,f.color));
 const dpr=window.devicePixelRatio||1;ctx.fillStyle='#a0b4c5';ctx.font=`${10*dpr}px Inter,Arial`;ctx.fillText('GEORGE  /  SPATIAL STUDY',22*dpr,26*dpr);
};
mountSpace3D=function(host){
 const canvas=host.querySelector('canvas');if(!canvas)return {stop(){}};const ctx=canvas.getContext('2d');let yaw=.13,zoom=1,drag=false,last=0;
 const draw=()=>{const r=host.getBoundingClientRect();if(r.width<5||r.height<5)return;const d=Math.min(window.devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;renderSpace3D(ctx,host.dataset.cq3d,yaw,zoom);};host._cqDraw=draw;
 canvas.addEventListener('pointerdown',e=>{drag=true;last=e.clientX;canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';});canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-last)*.007;last=e.clientX;draw();});const end=()=>{drag=false;canvas.style.cursor='grab';};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
 canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.min(1.8,Math.max(.65,zoom-e.deltaY*.0008));draw();},{passive:false});
 const ro=new ResizeObserver(draw);ro.observe(host);draw();return {stop(){ro.disconnect();}};
};

