function skyData(){
 const p=findProject(archiveProject),quotes=projectQuoteRows(p[0]);const cat=ensureClientCat(quotes);const space=ensureClientSpace(quotes,cat);const cats=clientCatTotals(quotes);const quoted=cats.filter(c=>c.quoted);const current=cats.find(c=>c.cat===cat);const all=cat==='全部品类';
 const rooms=clientAssignedSpaces(quotes,cat);const rows=[];rooms.filter(q=>space==='all'||q.space===space).forEach(q=>qCategoryGroups(q).filter(g=>hasDraftForCat(archiveProject,g.cat)&&(all||g.cat===cat)).forEach(g=>g.items.forEach(x=>{const a=x.slice();a.space=q.space;rows.push(a);})));const total=quoted.reduce((n,c)=>n+c.amount,0);const amount=rows.reduce((n,x)=>n+qNum(x[2]),0);const categoryAmount=all?total:current?.amount||0;const confirmed=quoted.filter(c=>catFullyConfirmed(quotes,c.cat)||QUOTE_UI.clientSelected[c.cat]).length;const done=!all&&!!current?.quoted&&(catFullyConfirmed(quotes,cat)||QUOTE_UI.clientSelected[cat]);
 return {p,quotes,cat,space,cats,quoted,current,all,rooms,rows,total,amount,categoryAmount,confirmed,done,unquoted:!all&&!current?.quoted};
}
