let wkEditorTemplatePromise;
function wkLoadEditorTemplate(){
 if(wkEditorTemplatePromise)return wkEditorTemplatePromise;
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);
 wkEditorTemplatePromise=fetch(WK_EDITOR_URL,{signal:controller.signal}).then(response=>{
  if(!response.ok)throw Error('报价模板加载失败');return response.text();
 }).then(html=>{
  if(!/^\s*<!doctype html>/i.test(html)||!html.includes('<head>')||!html.includes('__CRM_INITIAL'))throw Error('报价模板内容无效');
  return html;
 }).catch(error=>{wkEditorTemplatePromise=undefined;throw error;}).finally(()=>clearTimeout(timer));
 return wkEditorTemplatePromise;
}
