 function animate(now){if(stopped||!state.auto)return;const dt=lastMoveTime?Math.min(32,now-lastMoveTime):16;lastMoveTime=now;state.yaw+=dt*.00012;requestDraw();autoRaf=requestAnimationFrame(animate);}
 function clearPaint(){for(const r of paintRecords){r.mesh.material=r.original;r.clones.forEach(m=>m.dispose());}paintRecords=[];for(const line of edgeLines){line.parent?.remove(line);line.geometry.dispose();line.material.dispose();}edgeLines=[];painted=null;}
 function paintProduct(g){if(painted===g)return;clearPaint();painted=g;if(g){const meshes=[];g.traverse(o=>{if(o.isMesh&&o.material)meshes.push(o)});for(const mesh of meshes){const original=mesh.material,clones=(Array.isArray(original)?original:[original]).map(m=>{const c=m.clone();if(c.emissive){c.emissive.set('#329bcc');c.emissiveIntensity=.26;}return c;});mesh.material=Array.isArray(original)?clones:clones[0];paintRecords.push({mesh,original,clones});const edges=new T.EdgesGeometry(mesh.geometry,38),line=new T.LineSegments(edges,new T.LineBasicMaterial({color:'#62b5d5',transparent:true,opacity:.72,depthTest:true}));mesh.add(line);edgeLines.push(line);}}requestDraw();}
