 function clearRecognition(){for(const r of recognitionPaint){r.mesh.material=r.original;r.clones.forEach(m=>m.dispose());}recognitionPaint=[];for(const line of recognitionLines){line.parent?.remove(line);line.geometry.dispose();line.material.dispose();}recognitionLines=[];recognitionCount=0;}
 function recognize(on){on=!!on;const category=QUOTE_UI.clientCat||'全部品类',scope=category+'|'+key;if(on===recognitionOn&&recognitionBuilt&&scope===recognitionCategory)return;closeObject();clearRecognition();recognitionCategory=scope;recognitionOn=on;recognitionBuilt=true;if(on){const meshes=new Set(),products=new Set();world.root.updateMatrixWorld(true);for(const g of world.pickables){const row=quoteRow(g);if(!row||(category!=='全部品类'&&row.p[1]!==category)||(key!=='全部空间'&&row.space!==key))continue;products.add(row.space+'|'+row.p[3]);g.traverse(o=>{if(o.isMesh)meshes.add(o)});}for(const mesh of meshes){const line=new T.LineSegments(new T.EdgesGeometry(mesh.geometry,28),new T.LineBasicMaterial({color:'#208ec5',transparent:true,opacity:.88,depthTest:true}));line.userData.recognition=true;line.raycast=()=>{};mesh.add(line);recognitionLines.push(line);if(category!=='全部品类'&&mesh.material){const original=mesh.material,clones=(Array.isArray(original)?original:[original]).map(m=>{const c=m.clone();c.color?.lerp(new T.Color('#6fc5e9'),.22);if(c.emissive){c.emissive.set('#319bcc');c.emissiveIntensity=.20;}return c;});mesh.material=Array.isArray(original)?clones:clones[0];recognitionPaint.push({mesh,original,clones});}}recognitionCount=products.size;}host.dataset.recognitionCategory=category;host.dataset.recognition=String(on);host.dataset.recognitionCount=String(recognitionCount);requestDraw();}
