 function select(g){closeObject();selected=g;const row=quoteRow(g);selected.userData.quoteRow=row;stopAuto();if(!row){toast(skyT('该陈设在当前品类下暂无已提交报价。','This furnishing has no submitted quote in the current category.'));return;}paintProduct(g);const {p,space}=row;delete canvas.dataset.key;Object.assign(canvas.dataset,{name:p[0],cat:p[1],price:p[2],sku:p[3],qty:String(p[4]),unit:p[5],space,unquoted:String(p._v28Quoted===false)});skyProductDetails(canvas);}
