 canvas.addEventListener('pointermove',e=>{const last=points.get(e.pointerId);if(!last){if(e.pointerType==='mouse'&&!state.auto){const h=hitObject(e.clientX,e.clientY);setHover(h.quoted?h.g:null,e.clientX,e.clientY);const room=roomHit(e.clientX,e.clientY);host.dataset.hoverRoom=room;selectRoom(QUOTE_UI.clientSpace,room);if(room&&!h.g)canvas.style.cursor='pointer';}return;}const dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.hypot(e.clientX-startX,e.clientY-startY)>4)moved=true;points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2){const q=[...points.values()],dist=Math.hypot(q[0].x-q[1].x,q[0].y-q[1].y);state.radius=T.MathUtils.clamp(state.radius*lastPinch/Math.max(1,dist),extent*.65,extent*3.2);lastPinch=dist;moved=true;}else if(panDrag){const k=state.radius*.0009;state.tx-=dx*Math.cos(state.yaw)*k;state.tz+=dx*Math.sin(state.yaw)*k;state.tx-=dy*Math.sin(state.yaw)*k;state.tz-=dy*Math.cos(state.yaw)*k;state.tx=T.MathUtils.clamp(state.tx,-extent,extent);state.tz=T.MathUtils.clamp(state.tz,-extent,extent);}else{state.yaw-=dx*.006;state.pitch=T.MathUtils.clamp(state.pitch-dy*.005,.025,1.35);pressed('top',state.pitch<.06);pressed('orbit',state.pitch>=.06);}requestDraw();},{signal});
