/* GEORGE Workspace — a unified visual shell around the existing workflows. */
const V5={homeFilter:'全部',navMini:wkRead('crm-nav-mini-v5',false)};
const V5_NAV=[['工作空间',[['home','home','工作台'],['todos','check','待办中心']]],['客户与项目',[['customers','users','客户管理'],['projects','brief','项目管理'],['opps','chart','商机管理'],['invite','file','客户邀请函'],['arrival','home','邀约到店'],['sea','users','客户公海']]],['方案与报价',[['drafts','file','报价单报价'],['mall','grid','商城选品']]]];
function v5Nav(){const kind=pageKind(page),active=({board:'projects',detail:'projects',oppDetail:'opps',custDetail:'customers',draftEditor:'drafts'})[kind]||kind;return `<div class="v5-nav-top"><span>业务工作空间</span><button data-v5="foldNav" title="${V5.navMini?'展开导航':'收起导航'}" aria-label="${V5.navMini?'展开导航':'收起导航'}"><svg class="sky-icon" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16"/></svg></button></div><nav class="v5-nav-links" aria-label="主导航">${V5_NAV.map(([name,items])=>`<section><div class="v5-nav-group">${name}</div>${items.map(([id,icon,label])=>`<button data-v5="nav" data-page="${id}" class="${active===id?'on':''}" ${active===id?'aria-current="page"':''} title="${label}">${skyIcon(icon)}<span>${label}</span>${id==='todos'?`<small>${visibleTodos().filter(t=>t.status==='待处理').length}</small>`:''}</button>`).join('')}</section>`).join('')}</nav><div class="v5-nav-bottom">${companyLogo("company-logo-light")}<p>让理想空间成为日常</p></div>`;}
function v5SyncNav(){
 const nav=document.getElementById('v5Nav'),links=nav?.querySelector('.v5-nav-links'),scrollTop=links?.scrollTop||0;
 if(nav)nav.innerHTML=v5Nav();
 document.querySelector('.app').classList.toggle('v5-nav-mini',V5.navMini);
 // Rebuilding the selected menu must not send the navigation scrollbar to the top.
 const next=nav?.querySelector('.v5-nav-links');if(next)next.scrollTop=scrollTop;
}
function v5ShortDate(value){return String(value||'').slice(5,16)||'—';}
pageHome=function(){const c=v3Counts(),pending=visibleTodos().filter(t=>t.status==='待处理'),recent=pending.filter(t=>V5.homeFilter==='全部'||(V5.homeFilter==='报价'&&t.type==='报价待办')||(V5.homeFilter==='订单'&&t.type==='订单待办')).slice().sort((a,b)=>parseTodoTime(b.time)-parseTodoTime(a.time)).slice(0,5),progress=c.submitted+c.confirmed+c.bound;return `<div class="v5-home"><header class="v5-page-heading"><div><div class="v5-breadcrumb">工作空间 / 首页</div><h1>工作台</h1><p>${esc(V3.user)}，${new Date().getHours()<12?'上午':new Date().getHours()<18?'下午':'晚上'}好。今天的业务进展，尽在掌握。</p></div><div class="v5-heading-right"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><button class="wk-btn primary" data-act="go:draftEditor">${skyIcon('file')}新建报价</button></div></header><section class="v5-home-banner"><img src="${SKY_ASSETS.hero}" alt="现代家居空间"><div class="v5-banner-copy"><small>敬城 CRM · WORKSPACE</small><h2>让每一份期待，<br>都有恰到好处的回应。</h2><p>从客户需求到空间交付，连接业务的每一步。</p><button data-v3="homeTodos">查看待办 <span>${pending.length}</span>${skyIcon('arrow')}</button></div><div class="v5-banner-caption"><span>DESIGN FOR LIVING</span><i></i><span>成就理想空间</span></div></section><div class="v5-metrics">${[['待处理事项',pending.length,'待跟进的业务事项','brief','todos'],['待客户确认',c.submitted,'已提交报价','file','已提交'],['待绑定商机',c.confirmed,'客户已确认报价','check','已确认'],['进行中项目',PROJECTS.filter(p=>!/关闭|终止|完成/.test(p[4]||'')).length,'当前项目列表','home','projects']].map(([label,n,sub,icon,filter])=>`<button class="v5-metric" data-v3="homeMetric" data-filter="${filter}"><div><span>${label}</span>${skyIcon(icon)}</div><b>${n}<small>项</small></b><p>${sub}</p></button>`).join('')}</div><div class="v5-home-grid"><div class="v5-home-main"><section class="v5-surface"><div class="v5-surface-head"><div><h2>待办事项</h2><span>按到达时间排序</span></div><button class="v5-text-btn" data-v3="homeTodos">全部待办 ${skyIcon('arrow')}</button></div><div class="v5-task-tabs">${['全部','报价','订单'].map(f=>`<button class="${V5.homeFilter===f?'on':''}" data-v5="homeFilter" data-filter="${f}">${f==='全部'?'全部事项':f+'事项'}</button>`).join('')}</div><div class="v5-task-preview">${recent.map(t=>`<div class="v5-task-line"><div class="v5-task-icon">${skyIcon(t.type==='报价待办'?'file':t.type==='订单待办'?'brief':'check')}</div><div class="v5-task-copy"><b>${esc(todoSubject(t))}</b><span>${esc(t.customer||'未关联客户')}<i>·</i>${esc(t.type)}</span></div><div class="v5-task-person"><b>${esc(t.owner||'待分配')}</b><span>${esc(v5ShortDate(t.time))}</span></div><button class="v5-row-open" data-v3="homeTask" data-id="${t.id}" aria-label="查看${esc(todoSubject(t))}">${skyIcon('arrow')}</button></div>`).join('')||'<div class="v3-empty-note">当前没有此类待处理事项</div>'}</div></section><section class="v5-surface v5-projects"><div class="v5-surface-head"><div><h2>项目概览</h2><span>客户与空间方案</span></div><button class="v5-text-btn" data-act="go:projects">全部项目 ${skyIcon('arrow')}</button></div><div class="v5-project-table">${PROJECTS.slice(0,3).map((p,i)=>`<div class="v5-project-row"><span class="v5-project-num">${String(i+1).padStart(2,'0')}</span><div><b>${esc(p[1])}</b><small>${esc(p[0])} · ${esc(p[7])}</small></div><span class="v5-project-status">${esc(p[3]||'跟进中')}</span><button class="v5-text-btn" data-act="go:board" data-proj="${p[0]}">报价总览 ${skyIcon('arrow')}</button></div>`).join('')}</div></section></div><aside class="v5-home-aside"><section class="v5-surface"><div class="v5-surface-head"><div><h2>报价进展</h2><span>${progress} 份已提交报价单</span></div>${skyIcon('chart')}</div><div class="v5-pipeline"><div class="v5-pipeline-bar">${[['submitted',c.submitted],['confirmed',c.confirmed],['bound',c.bound]].map(([k,n])=>`<i class="${k}" style="flex:${n||0}"></i>`).join('')}</div>${[['已提交',c.submitted,'等待客户确认','submitted'],['已确认',c.confirmed,'等待绑定商机','confirmed'],['已绑定',c.bound,'进入订单执行','bound']].map(([label,n,sub,tone])=>`<button data-v3="homeMetric" data-filter="${label}"><i class="${tone}"></i><div><b>${label}</b><small>${sub}</small></div><strong>${n}</strong>${skyIcon('arrow')}</button>`).join('')}</div></section><section class="v5-surface"><div class="v5-surface-head"><div><h2>常用入口</h2></div></div><div class="v5-shortcuts">${[['file','新建报价','draftEditor'],['grid','商城选品','mall'],['brief','项目管理','projects'],['users','客户管理','customers']].map(([icon,label,id])=>`<button data-act="go:${id}">${skyIcon(icon)}<span>${label}</span>${skyIcon('arrow')}</button>`).join('')}</div></section><div class="v5-home-signature">${companyLogo()}<p>让理想空间成为日常</p><small>客户 · 方案 · 交付</small></div></aside></div></div>`;};
