function v5SearchResults(query=''){const q=query.trim().toLowerCase(),results=[...PROJECTS.filter(p=>[p[0],p[1],p[7]].join(' ').toLowerCase().includes(q)).map(p=>({kind:'project',id:p[0],title:p[1],sub:p[0]+' · '+p[7],label:'项目'})),...DRAFTS.filter(r=>[r[0],r[1],r[3]].join(' ').toLowerCase().includes(q)).map(r=>({kind:'draft',id:r[0],title:r[1],sub:r[0]+' · '+r[3],label:'报价单'}))].slice(0,9);return results.map(r=>`<button class="v5-search-result" data-v5="searchResult" data-kind="${r.kind}" data-id="${esc(r.id)}">${skyIcon(r.kind==='project'?'brief':'file')}<span><b>${esc(r.title)}</b><small>${esc(r.sub)}</small></span><em>${r.label}</em>${skyIcon('arrow')}</button>`).join('')||'<div class="v3-empty-note">没有找到匹配的项目或报价单</div>';}
function v5Search(){v3Dialog('搜索项目与报价单',`<label class="v5-search-input">${skyIcon('search')}<input id="v5SearchInput" placeholder="输入名称、编号、客户或负责人" autocomplete="off"></label><div id="v5SearchResults">${v5SearchResults()}</div>`,'<small>Enter 打开首项 · Esc 关闭</small><button class="wk-btn" data-v3="closeDialog">关闭</button>');document.getElementById('v5SearchInput').focus();}

const app=document.querySelector('.app');app.classList.add('v5-app');app.insertAdjacentHTML('beforeend','<aside class="v5-nav" id="v5Nav"></aside>');
document.querySelector('.brand').innerHTML=companyLogo()+'<span class="v6-system-name">敬城 CRM</span>';
document.querySelector('.top .marquee').remove();document.querySelector('.top .theme-wrap').style.display='none';const oldSearch=document.querySelector('.top>.right>.iconbtn');if(oldSearch)oldSearch.outerHTML=`<button class="v5-global-search" data-v5="search">${skyIcon('search')}<span>搜索项目、报价单</span><kbd>⌘ / Ctrl K</kbd></button>`;
document.querySelector('#btnRefresh').innerHTML=skyIcon('rotate');document.querySelector('.v3-user-button').innerHTML='AY';document.querySelector('.v3-user-button').insertAdjacentHTML('afterend','<span class="v5-user-name">Andy Ye<small>项目经理</small></span>');
const v5OldOpenPage=openPage;
openPage=function(id,opt){const result=v5OldOpenPage(id,opt);v5SyncNav();if(!V3.client)document.title=document.documentElement.dataset.auth==='on'?'敬城 CRM · '+(pageKind(page)==='home'?'工作台':'客户经营与空间交付'):'登录 · 敬城 CRM';return result;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v5]');if(!b)return;const a=b.dataset.v5;if(a==='nav')openPage(b.dataset.page);if(a==='foldNav'){V5.navMini=!V5.navMini;wkWrite('crm-nav-mini-v5',V5.navMini);v5SyncNav();}if(a==='homeFilter'){V5.homeFilter=b.dataset.filter;openPage('home');}if(a==='search')v5Search();if(a==='searchResult'){v3CloseDialog();if(b.dataset.kind==='project'){archiveProject=b.dataset.id;openPage('board');}else v3DraftDetail(b.dataset.id);}});
document.addEventListener('input',e=>{if(e.target.id==='v5SearchInput')document.getElementById('v5SearchResults').innerHTML=v5SearchResults(e.target.value);});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!V3.client&&document.documentElement.dataset.auth==='on'){e.preventDefault();v5Search();}if(e.key==='Enter'&&e.target.id==='v5SearchInput'){e.preventDefault();document.querySelector('#v5SearchResults button')?.click();}});
v5SyncNav();if(!V3.client){if(document.getElementById('v3Login'))v3Login();if(pageKind(page)==='home')openPage('home');}

/* A resubmission supersedes approval; a quick save still preserves the snapshot. */
const v8ApplySaved=applyDraftSaved;
applyDraftSaved=function(input){const cats=[...new Set([...v3Cats(input),...(input.draftCode?v3Meta(input.draftCode).categories:[])])];const blocked=cats.find(cat=>v3ScopeRecords(input.project,cat).some(([,m])=>m.bindings[cat]));if(blocked)return toast(blocked+'已有已绑定报价，请先处理订单变更后再提交新报价。');return v8ApplySaved(input);};
const v8Invalidate=v3Invalidate;
v3Invalidate=function(project,cats){for(const cat of cats)for(const [,m] of v3ScopeRecords(project,cat)){if(m.confirmedCats.includes(cat)&&!m.bindings[cat]){m.approvalHistory=m.approvalHistory||[];m.approvalHistory.push({cat,revision:m.revision,confirmedAt:m.confirmedAt||'',supersededAt:v3Stamp(),reason:'SM重新提交报价'});}}const result=v8Invalidate(project,cats);if(SKY.selectedByProject)delete SKY.selectedByProject[project];return result;};
const v8Review=skyReview;
function v8ReviewVersion(project,cat){return JSON.stringify(v3ScopeRecords(project,cat).map(([code,m])=>[code,m.revision,m.submittedAt]));}
skyReview=function(){v8Review();const b=document.querySelector('#skyReview [data-sky="commitReview"]');if(b){b.dataset.project=archiveProject;b.dataset.version=v8ReviewVersion(archiveProject,b.dataset.cat);}};
// The guard runs on window capture, ahead of the existing document confirmation handler.
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-sky="commitReview"]');if(!b)return;if(b.dataset.project!==archiveProject||b.dataset.version!==v8ReviewVersion(archiveProject,b.dataset.cat)){e.preventDefault();e.stopImmediatePropagation();document.getElementById('skyReview')?.remove();openClientQuoteView();toast('报价已更新，请核对最新版本后重新确认。');}},true);
const v8ClientHtml=clientQuoteHtml;
clientQuoteHtml=function(){const html=v8ClientHtml(),d=skyData(),records=v3ScopeRecords(archiveProject,d.cat);if(d.all||!records.length)return html;const revisions=records.map(([code,m])=>`<span>${esc(DRAFTS.find(r=>r[0]===code)?.[1]||code)} · V${m.revision}</span>`).join('');const updated=records.some(([,m])=>m.approvalHistory?.length);const note=d.done?skyT('如需调整，请联系 PM。SM 修改报价单并重新提交后，您可再次确认报价。','For changes, contact your PM. You can approve again after your specialist resubmits the draft.'):updated?skyT('SM 已重新提交报价，原确认已失效。请核对本版本并重新确认。','A revised quote has been submitted. Previous approval is superseded; please review and approve this version.'):skyT('请核对最新提交的方案与报价。','Please review the latest submitted proposal.');return html.replace('<section class="sky-products"',`<div class="v8-approval-note"><div>${revisions}</div><p>${note}</p></div><section class="sky-products"`);};
if(V3.client&&clientQuoteOpen())openClientQuoteView();

