function v8PlanRows(){const d=skyData(),all=[];for(const q of d.quotes)for(const g of qCategoryGroups(q).filter(g=>hasDraftForCat(archiveProject,g.cat)))for(const p of g.items){const x=p.slice();x.space=q.space;all.push(x);}return all.map((x,i)=>({x,key:encodeURIComponent([archiveProject,x.space,x[3],x[1],x[6]?.draftCode||'',i].join('|')),number:i+1,pos:V8_PLAN_POS[x.space+'|'+x[3]]||null})).filter(r=>(d.space==='all'||r.x.space===d.space)&&(d.all||r.x[1]===d.cat));}
function v10PlanModel(room,sku,art){const rows=v8PlanRows().filter(r=>r.x.space===room&&r.x[3]===sku);if(!rows.length)return `<g class="v10-plan-reference">${art}</g>`;const selected=rows.some(r=>r.key===V8_PLAN.selected),r=rows.find(r=>r.key===V8_PLAN.selected)||rows[0];return `<g class="v10-plan-object ${selected?'selected':''}" data-v8-plan="product" data-key="${r.key}" data-model="${encodeURIComponent(room+'|'+sku)}" data-sku="${sku}" role="button" tabindex="0" aria-pressed="${selected}" aria-label="${esc(skyProd(r.x[0]))} · ${esc(skySpace(room))} · ${skyMoney(qNum(r.x[2]))}"><title>${esc(skyProd(r.x[0]))} / ${esc(sku)}</title>${art}</g>`;}
