const v12IsVisual=()=>SKY.mode==='render';
const v12Room=()=>skySpaceKey()==='全部空间'?'客厅':skySpaceKey();
function v12Scene(){return V12_SCENES[v12Room()];}
function v12Crop(){return v12Scene()?.crop;}
const v12OldRoomArt=skyRoomArt;
skyRoomArt=function(space,mode='render'){const s=V12_SCENES[space==='全部空间'?'客厅':space];if(!s)return v12OldRoomArt(space,mode);return `<span class="sky-render v12-thumb"><svg viewBox="${s.crop.join(' ')}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="${SKY_ASSETS[s.asset]}" width="${s.width}" height="${s.height}"/></svg></span>`;};
function v12Models(scene){const rows=v8PlanRows();return scene.models.flatMap(m=>{if(SKY.mode==='render'&&m.room!==v12Room())return [];if(SKY.mode==='aerial'&&skySpaceKey()!=='全部空间'&&m.room!==skySpaceKey())return [];const row=rows.find(r=>r.x.space===m.room&&r.x[3]===m.sku);if(!row)return [];return [{...m,row}];});}
function v12Photo(){const s=v12Scene();if(!s)return `<div class="v10-plan-empty">${skyIcon('image')}<strong>${skyT('该空间效果正在完善','This room visualization is being prepared')}</strong><span>${skyT('可先查看报价中的产品配置','Explore the quoted products below')}</span></div>`;return `<svg class="v12-photo-svg" viewBox="${v12Crop().join(' ')}" preserveAspectRatio="xMidYMid meet" role="group" aria-label="${esc(skyT(SKY.mode==='aerial'?'两层空间鸟瞰效果':'空间效果','Design visualization'))}"><defs><clipPath id="v12PhotoCrop"><rect x="${v12Crop()[0]}" y="${v12Crop()[1]}" width="${v12Crop()[2]}" height="${v12Crop()[3]}"/></clipPath></defs><g clip-path="url(#v12PhotoCrop)"><image href="${SKY_ASSETS[s.asset]}" width="${s.width}" height="${s.height}"/><g class="v12-photo-models">${v12Models(s).map(m=>`<path d="${m.path}" class="v12-photo-product" data-v12="product" data-key="${m.row.key}" data-sku="${m.sku}" data-label="${esc(skyProd(m.row.x[0]))}" data-amount="${skyMoney(qNum(m.row.x[2]))}" role="button" tabindex="0" aria-label="${esc(skyProd(m.row.x[0]))} · ${esc(skySpace(m.room))} · ${skyMoney(qNum(m.row.x[2]))}"><title>${esc(skyProd(m.row.x[0]))} · ${skyMoney(qNum(m.row.x[2]))}</title></path>`).join('')}</g></g></svg>`;}
function v12Stage(){const scope=[archiveProject,SKY.mode,skySpaceKey(),QUOTE_UI.clientCat].join('|');if(scope!==V12_VISUAL.scope){V12_VISUAL.scope=scope;V12_VISUAL.zoom=1;}
 const aerial=SKY.mode==='aerial',room=skySpaceKey(),s=v12Scene(),models=s?v12Models(s):[],index=Math.max(0,V12_ROOMS.indexOf(v12Room())),floor=room==='客厅'?'1F':room==='全部空间'?'1F / 2F':'2F';
 return `<section class="v12-visual ${aerial?'v12-aerial':'v12-interior'} ${V12_VISUAL.marked?'v12-marked':''}" aria-label="${skyT(aerial?'空间鸟瞰展示':'空间效果展示',aerial?'Aerial presentation':'Interior presentation')}"><header class="v12-visual-caption"><div><span>${aerial?'SPATIAL OVERVIEW':'INTERIOR COLLECTION'}</span><b>${room==='全部空间'?skyT(aerial?'两层空间 · 全屋总览':'客餐厅 · 空间序章',aerial?'Two levels · Whole home':'Living & dining · Opening view'):esc(skySpace(room))}</b></div><small>${aerial?floor:skyT('自然光 · 材质与细节','Daylight · Materials & details')}</small></header><div class="v12-photo-viewport" tabindex="0" aria-label="${skyT('空间画面，放大后可拖动查看','Design image. Zoom in and drag to explore')}"><div class="v12-photo-paper" style="width:${V12_VISUAL.zoom*100}%;height:${V12_VISUAL.zoom*100}%">${v12Photo()}</div></div><div class="v12-hover-label" hidden></div><footer class="v12-visual-foot"><div><b>${skyT('空间概念效果','Concept visualization')}</b><span>${models.length?skyT('点击画面中的家具，查看报价配置','Select furnishings in the image for quoted details'):skyT('当前筛选暂无可选产品','No selectable products in this filter')}</span></div>${aerial?`<button data-v12="plan">${skyIcon('plan')}${skyT('对照平面图','View floor plan')}</button>`:`<nav aria-label="${skyT('浏览空间效果','Browse interior images')}"><button data-v12="previous" aria-label="${skyT('上一个空间','Previous room')}">‹</button><span>${String(index+1).padStart(2,'0')} <i>/ ${String(V12_ROOMS.length).padStart(2,'0')}</i></span><button data-v12="next" aria-label="${skyT('下一个空间','Next room')}">›</button></nav>`}</footer></section>`;
}
