function v12Controls(){const full=!!document.querySelector('#skyStudio.sky-focus-stage');return `<button class="v12-mark-toggle" data-v12="mark" aria-pressed="${V12_VISUAL.marked}" title="${skyT('显示可选产品轮廓','Show selectable product outlines')}">${skyIcon('grid')}<span>${skyT('产品识别','Products')}</span></button><span class="v10-tool-divider"></span><button data-v12="out" aria-label="${skyT('缩小画面','Zoom out')}" ${V12_VISUAL.zoom<=1?'disabled':''}>−</button><output>${Math.round(V12_VISUAL.zoom*100)}%</output><button data-v12="in" aria-label="${skyT('放大画面','Zoom in')}" ${V12_VISUAL.zoom>=3?'disabled':''}>+</button><button class="v12-fit" data-v12="fit">${skyT('适配','Fit')}</button><button data-sky="lightbox" aria-pressed="${full}" aria-label="${skyT(full?'退出全屏':'全屏查看',full?'Exit expanded view':'Expand image')}" title="${skyT(full?'退出全屏':'全屏查看',full?'Exit expanded view':'Expand image')}">${skyIcon(full?'close':'expand')}</button>`;}
function v12Sync(){const studio=document.getElementById('skyStudio');if(!studio)return;const visual=v12IsVisual(),tools=studio.querySelector('.sky-stage-tools');studio.classList.toggle('v12-studio',visual);if(visual){const c=document.getElementById('skyCanvas');delete c.dataset.sky;c.removeAttribute('role');c.removeAttribute('tabindex');tools.classList.remove('v10-plan-controls');tools.classList.add('v12-controls');tools.innerHTML=v12Controls();v12BindPan();}else if(tools.classList.contains('v12-controls')){tools.classList.remove('v12-controls');if(SKY.mode==='plan')v10PlanSync();else tools.innerHTML=`<button data-sky="resetView" title="${skyT('重置视图','Reset view')}">${skyIcon('rotate')}</button><button data-sky="lightbox" title="${skyT('全屏查看','Expand view')}">${skyIcon('expand')}</button>`;}}
const v12OldRender=skyRenderStage;skyRenderStage=function(){const result=v12OldRender();v12Sync();return result;};
const v12OldOpen=openClientQuoteView;openClientQuoteView=function(){const full=!!document.querySelector('#skyStudio.sky-focus-stage'),result=v12OldOpen();if(full)document.getElementById('skyStudio')?.classList.add('sky-focus-stage');v12Sync();return result;};
const v12OldLightbox=skyLightbox;skyLightbox=function(){if(!v12IsVisual())return v12OldLightbox();const studio=document.getElementById('skyStudio'),full=studio.classList.contains('sky-focus-stage');if(!full)V12_VISUAL.returnFocus=document.activeElement;studio.classList.toggle('sky-focus-stage');v12Sync();studio.querySelector('[data-sky="lightbox"]')?.focus({preventScroll:true});};
function v12Zoom(action){const viewport=document.querySelector('.v12-photo-viewport'),paper=viewport?.querySelector('.v12-photo-paper');if(!paper)return;const before=V12_VISUAL.zoom,next=action==='fit'?1:Math.max(1,Math.min(3,before+(action==='in'?.5:-.5)));const x=(viewport.scrollLeft+viewport.clientWidth/2)/before,y=(viewport.scrollTop+viewport.clientHeight/2)/before;V12_VISUAL.zoom=next;paper.style.width=next*100+'%';paper.style.height=next*100+'%';viewport.scrollLeft=action==='fit'?0:x*next-viewport.clientWidth/2;viewport.scrollTop=action==='fit'?0:y*next-viewport.clientHeight/2;v12Sync();}
function v12Browse(delta){const rooms=skyData().rooms.map(r=>r.space).filter(r=>V12_ROOMS.includes(r));if(!rooms.length)return;const i=rooms.indexOf(v12Room());QUOTE_UI.clientSpace=rooms[(Math.max(0,i)+delta+rooms.length)%rooms.length];SKY.search='';openClientQuoteView();document.querySelector(`[data-v12="${delta>0?'next':'previous'}"]`)?.focus({preventScroll:true});}
function v12BindPan(){const el=document.querySelector('.v12-photo-viewport');if(!el||el.dataset.bound)return;el.dataset.bound='true';let pointer=null;el.addEventListener('pointerdown',e=>{if(e.button===0)pointer={id:e.pointerId,x:e.clientX,y:e.clientY,left:el.scrollLeft,top:el.scrollTop,drag:false,mouse:e.pointerType==='mouse'};});el.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(dx,dy)>6)pointer.drag=true;if(pointer.drag&&pointer.mouse&&V12_VISUAL.zoom>1){el.setPointerCapture(e.pointerId);el.classList.add('is-panning');el.scrollLeft=pointer.left-dx;el.scrollTop=pointer.top-dy;e.preventDefault();}});const end=e=>{if(!pointer||pointer.id!==e.pointerId)return;V12_VISUAL.dragged=pointer.drag;pointer=null;el.classList.remove('is-panning');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);setTimeout(()=>V12_VISUAL.dragged=false,120);};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('click',e=>{if(V12_VISUAL.dragged){e.preventDefault();e.stopPropagation();}},true);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v12]');if(!b)return;e.preventDefault();const a=b.dataset.v12;if(a==='product'){if(V12_VISUAL.dragged)return;v8PlanOpenProduct(b.dataset.key,b);}if(['in','out','fit'].includes(a))v12Zoom(a);if(a==='next'||a==='previous')v12Browse(a==='next'?1:-1);if(a==='mark'){V12_VISUAL.marked=!V12_VISUAL.marked;document.querySelector('.v12-visual')?.classList.toggle('v12-marked',V12_VISUAL.marked);v12Sync();document.querySelector('[data-v12="mark"]')?.focus();}if(a==='plan'){SKY.mode='plan';skyRenderStage();document.querySelector('[data-mode="plan"]')?.focus();}});
function v12Hover(e,show){const p=e.target.closest('.v12-photo-product'),label=document.querySelector('.v12-hover-label');if(!label||!p)return;label.hidden=!show;if(show){label.textContent=p.dataset.label+' · '+p.dataset.amount;}}
document.addEventListener('pointerover',e=>v12Hover(e,true));document.addEventListener('pointerout',e=>v12Hover(e,false));document.addEventListener('focusin',e=>v12Hover(e,true));document.addEventListener('focusout',e=>v12Hover(e,false));
window.addEventListener('keydown',e=>{if(document.querySelector('.q125-history-dialog[open],.q128-history-media-drawer[open]'))return;if(!v12IsVisual()||!clientQuoteOpen())return;const drawer=document.querySelector('#drawer.on'),review=document.getElementById('skyReview');if(drawer||review)return;if(e.key==='Escape'&&document.querySelector('#skyStudio.sky-focus-stage')){e.preventDefault();e.stopImmediatePropagation();document.getElementById('skyStudio').classList.remove('sky-focus-stage');v12Sync();document.querySelector('#skyStudio [data-sky="lightbox"]')?.focus({preventScroll:true});}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.v12-photo-product')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.target.matches('.v12-photo-viewport')&&V12_VISUAL.zoom===1&&SKY.mode==='render'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();v12Browse(e.key==='ArrowRight'?1:-1);}},true);
