/* Drawing polish shares the exact existing selectable furniture groups. */
const v12OriginalDrawing=v8PlanDrawing;
v8PlanDrawing=function(rooms=null){let art=v12OriginalDrawing(rooms);
 art=art.replace('<defs>','<defs><filter id="v12PlanShadow" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="1.4" stdDeviation="1.5" flood-color="#253b43" flood-opacity=".13"/></filter><pattern id="v12PlanFabric" width="3" height="3" patternUnits="userSpaceOnUse"><rect width="3" height="3" fill="#f7f4ed"/><path d="M0 0h3M0 1.5h3" stroke="#d9d4c8" stroke-width=".16"/></pattern>');
 art=art.replace('width="34" height="9" patternUnits="userSpaceOnUse"><rect width="34" height="9" fill="#faf9f5"/><path d="M0 9h34M34 0v9" fill="none" stroke="#e9e7e0" stroke-width=".45"/>','width="52" height="14" patternUnits="userSpaceOnUse"><rect width="52" height="14" fill="#f5f1e8"/><path d="M0 7h52M0 14h52M16 0v7M43 7v7" fill="none" stroke="#d5cfc1" stroke-width=".42"/><path d="M2 3q13 -1 25 0t22 0M2 11q13 -1 25 0t22 0" fill="none" stroke="#e2d9c8" stroke-width=".25"/>');
 art=art.replaceAll('class="v10-plan-object ', 'filter="url(#v12PlanShadow)" class="v10-plan-object ');
 art=art.replaceAll('fill="#faf9f5"','fill="url(#v12PlanFabric)"');
 const detail=(x,y)=>`<g pointer-events="none"><rect x="${x}" y="${y}" width="17" height="12" rx="2" fill="#c7bca4" stroke="#9d957e" stroke-width=".5" transform="rotate(11 ${x+8} ${y+6})"/><path d="M${x+2} ${y+3}h12m-12 3h12" stroke="#e5dece" stroke-width=".5"/></g>`;
 art+=detail(177,282)+detail(276,282)+`<g pointer-events="none" fill="none" stroke="#b9b4a6" stroke-width=".5"><path d="M716 270h61m-61 4h61M660 439h46m-46 4h46"/><path d="M710 307q17 3 35 0t38 0M655 474q25 -4 54 0"/><circle cx="230" cy="361" r="6"/><circle cx="230" cy="361" r="3"/></g>`;
 for(const x of [110,620])art+=`<g pointer-events="none" transform="translate(${x+292} 539)"><path d="M0 0h80M0 -3v6M40 -3v6M80 -3v6" stroke="#73838a" stroke-width=".7"/><path d="M0 0h40" stroke="#73838a" stroke-width="2"/><text x="0" y="14" fill="#80949c" font-size="6">0</text><text x="38" y="14" fill="#80949c" font-size="6">1</text><text x="76" y="14" fill="#80949c" font-size="6">2m</text></g>`;
 return art;
};
if(V3.client&&clientQuoteOpen()&&SKY.mode==='plan')openClientQuoteView();

/* The selected category controls product emphasis without an extra toolbar switch. */
function v13SyncRecognition(){const studio=document.getElementById('skyStudio');if(!studio)return;const tools=studio.querySelector('.sky-stage-tools');tools.querySelector('[data-v13="recognize"]')?.remove();V12_VISUAL.marked=!!QUOTE_UI.clientCat&&QUOTE_UI.clientCat!=='全部品类';studio.classList.toggle('v13-recognition',V12_VISUAL.marked);tools.classList.remove('v13-recognition-tools');studio.querySelector('.v4-model')?._v4?.recognize(V12_VISUAL.marked);}
const v13OldVisualSync=v12Sync;v12Sync=function(){v13OldVisualSync();v13SyncRecognition();};
const v13OldPlanSync=v10PlanSync;v10PlanSync=function(){v13OldPlanSync();v13SyncRecognition();};
if(SKY.mode==='aerial')SKY.mode='render';
if(V3.client&&clientQuoteOpen())openClientQuoteView();

/* Quote-first workspace. All new records remain local prototype data. */
const V15={view:'work',filter:'all',origin:'home',editing:'',products:wkRead('crm-products-v15',[])};
if(!Array.isArray(V15.products))V15.products=[];
function v15Product(p){return {...p,artIndex:-1,temporary:true,space:p.space||'未确定空间'};}
function v15SyncCatalog(){for(const raw of V15.products){const p=v15Product(raw),i=WK_CATALOG.findIndex(x=>x.sku===p.sku);if(i<0)WK_CATALOG.push(p);else WK_CATALOG[i]=p;}document.getElementById('pimsFrame')?.contentWindow?.postMessage({type:'v15Catalog',products:V15.products},'*');}
v15SyncCatalog();
WK.cart=wkRead('crm-sky-cart-v2',[]).filter(x=>WK_CATALOG.some(p=>p.sku===x.sku)&&x.qty>0);
function v15Rows(d){return (d?.spaces||[]).flatMap(s=>(s.products||[]).map(p=>({...p,space:s.name})));}
function v15Drafts(){return DRAFTS.slice().sort((a,b)=>String(b[11]||'').localeCompare(String(a[11]||'')));}
function v15Records(){return Object.entries(V3.meta).filter(([,m])=>m.submitted&&m.active!==false);}
function v15Pending(){return V15.products.filter(p=>p.status!=='ready');}
function v15ProjectName(code){return PROJECTS.find(p=>p[0]===code)?.[1]||'尚未关联项目';}
function v15Empty(title,copy,button=''){return `<div class="v15-empty"><b>${esc(title)}</b><p>${esc(copy)}</p>${button}</div>`;}
function v15Button(a,label,extra='',primary=false){return `<button class="wk-btn ${primary?'primary':''}" data-v15="${a}" ${extra}>${label}</button>`;}
function v15State(code){const m=v3Meta(code);return v3HasUnsubmitted(code)?'<span class="v15-pill amber">有未提交修改</span>':m.submitted?v3StateHtml(m):'<span class="v15-pill">尚未提交</span>';}
function v15Header(title,sub,action=''){return `<div class="v15-section-head"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>`;}
function v15DraftSection(){const list=v15Drafts().filter(r=>{const m=v3Meta(r[0]);return V15.filter==='all'||V15.filter==='editing'&&(!m.submitted||v3HasUnsubmitted(r[0]))||V15.filter==='submitted'&&v3Status(m)==='已提交';}).slice(0,4);return `<section class="v15-panel">${v15Header('继续推进报价','从最近的方案接着做，或复制一份开始新报价。','<button class="v15-link" data-v15="drafts">全部报价单 '+skyIcon('arrow')+'</button>')}<div class="v15-tabs" role="group" aria-label="报价单筛选">${[['all','最近更新'],['editing','待编辑 / 提交'],['submitted','待客户确认']].map(([k,l])=>`<button data-v15="draftFilter" data-filter="${k}" class="${V15.filter===k?'on':''}" aria-pressed="${V15.filter===k}">${l}</button>`).join('')}</div><div class="v15-draft-list">${list.map(r=>{const m=v3Meta(r[0]),d=DRAFT_DATA[r[0]],detail=v15Rows(d).length,locked=Object.keys(m.bindings||{}).length>0,preview=m.submitted&&!v3HasUnsubmitted(r[0]);return `<article class="v15-draft"><span class="v15-file-icon">${skyIcon('file')}</span><div class="v15-draft-copy"><div><b>${esc(r[1])}</b>${v15State(r[0])}</div><p>${esc(v15ProjectName(m.project||d?.project))}<span>·</span>${esc((m.categories||[]).join(' / ')||'未选品类')}</p><small>${esc(r[0])} · ${detail?detail+' 项产品明细':'历史记录无产品明细'} · ${esc(v5ShortDate(r[11]))}</small></div><div class="v15-draft-acts">${preview?v15Button('preview','客户预览',`data-project="${esc(m.project)}"`,true):v15Button('editDraft',locked?'查看报价单':'继续编辑',`data-code="${r[0]}"`,true)}${v15Button('copyOne','复制报价单',`data-code="${r[0]}" ${!detail?'disabled title="此历史记录无明细，不能复制"':''}`)}${preview&&!locked?`<button class="v15-link" data-v15="editDraft" data-code="${r[0]}">编辑</button>`:''}</div></article>`;}).join('')||v15Empty('当前没有此类报价单','可以新建报价，或切换筛选查看其他方案。',v15Button('new','新建报价'))}</div></section>`;}
function v15TaskSection(){const list=visibleTodos().filter(t=>t.status==='待处理').slice().sort((a,b)=>parseTodoTime(a.time)-parseTodoTime(b.time)).slice(0,4);return `<section class="v15-panel">${v15Header('待办与交接','按到达时间排序，优先查看停留较久的事项。','<button class="v15-link" data-v3="homeTodos">待办中心 '+skyIcon('arrow')+'</button>')}<div class="v15-task-list">${list.map(t=>`<article class="v15-task"><i></i><div><b>${esc(todoSubject(t))}</b><p>${esc(t.type)} · ${esc(t.owner||'待分配')} · ${esc(v5ShortDate(t.time))}</p></div><button class="v15-link" data-v15="task" data-id="${esc(t.id)}">处理 ${skyIcon('arrow')}</button></article>`).join('')||v15Empty('暂无待处理事项','新的业务交接将在这里出现。')}</div></section>`;}
function v15ClientSection(){const groups=[...new Set(v15Records().map(([,m])=>m.project))];return `<section class="v15-panel">${v15Header('客户方案','已提交报价可直接进入客户预览。')}<div class="v15-client-list">${groups.slice(0,3).map(project=>{const records=v15Records().filter(([,m])=>m.project===project),cats=[...new Set(records.flatMap(([,m])=>m.categories))],done=cats.filter(c=>records.filter(([,m])=>m.categories.includes(c)).every(([,m])=>m.confirmedCats.includes(c)));return `<article><div class="v15-client-title">${skyIcon('home')}<b>${esc(v15ProjectName(project))}</b></div><p>${cats.length} 个已提交品类 · ${done.length} 个已确认</p><div class="v15-client-progress"><i style="width:${cats.length?done.length/cats.length*100:0}%"></i></div><div class="v15-client-actions">${v15Button('preview','打开客户预览',`data-project="${esc(project)}"`,true)}<button class="v15-link" data-v15="board" data-project="${esc(project)}">报价总览</button></div></article>`;}).join('')||v15Empty('等待第一份报价提交','提交后即可在这里核对客户将看到的方案。')}</div><div class="v15-panel-note">PM 核对方案后，将对客链接发送至 SCRM 项目群。</div></section>`;}
function v15MissingSection(){const list=v15Pending();return `<section class="v15-panel">${v15Header('产品资料协作',`${list.length} 款产品待完善 · 报价可继续推进`,'<button class="v15-link" data-v15="productList">查看全部</button>')}${list.slice(0,3).map(p=>`<div class="v15-product-task"><span>${skyIcon('grid')}</span><div><b>${esc(p.name)}</b><small>${esc(p.sku)} · ${esc(p.cat)}</small></div><button class="v15-link" data-v15="editProduct" data-sku="${esc(p.sku)}">完善</button></div>`).join('')||v15Empty('产品库没找到？','在线新建待完善产品，先完成本次选品报价。')}<div class="v15-panel-foot">${v15Button('newProduct','＋ 新建待完善产品')}</div></section>`;}
function v15Insights(){const map=new Map();for(const [code,m] of v15Records())for(const p of v15Rows(m.submitted)){if(!p.sku)continue;const key=[p.cat,p.sku,p.unit||'件',p.productSnapshot?.spec||'',p.productSnapshot?.material||''].join('|');const x=map.get(key)||{sku:p.sku,name:p.name,cat:p.cat,spec:p.productSnapshot?.spec||'',material:p.productSnapshot?.material||'',qty:0,amount:0,confirmed:0,projects:new Set(),unit:p.unit||'件'};x.qty+=Number(p.qty)||0;x.amount+=Number(p.amt)||0;if(m.confirmedCats.includes(p.cat))x.confirmed+=Number(p.qty)||0;x.projects.add(m.project);map.set(key,x);}const list=[...map.values()].sort((a,b)=>b.amount-a.amount);return `<div class="v15-insight-top"><div><small>已报价产品</small><strong>${new Set(list.map(p=>p.cat+'|'+p.sku)).size}<em>款</em></strong><p>按品类与产品编码去重</p></div><div><small>有已提交报价的项目</small><strong>${new Set(v15Records().map(([,m])=>m.project)).size}<em>个</em></strong><p>采用当前有效提交版本</p></div><div><small>待完善产品</small><strong>${v15Pending().length}<em>款</em></strong><p>进入资料协作队列</p></div><div class="v15-unavailable"><small>实际采购</small><strong>—</strong><p>采购数据尚未接入</p></div></div><section class="v15-panel">${v15Header('产品报价分布','采用最新有效提交版本；同款不同规格、材质或单位分行呈现。',v15Button('catalog','进入产品库'))}<div class="v15-table-wrap"><table class="v15-product-table"><thead><tr><th>产品 / 编码</th><th>品类</th><th>关联项目</th><th>报价数量</th><th>已确认数量</th><th>报价金额 · CNY</th></tr></thead><tbody>${list.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.sku)}</small>${p.spec?`<small>${esc(p.spec)}${p.material?' · '+esc(p.material):''}</small>`:''}</td><td>${esc(p.cat)}</td><td>${p.projects.size}</td><td>${p.qty.toLocaleString()} ${esc(p.unit)}</td><td>${p.confirmed.toLocaleString()} ${esc(p.unit)}</td><td>${qMoney(p.amount)}</td></tr>`).join('')||'<tr><td colspan="6">暂无已提交的产品报价</td></tr>'}</tbody></table></div><div class="v15-panel-note">当前工作空间的报价数据，不代表成交或实际采购。未生成线上记录的线下业务不在本表中。</div></section><div class="v15-insight-foot">${v15MissingSection()}<section class="v15-panel v15-measure-note">${skyIcon('chart')}<h2>先把业务记录完整，再衡量效率</h2><p>报价时效、线上首发率与采购分析，需要完整的业务事件和采购记录。本页暂不显示未经记录支持的采用率或绩效排名。</p><button class="v15-link" data-v3="homeTodos">查看实际待办 ${skyIcon('arrow')}</button></section></div>`;}
pageHome=function(){const pending=visibleTodos().filter(t=>t.status==='待处理').length,editing=v15Drafts().filter(r=>!v3Meta(r[0]).submitted||v3HasUnsubmitted(r[0])).length,waiting=new Set(v15Records().flatMap(([,m])=>m.categories.filter(c=>!m.confirmedCats.includes(c)).map(c=>m.project+'|'+c))).size;return `<div class="v15-workbench"><header class="v15-heading"><div><span>工作空间 / 敬城 CRM</span><h1>工作台</h1><p>${esc(V3.user)}，${new Date().getHours()<12?'上午':new Date().getHours()<18?'下午':'晚上'}好。继续一份报价，推进一次交接。</p></div><div class="v15-heading-end"><small>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</small><button class="wk-btn" data-v3="homeTodos">${skyIcon('check')}待办中心 <b>${pending}</b></button></div></header><div class="v15-launch">${[['new','file','新建空间报价','选择项目，进入报价模板'],['copy','rotate','复制历史报价单','沿用方案，调整本次需求'],['catalog','grid','产品库选品','查找产品，带入报价资料'],['clients','home','客户预览','核对方案，衔接客户确认']].map(([a,i,h,p],n)=>`<button data-v15="${a}" class="v15-launch-item ${n===0?'primary':''}"><span class="v15-launch-icon">${skyIcon(i)}</span><div><b>${h}</b><small>${p}</small></div>${skyIcon('arrow')}</button>`).join('')}</div><div class="v15-view-bar"><div role="group" aria-label="工作台视图">${[['work','工作推进'],['insights','产品洞察']].map(([k,l])=>`<button data-v15="view" data-view="${k}" class="${V15.view===k?'on':''}" aria-pressed="${V15.view===k}">${l}</button>`).join('')}</div><span>当前工作空间 · ${V15.view==='work'?'报价与业务交接':'已提交报价统计'}</span></div>${V15.view==='insights'?v15Insights():`<div class="v15-metrics">${[['editing','待编辑 / 提交',editing,'份报价单'],['waiting','待客户确认',waiting,'个品类报价'],['todos','待处理事项',pending,'项业务交接'],['products','待完善产品',v15Pending().length,'款资料记录']].map(([a,l,n,s])=>`<button data-v15="metric" data-metric="${a}"><span>${l}${skyIcon('arrow')}</span><div><b>${n}</b><small>${s}</small></div></button>`).join('')}</div><div class="v15-work-grid"><main>${v15DraftSection()}${v15TaskSection()}</main><aside>${v15ClientSection()}${v15MissingSection()}</aside></div>`}</div>`;};
RENDER.home=pageHome;
function v15NewQuote(){v3Dialog('新建空间报价',`<div class="v15-dialog-intro">关联项目后进入报价模板，产品资料可从侧边栏选入。</div><form id="v15NewQuoteForm" class="v15-form"><label>关联项目<select name="project" required>${PROJECTS.map(p=>`<option value="${esc(p[0])}" ${p[0]===archiveProject?'selected':''}>${esc(p[1])} · ${esc(p[0])}</option>`).join('')}</select></label><label>报价品类<select name="cat">${Object.keys(V3.owners).map(c=>`<option${c==='卫浴'?' selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="wide">报价单名称<input name="name" maxlength="80" placeholder="可不填，自动使用项目与品类名称"></label><p class="wide v15-form-note">复制历史报价单可沿用已有产品与空间；正式提交前请核对本次规格和价格。</p></form>`,`<button class="wk-btn" data-v3="closeDialog">取消</button>${v15Button('startQuote','进入报价编辑','',true)}`);}
function v15StartQuote(){const f=document.getElementById('v15NewQuoteForm');if(!f?.reportValidity())return;const d=Object.fromEntries(new FormData(f)),p=PROJECTS.find(x=>x[0]===d.project);if(!p)return;v3CloseDialog();archiveProject=p[0];draftEditorCtx={project:p[0],customer:p[7],tpl:d.cat,name:d.name.trim()||p[1]+'-'+d.cat+'报价',spaces:['未确定空间']};pageEl('draftEditor')?.remove();openPage('draftEditor');}
function v15CopyPicker(){v3Dialog('复制历史报价单',`<p class="v15-dialog-intro">沿用产品与空间明细，新报价单不会继承客户确认或订单绑定。</p><label class="v15-search">${skyIcon('search')}<input id="v15CopySearch" placeholder="搜索报价单名称、项目或品类"></label><div id="v15CopyResults">${v15CopyResults('')}</div>`);document.getElementById('v15CopySearch').focus();}
function v15CopyResults(q){return v15Drafts().filter(r=>(r[1]+' '+r[0]+' '+v15ProjectName(v3Meta(r[0]).project)+' '+v3Meta(r[0]).categories.join(' ')).toLowerCase().includes(q.toLowerCase())).map(r=>{const d=DRAFT_DATA[r[0]]||v3Meta(r[0]).submitted,n=v15Rows(d).length;return `<article class="v15-pick-row"><div><b>${esc(r[1])}</b><p>${esc(r[0])} · ${n?n+' 项产品':'历史记录无明细'}</p></div>${v15Button('copyOne','复制并编辑',`data-code="${r[0]}" ${n?'':'disabled'}`)}</article>`;}).join('')||v15Empty('没有匹配的报价单','换一个名称或品类搜索。');}
function v15ClientPicker(){v3Dialog('选择客户方案',v15ClientSection());}
function v15Preview(project){if(!v15Records().some(([,m])=>m.project===project))return toast('请先提交该项目的报价');v3CloseDialog();archiveProject=project;QUOTE_UI.clientSpace='all';QUOTE_UI.clientCat='全部品类';QUOTE_UI.clientSelected={};SKY.mode='plan';openPage('board');openModal('clientFx');}
// Keep a confirmed custom rate when reopening; changing currency still selects its default rate.
const v35BindClientFx=bindClientFx;
bindClientFx=function(){const rate=document.getElementById('clientFxRate');if(rate)rate.dataset.touched='1';return v35BindClientFx();};
function v15ShareInfo(project){v3Dialog('对客交付',`<div class="v15-delivery"><span>${skyIcon('home')}</span><h3>${esc(v15ProjectName(project))}</h3><p>PM 核对提交版本 → 复制对客链接 → 发送至 SCRM 项目群 → 客户查看并确认。</p><div class="v15-delivery-note">外部分享尚未开通。当前可体验本地客户预览；正式对客链接需要接入发布服务。</div></div>`,`<button class="wk-btn" data-v3="closeDialog">关闭</button>${v15Button('preview','查看客户预览',`data-project="${esc(project)}"`,true)}`);}
const v15BoardBase=pageBoard;
const v15DraftPageBase=pageDrafts;pageDrafts=function(){const box=document.createElement('div');box.innerHTML=v15DraftPageBase();const headers=box.querySelectorAll('.v3-draft-table thead th');if(headers[9])headers[9].textContent='产品明细';if(headers[10])headers[10].textContent='待完善产品';return box.innerHTML;};RENDER.drafts=pageDrafts;
const v15DraftBodyBase=v3DraftBody;v3DraftBody=function(){const table=document.createElement('table');table.innerHTML='<tbody>'+v15DraftBodyBase()+'</tbody>';for(const tr of table.querySelectorAll('tbody tr')){const code=tr.querySelector('[data-code]')?.dataset.code;if(!code)continue;const m=v3Meta(code),d=DRAFT_DATA[code]||m.submitted,items=v15Rows(d),pending=new Set(items.filter(p=>V15.products.some(x=>x.sku===p.sku&&x.status!=='ready')).map(p=>p.sku));if(tr.cells[9])tr.cells[9].textContent=items.length?items.length+' 项':'—';if(tr.cells[10])tr.cells[10].textContent=items.length?pending.size+' 款':'—';}return table.querySelector('tbody').innerHTML;};
pageBoard=function(){const box=document.createElement('div');box.innerHTML=v15BoardBase();const bar=box.querySelector('.quote-topbar');if(bar){const copy=bar.querySelector('[data-act="copyQuoteLink"]');if(copy){copy.removeAttribute('data-act');copy.dataset.v15='share';copy.dataset.project=archiveProject;copy.textContent='复制链接';}const link=bar.querySelector('.quote-link-top');if(link)link.textContent='已提交版本 · 客户方案';const config=bar.querySelector('[data-act="modal:clientFx"]');if(config)config.outerHTML=v15Button('preview','客户预览',`data-project="${esc(archiveProject)}"`,true);}return box.innerHTML;};RENDER.board=pageBoard;
const v15SubmitBase=applyDraftSaved;
applyDraftSaved=function(d){const before=new Map(Object.entries(V3.meta).map(([code,m])=>[code,m.submitted]));const result=v15SubmitBase(d);const code=V3.lastCode,m=V3.meta[code];if(m?.submitted&&m.submitted!==before.get(code)&&m.project===d.project&&pageKind(page)==='drafts'){v3Dialog('报价已提交',`<div class="v15-delivery"><span>${skyIcon('check')}</span><h3>${esc(DRAFTS.find(r=>r[0]===code)?.[1]||d.name)}</h3><p>${esc(v15ProjectName(m.project))} · V${m.revision} · ${qMoney(v3DraftAmount(m.submitted))}</p><div class="v15-delivery-note">同一份报价单已保留，并同步报价总览。现在可以核对客户预览，由 PM 继续对客沟通。</div><p class="v15-form-note">${m.categories.map(esc).join(' / ')} · 客户确认后进入订单环节</p></div>`,`${v15Button('home','返回工作台')}${v15Button('editDraft','继续编辑',`data-code="${esc(code)}"`)}${v15Button('preview','查看客户预览',`data-project="${esc(m.project)}"`,true)}`);}return result;};
function v15ProductForm(origin='home',sku=''){V15.origin=origin;V15.editing=sku;const p=V15.products.find(x=>x.sku===sku)||{};V15.image=p.image||'';V15.imageReading=false;const field=(name,label,value,required=false,type='text')=>`<label>${label}${required?' <em>*</em>':''}<input name="${name}" type="${type}" value="${esc(value??'')}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':'maxlength="140"'}></label>`;v3Dialog(sku?'完善产品资料':'新建待完善产品',`<p class="v15-dialog-intro">记录本次报价所需资料，生成独立产品编码后即可选入报价。详细资料可在产品资料协作中继续完善。</p><form id="v15ProductForm" class="v15-form">${field('name','产品名称',p.name,true)}<label>品类 <em>*</em><select name="cat" required>${Object.keys(V3.owners).map(c=>`<option ${c===(p.cat||'家具')?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('spec','规格 / 配置',p.spec,true)}${field('material','材质',p.material)}${field('unit','计价单位',p.unit||'件',true)}${field('price','本次参考单价 · CNY',p.price,true,'number')}${field('source','供应商 / 产品来源',p.source)}${field('note','备注',p.note)}<label class="wide v15-file-field">产品图片（可选，PNG / JPG / WebP，1 MB 内）<input type="file" id="v15ProductImage" accept="image/png,image/jpeg,image/webp"><span id="v15ImageState">${p.image?'已有产品图片，选择文件可替换':'使用真实产品图片，避免用其他产品代替。'}</span></label>${sku?`<label class="wide v15-check"><input type="checkbox" name="complete" ${p.status==='ready'?'checked':''}>资料已完善（需补齐材质与产品来源）</label>`:''}<p class="wide v15-form-note">提交时检查同名同规格记录，避免重复建档。已有报价保留当时的产品与价格信息。</p><div id="v15ProductError" class="wide v15-error" role="alert"></div></form>`,`<button class="wk-btn" data-v3="closeDialog">取消</button>${v15Button('saveProduct',sku?'保存资料':origin==='editor'?'创建并加入报价':origin==='mall'?'创建并加入选品清单':'创建产品','',true)}`);document.querySelector('#v15ProductForm [name="name"]').focus();}
async function v15ImageFile(input){const file=input.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1024*1024){input.value='';document.getElementById('v15ProductError').textContent='请选择 1 MB 内的 PNG、JPG 或 WebP 图片。';return;}V15.imageReading=true;try{const value=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});if(!input.isConnected)return;V15.image=value;document.getElementById('v15ImageState').textContent='已选择：'+file.name;document.getElementById('v15ProductError').textContent='';}catch(e){if(document.getElementById('v15ProductError'))document.getElementById('v15ProductError').textContent='图片读取失败，请重新选择。';}finally{if(input.isConnected)V15.imageReading=false;}}
function v15SaveProduct(){const form=document.getElementById('v15ProductForm');if(!form?.reportValidity())return;const err=document.getElementById('v15ProductError');if(V15.imageReading){err.textContent='图片正在读取，请稍候。';return;}const data=Object.fromEntries(new FormData(form));for(const k of ['name','spec','material','unit','source','note'])data[k]=String(data[k]||'').trim();if(!data.name||!data.spec||!data.unit){err.textContent='请填写产品名称、规格和单位。';return;}if(!Number.isFinite(Number(data.price))||Number(data.price)<0){err.textContent='请输入有效单价。';return;}const duplicate=V15.products.find(p=>p.sku!==V15.editing&&p.name===data.name&&p.spec===data.spec&&p.cat===data.cat);if(duplicate){err.textContent='已有同名同规格产品：'+duplicate.sku+'，请从产品库选入。';return;}if(data.complete&&(!data.material||!data.source)){err.textContent='标记资料已完善前，请补齐材质与供应商 / 产品来源。';return;}const old=V15.products.find(p=>p.sku===V15.editing);let sku=old?.sku;if(!sku){const prefix='TMP-'+v3Stamp().slice(0,10).replaceAll('-','')+'-';let n=1;while(WK_CATALOG.some(p=>p.sku===prefix+String(n).padStart(3,'0')))n++;sku=prefix+String(n).padStart(3,'0');}const record={sku,name:data.name,cat:data.cat,spec:data.spec,material:data.material,unit:data.unit,price:Number(data.price),source:data.source,note:data.note,image:V15.image,status:data.complete?'ready':'pending',createdAt:old?.createdAt||v3Stamp(),updatedAt:v3Stamp(),createdBy:old?.createdBy||V3.user};const next=V15.products.filter(p=>p.sku!==sku).concat(record);if(!wkWrite('crm-products-v15',next)){err.textContent='产品未能保存，请减小图片或检查浏览器存储后重试。';return;}V15.products=next;v15SyncCatalog();const origin=V15.origin;v3CloseDialog();markPagesDirty();if(origin==='editor'){document.getElementById('pimsFrame')?.contentWindow?.postMessage({type:'v15ProductCreated',product:record},'*');}else if(origin==='mall'){wkAdd(sku);wkUpdateCatalog();}else if(origin==='list'){v15ProductList();}else if(pageKind(page)==='home')openPage('home');toast(old?'产品资料已更新，历史报价保持不变':'已建立 '+sku+'，可继续选品报价');}
function v15ProductList(){v3Dialog('产品资料协作',`<p class="v15-dialog-intro">${v15Pending().length} 款待完善 / ${V15.products.length} 款在线新增产品。资料已完善不代表完成供应商审核。</p>${V15.products.map(p=>`<article class="v15-pick-row"><div><b>${esc(p.name)} <span class="v15-pill ${p.status==='ready'?'':'amber'}">${p.status==='ready'?'资料已完善':'待完善'}</span></b><p>${esc(p.sku)} · ${esc(p.spec)} · ${esc(p.cat)}</p></div>${v15Button('editProduct','完善资料',`data-sku="${esc(p.sku)}" data-origin="list"`)}</article>`).join('')||v15Empty('暂无新增产品','缺品时可在线建立产品记录，关联后续报价。')}`,`<button class="wk-btn" data-v3="closeDialog">关闭</button>${v15Button('newProduct','新建待完善产品','data-origin="list"',true)}`);}
const v15ArtBase=wkArt;wkArt=function(p){return p?.image?`<img class="v15-real-product" src="${esc(p.image)}" alt="${esc(p.name)}">`:v15ArtBase(p);};
const v15MallBase=pageMall;pageMall=function(){const box=document.createElement('div');box.innerHTML=v15MallBase();box.querySelector('.wk-catalog-tools')?.insertAdjacentHTML('beforeend',v15Button('newProduct','找不到？新增产品','data-origin="mall"'));return box.innerHTML;};RENDER.mall=pageMall;
const v15ProductCardsBase=wkProductCards;wkProductCards=function(){const box=document.createElement('div');box.innerHTML=v15ProductCardsBase();box.querySelectorAll('.wk-product').forEach(card=>{const sku=card.querySelector('[data-sku]')?.dataset.sku,p=V15.products.find(p=>p.sku===sku);if(p)card.querySelector('.wk-product-body>small').textContent=p.cat+' / '+(p.status==='ready'?'资料已完善':'待完善产品');});return box.innerHTML;};
function v15AttachSnapshots(code){const m=V3.meta[code];if(!m?.submitted)return;for(const q of projectQuoteRows(m.project)){const source=m.submitted.spaces.find(s=>s.name===q.space);if(!source)continue;for(const row of q.products){if(row[6]?.draftCode!==code)continue;const p=source.products.find(p=>p.sku===row[3]&&p.cat===row[1]);if(p?.productSnapshot)row[6]={...row[6],productSnapshot:v3Copy(p.productSnapshot),unit:p.unit||p.productSnapshot.unit};}}}
const v15RebuildBase=v3RebuildDraftQuotes;v3RebuildDraftQuotes=function(code){const result=v15RebuildBase(code);v15AttachSnapshots(code);return result;};
for(const [code,m] of v15Records())if(v15Rows(m.submitted).some(p=>p.productSnapshot))v15AttachSnapshots(code);
function v15QuoteSnapshot(sku,space,cat,key){if(key&&typeof v8PlanRows==='function'){const row=v8PlanRows().find(r=>r.key===key);if(row?.x[6]?.productSnapshot)return row.x[6].productSnapshot;}for(const q of projectQuoteRows(archiveProject)){if(space&&space!=='全部空间'&&q.space!==space)continue;const row=q.products.find(p=>p[3]===sku&&(!cat||cat===p[1])&&p[6]?.productSnapshot);if(row)return row[6].productSnapshot;}return null;}
const v15QuoteImageBase=quoteImgSvg;quoteImgSvg=function(sku){if(!sku?.startsWith('TMP-'))return v15QuoteImageBase(sku);const p=v15QuoteSnapshot(sku);return p?.image?`<img class="v15-real-product" src="${esc(p.image)}" alt="${esc(p.name)}">`:`<span class="wk-no-image">${skyIcon('image')}<span>${skyT('图片待补充','Image pending')}</span></span>`;};
const v15ClientProductBase=skyProductDetails;skyProductDetails=function(t){v15ClientProductBase(t);const p=v15QuoteSnapshot(t.dataset.sku,t.dataset.space,t.dataset.cat,t.dataset.key);if(!p)return;const d=t.dataset,grid=document.querySelector('#dBody .qpd-grid');if(grid)grid.innerHTML=[[skyT('产品编号','SKU'),d.sku],[skyT('数量','Quantity'),d.qty+' '+p.unit],[skyT('单价','Unit price'),skyMoney(qNum(d.unit))],[skyT('小计','Subtotal'),skyMoney(qNum(d.price))],[skyT('报价规格','Quoted specification'),p.spec],[skyT('材质','Material'),p.material||skyT('待确认','To be confirmed')]].map(([k,v])=>`<span>${k}</span><b>${esc(v)}</b>`).join('');const hero=document.querySelector('#dBody .qpd-hero');if(hero)hero.innerHTML=p.image?`<img class="v15-real-product" src="${esc(p.image)}" alt="${esc(p.name)}">`:quoteImgSvg(d.sku);const note=document.querySelector('#dBody .qpd>p');if(note)note.textContent=skyT('以上为本次方案中所报的规格与材质，请核对后确认。','Please review the specification and material quoted in this proposal before approval.');};
const v15DetailBase=wkShowDetail;wkShowDetail=function(sku){const p=V15.products.find(p=>p.sku===sku);if(!p)return v15DetailBase(sku);v3Dialog(p.name,`<div class="v15-product-detail"><div>${wkArt(v15Product(p))}</div><section><span class="v15-pill ${p.status==='ready'?'':'amber'}">${p.status==='ready'?'资料已完善':'待完善产品'}</span><h3>${esc(p.name)}</h3><p>${esc(p.sku)} · ${esc(p.cat)}</p><strong>${qMoney(p.price)} / ${esc(p.unit)}</strong><dl><dt>规格</dt><dd>${esc(p.spec)}</dd><dt>材质</dt><dd>${esc(p.material||'待完善')}</dd><dt>来源</dt><dd>${esc(p.source||'待完善')}</dd></dl></section></div>`,`<button class="wk-btn" data-v3="closeDialog">关闭</button><button class="wk-btn primary" data-wk="add" data-sku="${esc(sku)}">添加至${esc(WK.room)}</button>`);};
const v15HandleBase=handleAct;handleAct=function(t){if(t?.dataset?.act==='go:draftEditor'&&!t.dataset.draft)return v15NewQuote();if(t?.dataset?.act==='copyQuoteLink')return v15ShareInfo(archiveProject);return v15HandleBase(t);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v15]');if(!b||b.disabled)return;const a=b.dataset.v15;if(a==='view'){V15.view=b.dataset.view;openPage('home');}if(a==='new')v15NewQuote();if(a==='startQuote')v15StartQuote();if(a==='copy')v15CopyPicker();if(a==='copyOne')v3CopyDraft(b.dataset.code);if(a==='editDraft'){v3CloseDialog();v125DraftLocked(v3Meta(b.dataset.code))?v3DraftDetail(b.dataset.code):openDraftEditor(b.dataset.code);}if(a==='catalog')openPage('mall');if(a==='clients')v15ClientPicker();if(a==='preview')v15Preview(b.dataset.project);if(a==='share')v15ShareInfo(b.dataset.project||archiveProject);if(a==='board'){v3CloseDialog();archiveProject=b.dataset.project;openPage('board');}if(a==='home'){v3CloseDialog();openPage('home');}if(a==='drafts'){V3.filter='全部';V3.search='';openPage('drafts');}if(a==='draftFilter'){V15.filter=b.dataset.filter;openPage('home');}if(a==='metric'){const m=b.dataset.metric;if(m==='products')v15ProductList();else if(m==='todos')document.querySelector('[data-v3="homeTodos"]')?.click();else{V15.filter=m==='editing'?'editing':'submitted';openPage('home');}}if(a==='task'){const t=TODOS.find(t=>t.id===b.dataset.id);if(!t)return;const actions=todoActs(t),main=actions.find(x=>x.act&&!/查看|总览|档案|轨迹|驳回|结束|详情/.test(x.t||''));if(main){const el=document.createElement('div');el.innerHTML=`<button data-act="${esc(main.act)}" ${main.extra||''}></button>`;handleAct(el.firstElementChild);}else{todoStatus='待处理';todoFilter=t.type;todoSearch=t.id;todoProject='';todoQuick='';const old=document.getElementById('todoSearchInp');if(old)old.value=todoSearch;openPage('todos');}}if(a==='newProduct')v15ProductForm(b.dataset.origin||'home');if(a==='editProduct')v15ProductForm(b.dataset.origin||'home',b.dataset.sku);if(a==='saveProduct')v15SaveProduct();if(a==='productList')v15ProductList();});
document.addEventListener('input',e=>{if(e.target.id==='v15CopySearch')document.getElementById('v15CopyResults').innerHTML=v15CopyResults(e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='v15ProductImage')v15ImageFile(e.target);});
document.addEventListener('submit',e=>{if(e.target.id==='v15ProductForm'){e.preventDefault();v15SaveProduct();}if(e.target.id==='v15NewQuoteForm'){e.preventDefault();v15StartQuote();}});
window.addEventListener('message',e=>{const f=document.getElementById('pimsFrame');if(!f||e.source!==f.contentWindow||!e.data)return;if(e.data.type==='v15CreateProduct')v15ProductForm('editor');});
if(!V3.client&&pageKind(page)==='home')openPage('home');

/* Role-aware overview. Role preview changes presentation, never account permissions. */
const V16_ROLES={
 business:{name:'业务 · 客户负责人',short:'客户经营',mission:'把客户需求交接清楚，让每一次跟进都有后续。',types:['客户待办','公海跟进'],default:'覃文康(Chum)'},
 designer:{name:'设计师',short:'设计协同',mission:'读懂需求，交付可落地的设计，衔接项目立项。',types:['设计待办','设计单'],default:'林嘉怡(中东设计师)'},
 pm:{name:'PM · 项目经理',short:'项目统筹',mission:'统筹设计、品类方案与客户沟通，把握项目下一步。',types:['创建项目待办','项目待办','收款待办'],default:'叶志松(Andy Ye)'},
 sm:{name:'SM · 品类方案经理',short:'品类交付',mission:'从承接商机到报价、转单与备货，推进负责的品类。',types:['确认商机','报价待办','订单待办','备货待办'],default:'林晓'},
 library:{name:'产品资料协作',short:'产品资料',mission:'及时补齐报价缺品，让选品资料持续沉淀。',types:[],default:''},
 finance:{name:'财务协作',short:'收款核对',mission:'了解订单与 CRM 收款记录，为财务核对提供依据。',types:[],default:''},
 manager:{name:'管理者',short:'团队全局',mission:'看清业务停在哪里、由谁推进，让跨角色协作有序发生。',types:['邀请函审核'],default:'王主管'}
};
const V16={role:'pm',owner:'叶志松(Andy Ye)',tab:'mine',search:''};
function v16Owners(role=V16.role){const r=V16_ROLES[role];let names=TODOS.filter(t=>r.types.includes(t.type)).map(t=>t.owner);if(role==='business')names.push(...CUSTOMERS.map(c=>c[4]));if(role==='pm')names.push(...PROJECTS.map(p=>p[9]));if(role==='sm')names.push(...Object.values(V3.owners));return [...new Set(names.filter(n=>n&&n!=='-'))];}
function v16Name(s){return String(s||'').replace(/\([^)]*\)/g,'').trim();}
function v16TaskRole(t){return Object.values(V16_ROLES).find(r=>r.types.includes(t.type))?.name||'业务协作';}
function v16Unit(kind){return ({projects:'个',customers:'位',opps:'个',products:'款',catalog:'款',insights:'款',receipts:'笔',orders:'笔'})[kind]||'项';}
function v16Cats(t){return String(t.cat||t.cats||t.smDept||'').split(/[、,，/]/).map(x=>x.trim()).filter(Boolean);}
function v16QuoteWaiting(t){if(t.type!=='报价待办'||t.status!=='待处理')return false;const codes=[...new Set([t.draft,...(t.drafts||[])].filter(Boolean))];return !!codes.length&&codes.every(code=>{const m=V3.meta[code];return m?.submitted&&m.active!==false&&!v3HasUnsubmitted(code)&&m.categories.some(c=>!m.confirmedCats.includes(c));});}
function v16Sort(tasks,done=false){return tasks.slice().sort((a,b)=>done?parseTodoTime(b.approveTime||b.time)-parseTodoTime(a.approveTime||a.time):parseTodoTime(a.time)-parseTodoTime(b.time));}
function v16Scope(){
 const role=V16.role,owner=V16.owner,all=visibleTodos(),wide=['manager','finance','library'].includes(role),own=all.filter(t=>t.owner===owner&&V16_ROLES[role].types.includes(t.type)),cats=Object.entries(V3.owners).filter(([,n])=>n===owner).map(([c])=>c);
 const customerNames=new Set(CUSTOMERS.filter(c=>c[4]===owner).map(c=>c[1]));own.forEach(t=>{if(t.customer)customerNames.add(t.customer);});
 const projectIds=new Set(own.filter(t=>t.project&&t.project!=='-').map(t=>t.project));
 PROJECTS.forEach(p=>{if(wide||role==='pm'&&p[9]===owner||role==='business'&&customerNames.has(p[7]))projectIds.add(p[0]);});
 if(role==='sm')OPPS.filter(o=>o[7]===owner).forEach(o=>projectIds.add(o[4]));
 const projects=PROJECTS.filter(p=>projectIds.has(p[0]));
 const related=all.filter(t=>wide||own.includes(t)||((projectIds.has(t.project)||role==='business'&&customerNames.has(t.customer))&&(role!=='sm'||v16Cats(t).some(c=>cats.includes(c)))&&(role!=='designer'||['创建项目待办','项目待办'].includes(t.type))));
 const pending=related.filter(t=>t.status==='待处理');
 const mine=v16Sort(own.filter(t=>t.status==='待处理'&&!v16QuoteWaiting(t)&&!todoBlockedReason(t)));
 const waiting=v16Sort(pending.filter(t=>!mine.includes(t)));
 const done=v16Sort(own.filter(t=>t.status==='已处理'),true);
 const customers=CUSTOMERS.filter(c=>wide||(role==='business'?c[4]===owner:customerNames.has(c[1])||projects.some(p=>p[7]===c[1])));
 const opps=OPPS.filter(o=>projectIds.has(o[4])&&(role!=='sm'||o[7]===owner));
 const drafts=DRAFTS.filter(d=>{const m=v3Meta(d[0]);return (wide||projectIds.has(m.project))&&(role!=='sm'||m.categories.some(c=>cats.includes(c)));});
 const orders=ORDERS.filter(o=>projectIds.has(o[15])&&(role!=='sm'||cats.includes(o[4])));
 const receipts=all.flatMap(t=>(t.receipts||[]).map((r,i)=>({...r,task:t,index:i}))).filter(r=>wide||projectIds.has(r.task.project));
 return {role,owner,all,own,cats,projects,related,pending,mine,waiting,done,customers,opps,drafts,orders,receipts};
}
function v16WaitLabel(t){if(v16QuoteWaiting(t))return '待客户确认';const labels={'设计待办':'待设计交付','设计单':'待设计处理','创建项目待办':'待 PM 立项','项目待办':'待 PM 分配商机','确认商机':'待 SM 承接','报价待办':'待 SM 提交报价','订单待办':'待 SM 转单','收款待办':'待 PM 登记收款','备货待办':'待 SM 提交备货','客户待办':'待补齐客户需求','邀请函审核':'待邀请函审核','公海跟进':'待客户跟进'};return todoBlockedReason(t)||labels[t.type]||t.type;}
function v16Next(t){const labels={'客户待办':'填报设计需求','设计待办':'承接与提交设计','创建项目待办':'确认立项','项目待办':'分配品类商机','确认商机':'确认承接','报价待办':'编辑报价','订单待办':'绑定并转单','收款待办':'登记收款','备货待办':'填写备货资料','设计单':'创建费用订单','邀请函审核':'审核邀请函','公海跟进':'记录客户跟进'};return labels[t.type]||'处理事项';}
function v16Primary(t){return todoActs(t).find(a=>!['todoReject','todoEnd'].includes(a.act)&&!/^(查看|详情|报价总览|项目报价总览|流程轨迹)/.test(a.t));}
function v16QuoteActions(t){if(!v16QuoteWaiting(t))return '';if(V16.role==='pm')return v15Button('preview','核对客户预览',`data-project="${esc(t.project)}"`,true);if(V16.role==='sm'&&t.owner===V16.owner&&t.draft)return v15Button('editDraft','需要调整？编辑报价',`data-code="${esc(t.draft)}"`);return '';}
function v16Age(t){const n=Math.floor((Date.now()-parseTodoTime(t.time))/86400000);return Number.isFinite(n)?n>0?'停留 '+Math.max(0,n)+' 天':'今日到达':'时间未记录';}
function v16Btn(action,label,attrs='',primary=false){return `<button class="v16-btn ${primary?'primary':''}" data-v16="${action}" ${attrs}>${label}</button>`;}
function v16Empty(title,body){return `<div class="v16-empty">${skyIcon('check')}<b>${esc(title)}</b><p>${esc(body)}</p></div>`;}
function v16Title(title,sub='',button=''){return `<header class="v16-section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${button}</header>`;}
function v16Tasks(items,mode='mine',limit=5){return items.slice(0,limit).map(t=>{
 const actionable=mode==='mine'&&v16Primary(t),waiting=v16QuoteWaiting(t),done=t.status==='已处理';
 return `<article class="v16-task" data-task-id="${esc(t.id)}"><span class="v16-task-icon ${waiting?'waiting':''}">${skyIcon(t.type.includes('报价')?'file':t.type.includes('客户')?'users':'check')}</span><div class="v16-task-body"><div class="v16-task-title"><b>${esc(mode==='waiting'?v16WaitLabel(t):v16Next(t))}</b><span class="v16-tag ${waiting?'amber':''}">${esc(done?'已完成':waiting?'待客户确认':t.type.replace('待办',''))}</span></div><p>${esc(t.project&&t.project!=='-'?v15ProjectName(t.project):t.customer||'未关联客户')}${v16Cats(t).length?' · '+esc(v16Cats(t).join(' / ')):''}</p><small>${esc(t.id)} · ${mode==='mine'?'交接要求：'+v16Hint(t):done?'完成于 '+(t.approveTime&&t.approveTime!=='-'?t.approveTime:'时间未记录'):'推进方：'+(waiting?'客户 · PM 跟进 / '+v16Name(t.owner)+' 提供方案':v16TaskRole(t)+' · '+(t.owner||'待分配'))}</small></div><div class="v16-task-end"><span>${done?'已留存交接记录':esc(v16Age(t))}</span>${v16Btn(actionable?'act':'task',actionable?v16Next(t):'查看进展',`data-id="${esc(t.id)}"`,!!actionable)}</div></article>`;
 }).join('')||v16Empty(mode==='mine'?'当前没有需要你处理的事项':mode==='done'?'暂无已完成记录':'当前没有等待协作的事项',mode==='mine'?'可查看等待协作与项目进展，新的交接会在这里出现。':'以当前角色关联的业务记录为准。');}
function v16Hint(t){return ({'客户待办':'补齐需求与附件，交给设计师','设计待办':'核对需求，提交设计资料','创建项目待办':'核对交接资料并创建项目','项目待办':'按空间与品类选择方案经理','确认商机':'核对范围后承接或退回','报价待办':'完成产品选品，提交本轮报价','订单待办':'确认报价后绑定商机生成订单','收款待办':'登记本次收款，满足条件后衔接备货','备货待办':'补齐备货信息交给后续执行','设计单':'处理本次设计费用','邀请函审核':'核对客户与邀请信息','公海跟进':'补充跟进记录，维护客户关系'})[t.type]||t.title||'核对资料后推进';}
function v16Metrics(s){const task=(key,label,items,sub)=>({key,label,items,kind:'tasks',sub}),rows=(key,label,items,kind,sub)=>({key,label,items,kind,sub});const mine=task('mine','需要我处理',s.mine,'本人名下，可直接推进'),waiting=task('waiting','等待协作',s.waiting,'关联业务中的待推进事项'),projects=rows('projects','关联项目',s.projects,'projects','设计、报价、订单进展');
 const per={
 business:[mine,rows('customers','负责客户',s.customers,'customers','当前客户与关联需求'),task('sea','公海预警',s.own.filter(t=>t.type==='公海跟进'&&t.status==='待处理'),'需要及时跟进的客户'),waiting],
 designer:[mine,task('design','待设计处理',s.mine.filter(t=>['设计待办','设计单'].includes(t.type)),'设计需求与设计费用'),task('handoff','等待立项 / 分配',s.waiting,'已关联设计项目的后续交接'),task('done','已完成交接',s.done,'本人已完成的业务记录')],
 pm:[mine,projects,task('customerWait','待客户确认',s.pending.filter(v16QuoteWaiting),'已提交报价 · 按待办计'),task('pay','待收款处理',s.pending.filter(t=>t.type==='收款待办'),'PM 名下收款登记待办')],
 sm:[mine,rows('opps','负责商机',s.opps,'opps',s.cats.join(' / ')||'当前品类'),task('customerWait','待客户确认',s.pending.filter(v16QuoteWaiting),'当前有效提交报价'),task('execution','转单 / 备货',s.mine.filter(t=>['订单待办','备货待办'].includes(t.type)),'客户确认后的执行事项')],
 manager:[task('team','团队待推进',s.pending,'覆盖客户至订单备货'),rows('projects','在管项目',s.projects,'projects','当前工作空间内项目'),task('customerWait','待客户确认',s.pending.filter(v16QuoteWaiting),'PM 负责对客跟进'),task('mine','待我审批',s.mine,'当前主管名下审批')],
 finance:[rows('receipts','CRM 收款记录',s.receipts,'receipts','已登记记录，非财务核销'),rows('orders','关联订单',s.orders,'orders','核对订单与收款依据'),task('pay','待登记收款',s.pending.filter(t=>t.type==='收款待办'),'由 PM 登记 CRM 收款'),{key:'fsc',label:'FSC 核销状态',value:'—',sub:'尚未接入',items:[],kind:'fsc'}],
 library:[rows('products','待完善产品',v15Pending(),'products','在线新增，报价可继续'),rows('ready','已完善产品',V15.products.filter(p=>p.status==='ready'),'products','已补齐材质与产品来源'),rows('catalog','可选产品',WK_CATALOG,'catalog','当前工作空间产品库'),rows('quoted','已报价产品',Array.from(new Set(v15Records().flatMap(([,m])=>v15Rows(m.submitted).map(p=>p.sku)))),'insights','有效提交版本，按编码去重')]
 };return per[s.role];}
const V16_STAGES=[['客户需求',['客户待办','公海跟进']],['设计与立项',['设计待办','设计单','创建项目待办']],['商机与报价',['项目待办','确认商机','报价待办']],['订单与交付',['订单待办','收款待办','备货待办']],['专项审批',['邀请函审核']]];
function v16RoleAside(s){
 if(s.role==='library'){const pending=v15Pending(),rows=[['待补材质',pending.filter(p=>!p.material)],['待补产品来源',pending.filter(p=>!p.source)],['待核对完成',pending.filter(p=>p.material&&p.source)]];return `<section class="v16-surface">${v16Title('资料缺口','按资料字段查看，快速定位待补内容')}<div class="v16-stages">${rows.map(([name,items],i)=>`<button data-v16="productGap" data-index="${i}"><span class="v16-stage-no">${i+1}</span><span>${name}</span><strong>${items.length}</strong>${skyIcon('arrow')}</button>`).join('')}</div><p class="v16-footnote">同一产品可能缺少多个字段。完善资料后，历史报价仍保留原提交版本。</p></section>`;}
 if(s.role==='finance'){return `<section class="v16-surface">${v16Title('订单与收款衔接','明确收款登记与后续执行的责任')}<div class="v16-stages">${[['待 PM 登记收款','pay',s.pending.filter(t=>t.type==='收款待办').length],['待 SM 提交备货','stock',s.pending.filter(t=>t.type==='备货待办').length],['已登记收款记录','receipts',s.receipts.length]].map(([name,key,count],i)=>`<button data-v16="financeLink" data-key="${key}"><span class="v16-stage-no">${i+1}</span><span>${name}</span><strong>${count}</strong>${skyIcon('arrow')}</button>`).join('')}</div><p class="v16-footnote">实际到账与核销需在 FSC 核对。这里只统计 CRM 已记录的业务。</p></section>`;}
 return v16StagePanel(s);
}
function v16RecentDrafts(s){return `<section class="v16-surface">${v16Title('最近的品类报价单','未提交修改与已提交版本分开呈现')}<div>${s.drafts.slice().sort((a,b)=>String(b[11]||'').localeCompare(String(a[11]||''))).slice(0,4).map(d=>{const m=v3Meta(d[0]),locked=Object.keys(m.bindings||{}).length;return `<article class="v16-data-row"><div><b>${esc(d[1])}</b><p>${esc(d[0])} · ${esc(v15ProjectName(m.project))}</p>${v15State(d[0])}</div><div class="v16-data-end">${v15Button('editDraft',locked?'查看报价单':'继续编辑',`data-code="${esc(d[0])}"`)}${v15Rows(DRAFT_DATA[d[0]]||m.submitted).length?v15Button('copyOne','复制报价单',`data-code="${esc(d[0])}"`):''}</div></article>`;}).join('')||v16Empty('暂无关联报价单','可以新建报价，或复制历史报价单开始本次方案。')}</div></section>`;}
function v16StagePanel(s){return `<section class="v16-surface">${v16Title(s.role==='manager'?'团队业务分布':'关联业务进展','当前待推进事项，可跨环节并行')}<div class="v16-stages">${V16_STAGES.map(([name,types],i)=>{const n=s.pending.filter(t=>types.includes(t.type)).length;return `<button data-v16="stage" data-index="${i}"><span class="v16-stage-no">${String(i+1).padStart(2,'0')}</span><span>${name}</span><strong>${n}</strong>${skyIcon('arrow')}</button>`;}).join('')}</div><p class="v16-footnote">数量按待办计算；停留时长用于跟进，不代表已逾期。</p></section>`;}
function v16ProjectRows(items,all=false){return items.slice(0,all?Infinity:4).map(p=>{const tasks=visibleTodos().filter(t=>t.project===p[0]&&t.status==='待处理'),labels=[...new Set(tasks.map(v16WaitLabel))];return `<article class="v16-project"><div class="v16-project-head"><div><b>${esc(p[1])}</b><p>${esc(p[0])} · ${esc(p[7])}</p></div><span class="v16-tag">${esc(p[4]||'项目记录')}</span></div><div class="v16-project-progress">${labels.slice(0,4).map(l=>`<span><i></i>${esc(l)}</span>`).join('')||'<span>暂无待推进事项</span>'}${labels.length>4?`<span>＋${labels.length-4} 类</span>`:''}</div><footer><small>PM · ${esc(p[9])}　${tasks.length} 项待推进</small>${v16Btn('project','查看项目',`data-code="${esc(p[0])}"`)}</footer></article>`;}).join('')||v16Empty('暂无关联项目','新建项目或完成交接后，项目进展将在这里显示。');}
function v16CustomerRows(items,all=false){return items.slice(0,all?Infinity:4).map(c=>`<article class="v16-data-row"><span class="v16-avatar">${esc(c[1].slice(0,1))}</span><div><b>${esc(c[1])}</b><p>${esc(c[0])} · ${esc(c[9])} · ${esc(c[6])}级客户</p><small>最近跟进：${esc(c[14]||'未记录')}</small></div><div class="v16-data-end"><span class="v16-tag ${c[13]!=='正常'?'amber':''}">${esc(c[13]||'跟进中')}</span>${v16Btn('customer','查看客户',`data-name="${esc(c[1])}"`)}</div></article>`).join('')||v16Empty('暂无客户记录','以当前负责人名下的客户为准。');}
function v16ProductRows(items,all=false){return items.slice(0,all?Infinity:5).map(p=>`<article class="v16-data-row"><span class="v16-avatar">${skyIcon('grid')}</span><div><b>${esc(p.name)}</b><p>${esc(p.sku)} · ${esc(p.cat)}</p><small>${esc(p.spec)} · ${p.status==='ready'?'资料已完善':!p.material&&!p.source?'待补材质、产品来源':!p.material?'待补材质':!p.source?'待补产品来源':'待核对资料'}</small></div><div class="v16-data-end">${v15Button('editProduct','完善资料',`data-sku="${esc(p.sku)}" data-origin="list"`)}</div></article>`).join('')||v16Empty('当前没有待完善产品','报价中遇到缺品，可先在线建档，资料完善任务会汇集到这里。');}
function v16ReceiptRows(items,all=false){return items.slice(0,all?Infinity:5).map(r=>`<article class="v16-data-row"><span class="v16-avatar">${skyIcon('file')}</span><div><b>${esc(r.task.order||r.task.orderNo||r.task.project)} · ${esc(r.type||'收款')}</b><p>${esc(v15ProjectName(r.task.project))} · ${esc(r.time||'时间未记录')}</p><small>CRM 登记人 · ${esc(r.task.owner)}　FSC 核销状态未接入</small></div><div class="v16-data-end"><strong>${esc(r.amount)}</strong>${v16Btn('task','查看登记依据',`data-id="${esc(r.task.id)}"`)}</div></article>`).join('')||v16Empty('暂无 CRM 收款记录','PM 登记后在此查阅订单与收款依据。');}
function v16OppRows(items,all=false){return items.slice(0,all?Infinity:6).map(o=>`<article class="v16-data-row"><span class="v16-avatar">${esc(o[3].slice(0,1))}</span><div><b>${esc(o[1])}</b><p>${esc(o[0])} · ${esc(v15ProjectName(o[4]))}</p><small>${esc(o[3])} · SM ${esc(o[7])} · ${esc(o[2])}</small></div><div class="v16-data-end"><span class="v16-tag">${esc(o[12])}</span>${v16Btn('opp','查看商机',`data-code="${esc(o[0])}"`)}</div></article>`).join('')||v16Empty('暂无关联商机','PM 分配品类商机后在此跟进。');}
function v16TaskPanel(s){const manager=s.role==='manager',tabs=manager?[['mine','待我审批',s.mine],['waiting','团队跟进',s.waiting],['done','已完成审批',s.done]]:[['mine','需要我处理',s.mine],['waiting','等待协作',s.waiting],['done','最近完成',s.done]];const active=tabs.find(x=>x[0]===V16.tab)||tabs[0],list=active[2].filter(t=>!V16.search||[t.id,t.title,t.owner,t.customer,t.project,v15ProjectName(t.project),t.type,...v16Cats(t)].join(' ').toLowerCase().includes(V16.search.toLowerCase()));return `<section class="v16-surface v16-work-list">${v16Title(manager?'审批与团队跟进':'我的工作',manager?'审批与团队事项分别展示':'待办按停留时间排序，直接进入对应业务',v16Btn('list','查看全部',`data-kind="${active[0]}"`))}<div class="v16-work-tabs" role="group" aria-label="工作事项筛选">${tabs.map(([k,l,a])=>`<button data-v16="tab" data-tab="${k}" class="${V16.tab===k?'on':''}" aria-pressed="${V16.tab===k}">${l}<b>${a.length}</b></button>`).join('')}</div><label class="v16-search">${skyIcon('search')}<input id="v16Search" placeholder="搜索客户、项目、品类或负责人" value="${esc(V16.search)}"><span>${list.length} 项</span></label><div id="v16TaskRows">${v16Tasks(list,V16.tab)}</div>${list.length>5?`<div class="v16-more">${v16Btn('list','查看其余 '+(list.length-5)+' 项',`data-kind="${active[0]}"`)}</div>`:''}</section>`;}
function v16Portfolio(s){if(s.role==='business')return `<section class="v16-surface">${v16Title('客户概览','当前负责客户的关系与跟进状态',v16Btn('metric','全部客户','data-key="customers"'))}${v16CustomerRows(s.customers)}</section>`;if(s.role==='sm')return `<section class="v16-surface">${v16Title('品类商机','从承接到报价、订单的关联记录',v16Btn('metric','全部商机','data-key="opps"'))}${v16OppRows(s.opps)}</section>${v16RecentDrafts(s)}`;return `<section class="v16-surface">${v16Title(s.role==='manager'?'项目全局':'项目概览','同时了解当前环节与后续交接',v16Btn('list','全部关联项目','data-kind="projects"'))}<div class="v16-project-grid">${v16ProjectRows(s.projects)}</div></section>`;}
function v16Shortcuts(role){const links={business:[['create','users','新建客户'],['customers','users','客户管理'],['sea','users','公海跟进'],['invite','file','客户邀请函']],designer:[['todos','check','待办中心'],['projects','brief','项目资料'],['customers','users','客户档案'],['flow','file','PRD']],pm:[['projects','brief','项目管理'],['opps','chart','商机管理'],['clients','home','客户预览'],['flow','file','PRD']],sm:[['new','file','新建报价'],['copy','rotate','复制历史报价单'],['mall','grid','产品库选品'],['drafts','file','报价单报价']],library:[['productList','grid','产品资料协作'],['newProduct','plus','新增产品'],['mall','grid','产品库选品'],['insights','chart','产品报价分布']],finance:[['receipts','file','收款记录'],['projects','brief','项目管理'],['flow','file','PRD'],['orders','brief','订单资料']],manager:[['todos','check','待办中心'],['projects','brief','项目管理'],['insights','chart','产品报价分布'],['flow','file','PRD']]};return `<section class="v16-surface">${v16Title('常用入口','与当前角色相关的工作')}<div class="v16-shortcuts">${links[role].map(([a,i,l])=>`<button data-v16="shortcut" data-target="${a}">${skyIcon(i)}<span>${l}</span>${skyIcon('arrow')}</button>`).join('')}</div></section>`;}
function v16Cooperation(s){const actions=s.role==='pm'?s.opps:s.role==='sm'?s.opps:[];if(actions.length)return `<section class="v16-surface">${v16Title(s.role==='pm'?'品类协同':'我的品类','责任人与最新推进环节')}<div class="v16-partners">${actions.slice(0,5).map(o=>{const t=s.pending.find(t=>t.project===o[4]&&v16Cats(t).includes(o[3]));return `<button data-v16="opp" data-code="${esc(o[0])}"><span class="v16-partner-avatar">${esc(v16Name(o[7]).slice(-2))}</span><span><b>${esc(o[3])}<small>${esc(o[7])}</small></b><p>${esc(t?v16WaitLabel(t):o[12]==='已录单'?'已录单，查看订单记录':'暂无待推进事项')}</p></span>${skyIcon('arrow')}</button>`;}).join('')}</div>${s.role==='pm'?'<p class="v16-footnote">报价提交后，由 PM 核对对客版本，并发送链接至 SCRM 项目群。</p>':''}</section>`;return '';}
function v16SpecialMain(s){if(s.role==='library')return `<section class="v16-surface">${v16Title('产品资料待完善','先完成本次报价，再持续补齐共享产品资料',v16Btn('metric','查看全部','data-key="products"'))}${v16ProductRows(v15Pending())}<div class="v16-more">${v15Button('newProduct','新增待完善产品')}</div></section><section class="v16-surface">${v16Title('已完善的资料','保留独立产品编码，已有报价保留当时的资料')}${V15.products.some(p=>p.status==='ready')?v16ProductRows(V15.products.filter(p=>p.status==='ready')):v16Empty('暂无已完善记录','资料补齐并标记完成后，产品会在这里留存。')}</section>`;if(s.role==='finance')return `<section class="v16-surface">${v16Title('CRM 收款登记','用于查阅与核对，不代表已到账或完成财务核销',v16Btn('metric','全部记录','data-key="receipts"'))}${v16ReceiptRows(s.receipts)}</section><section class="v16-surface">${v16Title('等待 PM 登记收款','查看登记责任人与订单，不代替 PM 处理')}${v16Tasks(s.pending.filter(t=>t.type==='收款待办'),'waiting')}</section>`;return v16TaskPanel(s)+v16Portfolio(s);}
pageHome=function(){const s=v16Scope(),role=V16_ROLES[V16.role],metrics=v16Metrics(s),staff=v16Owners(),special=['finance','library'].includes(s.role),name=s.role==='manager'?'团队全局':special?'共享协作视图':v16Name(s.owner)+' · '+(s.role==='sm'?s.cats.join(' / '):role.short);return `<div class="v16-home"><header class="v16-heading"><div><div class="v5-breadcrumb">工作空间 / 首页</div><h1>工作台</h1><p>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})} <span>·</span> ${esc(name)}</p></div><div class="v16-context"><label><span>角色预览</span><select id="v16Role" aria-label="工作台角色">${Object.entries(V16_ROLES).map(([k,r])=>`<option value="${k}" ${k===V16.role?'selected':''}>${r.name}</option>`).join('')}</select></label>${!special&&s.role!=='manager'?`<label><span>查看人员</span><select id="v16Owner" aria-label="查看人员">${staff.map(n=>`<option ${n===s.owner?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`:''}</div></header><section class="v16-banner"><img src="${SKY_ASSETS.hero}" alt="敬城理想生活空间"><div><small>GEORGE · ${esc(role.short)}</small><h2>每一步协作，都走向理想空间。</h2><p>${esc(role.mission)}</p><button data-v16="${special?'metric':'list'}" ${special?'data-key="'+metrics[0].key+'"':'data-kind="mine"'}>${special?'查看当前协作':s.role==='manager'?'查看待我审批':'查看我的待办'} <b>${special?metrics[0].items?.length||0:s.mine.length}</b>${skyIcon('arrow')}</button></div><span class="v16-banner-sign">客户 · 设计 · 项目 · 交付</span></section><div class="v16-scope-line"><span>${skyIcon('users')} ${esc(special?'当前工作空间 · '+role.short:s.role==='manager'?'团队业务视图 · 审批归属 '+s.owner:'本人待办＋关联业务 · '+s.owner)}</span><small>角色切换仅用于预览</small></div><div class="v16-metrics">${metrics.map(m=>`<button data-v16="metric" data-key="${m.key}"><span>${m.label}${skyIcon('arrow')}</span><strong>${m.value??m.items.length}<small>${m.value?'':v16Unit(m.kind)}</small></strong><p>${esc(m.sub)}</p></button>`).join('')}</div><div class="v16-grid"><main>${v16SpecialMain(s)}</main><aside>${v16RoleAside(s)}${v16Cooperation(s)}${v16Shortcuts(s.role)}${s.role==='library'?`<div class="v16-note"><b>产品记录随业务沉淀</b><p>这里显示当前工作空间的资料协作；已报价产品可在「产品报价分布」查阅，实际采购尚未接入。</p></div>`:s.role==='finance'?`<div class="v16-note"><b>财务信息边界</b><p>收款待办由 PM 推进。到账、核销与差异处理仍以财务系统为准；当前原型仅展示 CRM 登记信息。</p></div>`:''}</aside></div></div>`;};
RENDER.home=pageHome;
function v16List(title,items,kind='tasks',mode='waiting'){
 let body='';if(kind==='tasks')body=v16Tasks(items,mode,Infinity);else if(kind==='projects')body=v16ProjectRows(items,true);else if(kind==='customers')body=v16CustomerRows(items,true);else if(kind==='opps')body=v16OppRows(items,true);else if(kind==='products')body=v16ProductRows(items,true);else if(kind==='receipts')body=v16ReceiptRows(items,true);else if(kind==='orders')body=items.map(o=>`<article class="v16-data-row"><div><b>${esc(o[0])}</b><p>${esc(o[2])} · ${esc(o[4])} · ${esc(o[3])}</p><small>${esc(v15ProjectName(o[15]))}</small></div><div class="v16-data-end"><strong>${esc(o[10])}</strong>${v16Btn('project','查看项目订单',`data-code="${esc(o[15])}" data-section="order"`)}</div></article>`).join('')||v16Empty('暂无订单','以已生成的订单为准。');else if(kind==='fsc')body=v16Empty('FSC 核销状态尚未接入','CRM 收款登记不能作为财务到账或核销结果。');
 v3Dialog(title,`<div class="v16-dialog-content"><p class="v16-list-scope">${esc(V16_ROLES[V16.role].name)}${V16.owner?' · '+esc(V16.owner):''} · ${items.length} 项</p>${body}</div>`);
}
function v16Metric(key){const s=v16Scope(),m=v16Metrics(s).find(x=>x.key===key);if(!m)return;if(m.kind==='catalog'){v3CloseDialog();openPage('mall');return;}if(m.kind==='insights'){v16Insights();return;}v16List(m.label,m.items,m.kind,key==='mine'||key==='execution'||key==='design'||key==='sea'?'mine':key==='done'?'done':'waiting');}
function v16Insights(){v3Dialog('产品报价分布',`<div class="v16-insights">${v15Insights()}</div>`);document.querySelector('#v3Dialog .v3-dialog')?.classList.add('v16-wide-dialog');}
function v16TaskDetail(id){const t=visibleTodos().find(x=>x.id===id);if(!t)return;const s=v16Scope(),mine=s.mine.includes(t),acts=todoActs(t),primary=v16Primary(t);v3Dialog('事项进展',`<div class="v16-detail"><span class="v16-tag">${esc(t.type)} · ${esc(t.status)}</span><h3>${esc(t.title||v16Next(t))}</h3><dl>${[['事项编号',t.id],['客户',t.customer],['关联项目',t.project&&t.project!=='-'?v15ProjectName(t.project):'尚未立项'],['责任人',t.owner],['当前进展',t.status==='已处理'?'已完成交接':v16WaitLabel(t)],['交接要求',v16Hint(t)],['到达时间',t.time],['停留情况',t.status==='待处理'?v16Age(t)+'（未设置截止时间）':'已处理']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl>${v16QuoteWaiting(t)?'<p class="v16-note">方案已提交，等待客户确认。PM 负责对客沟通；如需修改，由 SM 编辑并重新提交，客户再确认。</p>':''}${t.receipts?.length?`<h4>CRM 收款记录</h4>${t.receipts.map(r=>`<p>${esc(r.type)} · ${esc(r.amount)} · ${esc(r.time)}<br><small>FSC 到账 / 核销状态未接入</small></p>`).join('')}`:''}</div>`,`<button class="wk-btn" data-v3="closeDialog">关闭</button>${acts.filter(a=>/^(查看|详情|报价总览|项目报价总览|流程轨迹)/.test(a.t)).map(a=>v16Btn('existing',a.t,`data-id="${esc(id)}" data-existing="${esc(a.act)}"`)).join('')}${v16QuoteActions(t)}${mine&&primary?v16Btn('act',v16Next(t),`data-id="${esc(id)}"`,true):''}`);}
function v16RunAction(t,action){v3CloseDialog();const holder=document.createElement('div');holder.innerHTML=`<button data-act="${esc(action.act)}" ${action.extra||''}></button>`;handleAct(holder.firstElementChild);}
document.addEventListener('change',e=>{if(e.target.id==='v16Role'){V16.role=e.target.value;const r=V16_ROLES[V16.role];V16.owner=r.default||'';if(!['manager','library','finance'].includes(V16.role)&&!v16Owners().includes(V16.owner))V16.owner=v16Owners()[0]||'';V16.tab=V16.role==='manager'?'waiting':'mine';V16.search='';openPage('home');}if(e.target.id==='v16Owner'){V16.owner=e.target.value;V16.search='';openPage('home');}});
document.addEventListener('input',e=>{if(e.target.id!=='v16Search')return;V16.search=e.target.value;const s=v16Scope(),list=(s[V16.tab]||[]).filter(t=>[t.id,t.title,t.owner,t.customer,t.project,v15ProjectName(t.project),t.type,...v16Cats(t)].join(' ').toLowerCase().includes(V16.search.toLowerCase()));document.getElementById('v16TaskRows').innerHTML=v16Tasks(list,V16.tab);e.target.nextElementSibling.textContent=list.length+' 项';const more=document.querySelector('.v16-work-list .v16-more');if(more)more.remove();if(list.length>5)document.querySelector('.v16-work-list').insertAdjacentHTML('beforeend',`<div class="v16-more">${v16Btn('list','查看其余 '+(list.length-5)+' 项',`data-kind="${V16.tab}"`)}</div>`);});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-v16]');if(!b)return;const a=b.dataset.v16,s=v16Scope();
 if(a==='tab'){V16.tab=b.dataset.tab;V16.search='';openPage('home');}
 if(a==='metric')v16Metric(b.dataset.key);
 if(a==='productGap'){const n=Number(b.dataset.index);v16List(['待补材质','待补产品来源','待核对完成'][n],v15Pending().filter(p=>n===0?!p.material:n===1?!p.source:p.material&&p.source),'products');}
 if(a==='financeLink'){const k=b.dataset.key;if(k==='stock')v16List('待 SM 提交备货',s.pending.filter(t=>t.type==='备货待办'));else v16Metric(k);}
 if(a==='list'){const k=b.dataset.kind,items=s[k]||[];v16List(({mine:'需要我处理',waiting:'等待协作',done:'最近完成',projects:'关联项目'})[k]||'业务记录',items.filter(t=>k==='projects'||!V16.search||[t.id,t.title,t.owner,t.customer,t.project,v15ProjectName(t.project),t.type,...v16Cats(t)].join(' ').toLowerCase().includes(V16.search.toLowerCase())),k==='projects'?'projects':'tasks',k);}
 if(a==='stage'){const [label,types]=V16_STAGES[Number(b.dataset.index)];v16List(label+' · 待推进',s.pending.filter(t=>types.includes(t.type)));}
 if(a==='task')v16TaskDetail(b.dataset.id);
 if(a==='act'){const t=s.mine.find(t=>t.id===b.dataset.id),action=t&&v16Primary(t);if(action)v16RunAction(t,action);else v16TaskDetail(b.dataset.id);}
 if(a==='existing'){const t=s.related.find(t=>t.id===b.dataset.id),action=t&&todoActs(t).find(a=>a.act===b.dataset.existing&&/^(查看|详情|报价总览|项目报价总览|流程轨迹)/.test(a.t));if(action)v16RunAction(t,action);}
 if(a==='project'){v3CloseDialog();archiveProject=b.dataset.code;pdTab=b.dataset.section==='order'?'order':'opp';archOpen=false;archEditable=false;openPage('detail');}
 if(a==='customer'){v3CloseDialog();viewCustomer=b.dataset.name;cdTab='owner';openPage('custDetail');}
 if(a==='opp'){v3CloseDialog();viewOpp=b.dataset.code;const o=OPPS.find(o=>o[0]===viewOpp);if(o)archiveProject=o[4];openPage('oppDetail');}
 if(a==='shortcut'){const t=b.dataset.target;if(t==='new')v15NewQuote();else if(t==='copy')v15CopyPicker();else if(t==='clients'){const ids=new Set(s.projects.map(p=>p[0])),projects=[...new Set(v15Records().map(([,m])=>m.project))].filter(p=>ids.has(p));v3Dialog('关联项目 · 客户预览',projects.map(p=>`<article class="v16-data-row"><div><b>${esc(v15ProjectName(p))}</b><p>PM 核对已提交版本后，发送对客链接至 SCRM 项目群。</p></div>${v15Button('preview','打开预览',`data-project="${esc(p)}"`,true)}</article>`).join('')||v16Empty('暂无已提交方案','关联项目提交报价后，可在此核对客户预览。'));}else if(t==='insights')v16Insights();else if(t==='newProduct')v15ProductForm();else if(t==='productList')v15ProductList();else if(t==='receipts'||t==='orders')v16Metric(t);else if(t==='create'){const b=document.createElement('button');b.dataset.act='createCustomer';handleAct(b);}else if(t==='flow')openPage('prd');else openPage(t);}
});
if(!V3.client&&pageKind(page)==='home')openPage('home');

/* One shared workbench. Only record scope and current ownership affect the data. */
const V17={scope:'related',tab:'mine',search:''};
function v17Owner(){const names=[...new Set([...visibleTodos().map(t=>t.owner),...PROJECTS.map(p=>p[9]),...CUSTOMERS.map(c=>c[4]),...OPPS.map(o=>o[7])].filter(Boolean))],user=String(V3.user||'').trim().toLowerCase();return names.find(n=>String(n).toLowerCase()===user)||names.find(n=>String(n).match(/\(([^)]+)\)/)?.[1].trim().toLowerCase()===user)||V3.user;}
function v17Scope(){
 const all=visibleTodos(),owner=v17Owner(),own=all.filter(t=>t.owner===owner),wide=V17.scope==='all';
 const customersOwned=new Set(CUSTOMERS.filter(c=>c[4]===owner).map(c=>c[1]));own.forEach(t=>{if(t.customer)customersOwned.add(t.customer);});
 const ids=new Set(own.filter(t=>t.project&&t.project!=='-').map(t=>t.project));
 PROJECTS.forEach(p=>{if(p[9]===owner||customersOwned.has(p[7]))ids.add(p[0]);});OPPS.filter(o=>o[7]===owner).forEach(o=>ids.add(o[4]));
 const related=all.filter(t=>wide||t.owner===owner||ids.has(t.project)||customersOwned.has(t.customer));
 const pending=v16Sort(related.filter(t=>t.status==='待处理'));
 const mine=v16Sort(own.filter(t=>t.status==='待处理'&&!v16QuoteWaiting(t)&&!todoBlockedReason(t)));
 const waiting=pending.filter(t=>!mine.includes(t)),done=v16Sort(own.filter(t=>t.status==='已处理'),true);
 const projects=PROJECTS.filter(p=>wide||ids.has(p[0]));
 const projectIds=new Set(projects.map(p=>p[0]));
 const customers=CUSTOMERS.filter(c=>wide||customersOwned.has(c[1])||projects.some(p=>p[7]===c[1]));
 const receipts=all.filter(t=>wide||projectIds.has(t.project)).flatMap(t=>(t.receipts||[]).map((r,index)=>({...r,task:t,index})));
 const orders=ORDERS.filter(o=>wide||projectIds.has(o[15]));
 return {all,owner,own,related,pending,mine,waiting,done,projects,customers,receipts,orders};
}
function v17Btn(action,label,attrs='',primary=false){return `<button class="v16-btn ${primary?'primary':''}" data-v17="${action}" ${attrs}>${label}</button>`;}
function v17Adapt(html){return html.replaceAll('data-v16=','data-v17=');}
function v17ScopeName(){return V17.scope==='all'?'全部业务':'与我相关';}
function v17Match(t){return !V17.search||[t.id,t.title,t.owner,t.customer,t.project,v15ProjectName(t.project),t.type,...v16Cats(t)].join(' ').toLowerCase().includes(V17.search.toLowerCase());}
function v17Metrics(s){return [
 {key:'pending',label:'待推进事项',items:s.pending,kind:'tasks',note:'客户、设计、项目与交付'},
 {key:'customers',label:'关联客户',items:s.customers,kind:'customers',note:'当前范围内的客户档案'},
 {key:'projects',label:'进行中项目',items:s.projects.filter(p=>!/完成|关闭|终止/.test(p[4]||'')),kind:'projects',note:'跟进项目与跨品类协作'},
 {key:'customerWait',label:'待客户确认',items:s.pending.filter(v16QuoteWaiting),kind:'tasks',note:'已提交报价 · 按待办计'}
 ];}
function v17Tasks(items,limit=5,mode='follow'){
 const s=v17Scope();return items.slice(0,limit).map(t=>{const can=s.mine.includes(t)&&v16Primary(t),waiting=v16QuoteWaiting(t),done=t.status==='已处理';return `<article class="v16-task" data-task-id="${esc(t.id)}"><span class="v16-task-icon ${waiting?'waiting':''}">${skyIcon(t.type.includes('报价')?'file':t.type.includes('客户')?'users':'check')}</span><div class="v16-task-body"><div class="v16-task-title"><b>${esc(can||done?v16Next(t):v16WaitLabel(t))}</b><span class="v16-tag ${waiting?'amber':''}">${esc(done?'已完成':waiting?'待客户确认':t.type.replace('待办',''))}</span></div><p>${esc(t.project&&t.project!=='-'?v15ProjectName(t.project):t.customer||'未关联客户')}${v16Cats(t).length?' · '+esc(v16Cats(t).join(' / ')):''}</p><small>${esc(t.id)} · ${esc(v16TaskRole(t))} · ${esc(t.owner||'待分配')}${waiting?' · PM 对客跟进':''}</small>${can?`<small class="v17-next">下一步：${esc(v16Hint(t))}</small>`:''}</div><div class="v16-task-end"><span>${done?esc(t.approveTime&&t.approveTime!=='-'?v5ShortDate(t.approveTime):'已完成交接'):esc(v16Age(t))}</span>${v17Btn(can?'act':'task',can?v16Next(t):'查看进展',`data-id="${esc(t.id)}"`,!!can)}</div></article>`;}).join('')||v16Empty(mode==='mine'?'暂无需要我处理的事项':mode==='done'?'暂无本人已完成记录':'当前范围暂无协作跟进事项',mode==='mine'?'新分配给你的工作会在这里出现，也可查看协作跟进。':'可调整数据范围，或从常用入口查看业务记录。');
}
function v17WorkPanel(s){const tabs=[['mine','我的待办',s.mine],['waiting','协作跟进',s.waiting],['done','最近完成',s.done]],active=tabs.find(t=>t[0]===V17.tab)||tabs[0],items=active[2].filter(v17Match);return `<section class="v16-surface v17-work-list">${v16Title('工作事项','我的待办与最近完成归属本人；协作跟进随数据范围变化',v17Btn('list','查看全部',`data-kind="${active[0]}"`))}<div class="v16-work-tabs" role="group" aria-label="工作事项筛选">${tabs.map(([k,l,list])=>`<button data-v17="tab" data-tab="${k}" class="${V17.tab===k?'on':''}" aria-pressed="${V17.tab===k}">${l}<b>${list.length}</b></button>`).join('')}</div><label class="v16-search">${skyIcon('search')}<input id="v17Search" placeholder="搜索客户、项目、品类或负责人" value="${esc(V17.search)}"><span>${items.length} 项</span></label><div id="v17TaskRows">${v17Tasks(items,5,V17.tab)}</div>${items.length>5?`<div class="v16-more">${v17Btn('list','查看其余 '+(items.length-5)+' 项',`data-kind="${V17.tab}"`)}</div>`:''}</section>`;}
function v17Stages(s){return `<section class="v16-surface">${v16Title('流程进展','各业务环节当前的待推进事项')}<div class="v16-stages">${V16_STAGES.map(([name,types],i)=>`<button data-v17="stage" data-index="${i}"><span class="v16-stage-no">${String(i+1).padStart(2,'0')}</span><span>${name}</span><strong>${s.pending.filter(t=>types.includes(t.type)).length}</strong>${skyIcon('arrow')}</button>`).join('')}</div><p class="v16-footnote">按当前数据范围统计；各环节可并行推进。</p></section>`;}
function v17Attention(s){const rows=[['customerWait','客户待确认',s.pending.filter(v16QuoteWaiting).length,'PM 核对方案并跟进客户'],['pay','收款待处理',s.pending.filter(t=>t.type==='收款待办').length,'PM 登记收款，衔接订单执行'],['stock','备货待处理',s.pending.filter(t=>t.type==='备货待办').length,'SM 补齐备货信息'],['products','产品待完善',v15Pending().length,'共享产品资料，报价可继续']];return `<section class="v16-surface">${v16Title('协作关注','明确推进环节与承接责任')}<div class="v17-attention">${rows.map(([key,label,n,sub])=>`<button data-v17="attention" data-key="${key}"><span><b>${label}</b><small>${sub}</small></span><strong>${n}</strong>${skyIcon('arrow')}</button>`).join('')}</div><div class="v17-attention-foot"><button data-v17="shortcut" data-target="insights">产品报价分布 ${skyIcon('arrow')}</button><small>产品资料为共享队列</small></div></section>`;}
function v17Shortcuts(){return `<section class="v16-surface">${v16Title('常用入口','客户经营、方案报价与交付协作')}<div class="v16-shortcuts">${[['customers','users','客户管理'],['projects','brief','项目管理'],['new','file','新建报价'],['copy','rotate','复制报价单'],['mall','grid','商城选品'],['clients','home','客户预览'],['products','grid','产品资料'],['receipts','file','收款记录']].map(([key,icon,label])=>`<button data-v17="shortcut" data-target="${key}">${skyIcon(icon)}<span>${label}</span>${skyIcon('arrow')}</button>`).join('')}</div></section>`;}
pageHome=function(){const s=v17Scope();return `<div class="v16-home v17-home"><header class="v16-heading"><div><div class="v5-breadcrumb">工作空间 / 首页</div><h1>工作台</h1><p>${esc(V3.user)}，${new Date().getHours()<12?'上午':new Date().getHours()<18?'下午':'晚上'}好。一起推进每一份托付。</p></div><div class="v17-header-end"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><div class="v17-scope" role="group" aria-label="数据范围">${[['related','与我相关'],['all','全部业务']].map(([k,l])=>`<button data-v17="scope" data-scope="${k}" class="${V17.scope===k?'on':''}" aria-pressed="${V17.scope===k}">${l}</button>`).join('')}</div></div></header><section class="v16-banner"><img src="${SKY_ASSETS.hero}" alt="敬城理想生活空间"><div><small>敬城 CRM · WORKSPACE</small><h2>每一步协作，都走向理想空间。</h2><p>从客户需求到空间交付，看清进展，接住下一步。</p><button data-v17="list" data-kind="mine">查看我的待办 <b>${s.mine.length}</b>${skyIcon('arrow')}</button></div><span class="v16-banner-sign">客户 · 设计 · 项目 · 交付</span></section><div class="v16-scope-line"><span>${skyIcon('users')} 当前范围：${v17ScopeName()}${V17.scope==='related'?' · '+esc(s.owner):' · 当前工作空间'}</span><small>本人待办集中处理，业务协作共同推进</small></div><div class="v16-metrics">${v17Metrics(s).map(m=>`<button data-v17="metric" data-key="${m.key}"><span>${m.label}${skyIcon('arrow')}</span><strong>${m.items.length}<small>${v16Unit(m.kind)}</small></strong><p>${m.note}</p></button>`).join('')}</div><div class="v16-grid"><main>${v17WorkPanel(s)}<section class="v16-surface">${v16Title('项目概览','项目当前进展、负责人与关联交接',v17Btn('list','查看全部','data-kind="projects"'))}<div class="v16-project-grid">${v17Adapt(v16ProjectRows(s.projects))}</div></section>${v17Attention(s)}</main><aside>${v17Stages(s)}${v17Shortcuts()}<div class="v17-signature">${companyLogo()}<p>让理想空间成为日常</p></div></aside></div></div>`;};
RENDER.home=pageHome;
function v17List(title,items,kind='tasks',mode='follow'){
 let body='';if(kind==='tasks')body=v17Tasks(items,Infinity,mode);else if(kind==='projects')body=v17Adapt(v16ProjectRows(items,true));else if(kind==='customers')body=v17Adapt(v16CustomerRows(items,true));else if(kind==='products')body=v16ProductRows(items,true);else if(kind==='receipts')body=v17Adapt(v16ReceiptRows(items,true));else if(kind==='orders')body=items.map(o=>`<article class="v16-data-row"><div><b>${esc(o[0])}</b><p>${esc(o[2])} · ${esc(o[4])} · ${esc(v15ProjectName(o[15]))}</p></div>${v17Btn('project','查看订单',`data-code="${esc(o[15])}" data-section="order"`)}</article>`).join('')||v16Empty('暂无订单记录','以当前范围内已生成的订单为准。');
 const personal=['mine','done'].includes(mode),scope=kind==='products'?'共享产品队列':personal?'本人记录 · '+v17Owner():v17ScopeName();v3Dialog(title,`<div class="v16-dialog-content"><p class="v16-list-scope">${esc(scope)} · ${items.length} ${v16Unit(kind)}</p>${kind==='receipts'?'<p class="v16-note">以下为 CRM 收款登记依据。实际到账与财务核销状态尚未接入，需在 FSC 核对。</p>':''}${body}</div>`);
}
function v17Metric(key){const m=v17Metrics(v17Scope()).find(x=>x.key===key);if(m)v17List(m.label,m.items,m.kind);}
function v17TaskDetail(id){const s=v17Scope(),t=s.related.find(t=>t.id===id);if(!t)return;const can=s.mine.includes(t)&&v16Primary(t),waiting=v16QuoteWaiting(t),project=PROJECTS.find(p=>p[0]===t.project),acts=todoActs(t);v3Dialog('事项进展',`<div class="v16-detail"><span class="v16-tag">${esc(t.type)} · ${esc(t.status)}</span><h3>${esc(t.title||v16Next(t))}</h3><dl>${[['事项编号',t.id],['客户',t.customer],['关联项目',project?.[1]||'尚未立项'],['责任人',t.owner],['推进岗位',v16TaskRole(t)],['当前进展',t.status==='已处理'?'已完成交接':v16WaitLabel(t)],['下一步',v16Hint(t)],['到达时间',t.time],['停留情况',t.status==='待处理'?v16Age(t)+'（未设置截止时间）':'已处理']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl>${waiting?'<p class="v16-note">已提交报价等待客户确认，由 PM 继续对客沟通。如需调整，由 SM 编辑并重新提交，客户再确认。</p>':''}${t.receipts?.length?`<h4>CRM 收款记录</h4>${t.receipts.map(r=>`<p>${esc(r.type)} · ${esc(r.amount)} · ${esc(r.time)}<br><small>FSC 到账 / 核销状态未接入</small></p>`).join('')}`:''}</div>`,`<button class="wk-btn" data-v3="closeDialog">关闭</button>${acts.filter(a=>/^(查看|详情|报价总览|项目报价总览|流程轨迹)/.test(a.t)).map(a=>v17Btn('existing',a.t,`data-id="${esc(id)}" data-existing="${esc(a.act)}"`)).join('')}${waiting&&v15Records().some(([,m])=>m.project===t.project)?v15Button('preview','查看客户预览',`data-project="${esc(t.project)}"`):''}${waiting&&t.owner===s.owner&&t.draft?v15Button('editDraft','需要调整？编辑报价',`data-code="${esc(t.draft)}"`):''}${can?v17Btn('act',v16Next(t),`data-id="${esc(id)}"`,true):''}`);}
function v17Shortcut(target){const s=v17Scope();if(target==='new')v15NewQuote();else if(target==='copy')v15CopyPicker();else if(target==='products')v15ProductList();else if(target==='receipts')v17List('CRM 收款记录',s.receipts,'receipts');else if(target==='insights')v16Insights();else if(target==='clients'){const ids=new Set(s.projects.map(p=>p[0])),projects=[...new Set(v15Records().map(([,m])=>m.project))].filter(p=>ids.has(p));v3Dialog('客户预览',`<p class="v16-list-scope">${v17ScopeName()} · 已提交的客户方案</p>`+(projects.map(p=>`<article class="v16-data-row"><div><b>${esc(v15ProjectName(p))}</b><p>PM 核对提交版本后，将对客链接发送至 SCRM 项目群。</p></div>${v15Button('preview','打开预览',`data-project="${esc(p)}"`,true)}</article>`).join('')||v16Empty('当前范围暂无已提交方案','报价提交后，可在此核对客户预览。')));}else openPage(target);}
document.addEventListener('input',e=>{if(e.target.id!=='v17Search')return;V17.search=e.target.value;const s=v17Scope(),items=(s[V17.tab]||[]).filter(v17Match);document.getElementById('v17TaskRows').innerHTML=v17Tasks(items,5,V17.tab);e.target.nextElementSibling.textContent=items.length+' 项';document.querySelector('.v17-work-list .v16-more')?.remove();if(items.length>5)document.querySelector('.v17-work-list').insertAdjacentHTML('beforeend',`<div class="v16-more">${v17Btn('list','查看其余 '+(items.length-5)+' 项',`data-kind="${V17.tab}"`)}</div>`);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-v17]');if(!b)return;const a=b.dataset.v17,s=v17Scope();
 if(a==='scope'){V17.scope=b.dataset.scope;V17.search='';openPage('home');}
 if(a==='tab'){V17.tab=b.dataset.tab;V17.search='';openPage('home');}
 if(a==='metric')v17Metric(b.dataset.key);
 if(a==='list'){const k=b.dataset.kind;v17List(({mine:'我的待办',waiting:'协作跟进',done:'最近完成',projects:'项目概览'})[k]||'业务记录',(s[k]||[]).filter(t=>k==='projects'||v17Match(t)),k==='projects'?'projects':'tasks',k);}
 if(a==='stage'){const [name,types]=V16_STAGES[Number(b.dataset.index)];v17List(name+' · 待推进',s.pending.filter(t=>types.includes(t.type)));}
 if(a==='attention'){const key=b.dataset.key;if(key==='customerWait')v17Metric(key);else if(key==='products')v17List('待完善产品',v15Pending(),'products');else v17List(key==='pay'?'收款待处理':'备货待处理',s.pending.filter(t=>t.type===(key==='pay'?'收款待办':'备货待办')));}
 if(a==='task')v17TaskDetail(b.dataset.id);
 if(a==='act'){const t=s.mine.find(t=>t.id===b.dataset.id),act=t&&v16Primary(t);if(act)v16RunAction(t,act);else v17TaskDetail(b.dataset.id);}
 if(a==='existing'){const t=s.related.find(t=>t.id===b.dataset.id),act=t&&todoActs(t).find(a=>a.act===b.dataset.existing&&/^(查看|详情|报价总览|项目报价总览|流程轨迹)/.test(a.t));if(act)v16RunAction(t,act);}
 if(a==='project'){v3CloseDialog();archiveProject=b.dataset.code;pdTab=b.dataset.section==='order'?'order':'opp';archOpen=false;archEditable=false;openPage('detail');}
 if(a==='customer'){v3CloseDialog();viewCustomer=b.dataset.name;cdTab='owner';openPage('custDetail');}
 if(a==='shortcut')v17Shortcut(b.dataset.target);
});
if(!V3.client&&pageKind(page)==='home')openPage('home');

/* Workbench = overview and priorities. The task centre owns task processing. */
const V18={context:null};
const V18_TODO_NAMES=Object.fromEntries([...CHAIN_STEPS,'设计单','邀请函审核','公海跟进'].map(t=>[t,t.endsWith('待办')?t:t+'待办']));
const V18_STAGE_TYPES=[['客户待办','设计待办','设计单','邀请函审核','公海跟进'],['创建项目待办','项目待办','确认商机'],['报价待办'],['订单待办','收款待办','备货待办']].map(types=>types.filter(crmTodoEnabled));
function v18Name(t){const type=typeof t==='string'?t:t.type;return typeof crmTaskCategory==='function'?crmTaskCategory(t):V18_TODO_NAMES[type]||type;}
function v18Btn(action,label,attrs='',primary=false){return `<button class="v16-btn ${primary?'primary':''}" data-v18="${action}" ${attrs}>${label}</button>`;}
function v18PendingDrafts(s=v17Scope()){
 const ids=new Set(s.projects.map(p=>p[0]));return DRAFTS.map(row=>{
  const code=row[0],m=V3.meta[code];if(!m?.submitted||m.active===false)return null;
  const cats=(m.categories||[]).filter(cat=>!m.confirmedCats.includes(cat)&&m.bindings?.[cat]?.revision!==m.revision);if(!cats.length)return null;
  const mine=s.own.some(t=>t.draft===code||(t.drafts||[]).includes(code))||row[2]===s.owner||row[2]===V3.user||(m.categories||[]).some(cat=>quoteSmOf(cat)===s.owner);
  if(V17.scope!=='all'&&!ids.has(m.project)&&!mine)return null;
  return {code,row,m,cats,amount:v3DraftAmount(m.submitted),changed:v3HasUnsubmitted(code),partial:cats.length<m.categories.length};
 }).filter(Boolean).sort((a,b)=>String(b.m.submittedAt||b.row[11]||'').localeCompare(String(a.m.submittedAt||a.row[11]||'')));
}
function v18Focus(s=v17Scope()){return s.pending.map(t=>{
 const blocked=todoBlockedReason(t);if(blocked)return {t,rank:0,reason:'前置条件未完成',hint:blocked};
 if(t.type==='公海跟进'&&isSeaRiskCustomer(t.customer))return {t,rank:1,reason:'客户公海风险',hint:'及时记录客户跟进，处理当前公海预警。'};
 if(v16QuoteWaiting(t)){const pm=PROJECTS.find(p=>p[0]===t.project)?.[9];return {t,rank:2,reason:'等待客户确认',hint:`${pm?'PM '+pm:'项目 PM'} 跟进客户反馈；如需调整，交由 ${t.owner||'SM'} 修改并重新提交。`};}
 return null;
 }).filter(Boolean).sort((a,b)=>a.rank-b.rank||parseTodoTime(a.t.time)-parseTodoTime(b.t.time));}
function v18FocusRows(items,limit=3){return items.slice(0,limit).map(({t,reason,hint})=>`<article class="v18-focus-row" data-focus-id="${esc(t.id)}"><div class="v18-focus-mark">${skyIcon(v16QuoteWaiting(t)?'file':t.type==='公海跟进'?'users':'check')}</div><div class="v18-focus-copy"><div><b>${esc(v18Name(t))}</b><span class="v16-tag amber">${esc(reason)}</span></div><p>${esc(t.project&&t.project!=='-'?v15ProjectName(t.project):t.customer)}${v16Cats(t).length?' · '+esc(v16Cats(t).join(' / ')):''}</p><small>${esc(hint)}</small><small class="v18-focus-owner">${esc(t.id)} · 待办负责人 ${esc(t.owner||'待分配')}</small></div>${v18Btn('enter','去跟进',`data-kind="single" data-id="${esc(t.id)}"`)}</article>`).join('')||v16Empty('暂无需要重点提醒的待办','目前没有前置条件受阻、客户公海预警或待客户确认的事项。');}
function v18DraftRows(items,limit=4){return items.slice(0,limit).map(d=>`<article class="v18-draft-row" data-pending-draft="${esc(d.code)}"><div class="v18-draft-title"><b>${esc(d.row[1])}</b><span class="v16-tag ${d.partial?'amber':''}">${d.partial?'部分品类已确认':'待客户确认'}</span></div><div class="v18-draft-main"><div class="v18-draft-copy"><p>${esc(v15ProjectName(d.m.project))}</p><small>${esc(d.code)} · V${d.m.revision} · ${esc(d.m.submittedAt||d.row[11])} 提交</small><div class="v18-draft-cats">${d.cats.map(cat=>`<span>${esc(cat)} <small>SM · ${esc(quoteSmOf(cat))}</small></span>`).join('')}</div>${d.changed?'<p class="v18-unsent-note">另有已保存修改尚未提交；客户仍查看当前提交版本。</p>':''}</div><div class="v18-draft-end"><strong>${qMoney(d.amount)}</strong><small>提交总额 · CNY</small><div>${v15Button('preview','客户预览',`data-project="${esc(d.m.project)}"`,true)}<button class="v16-btn" data-v3="draftDetail" data-code="${esc(d.code)}">详情</button></div></div></div></article>`).join('')||v16Empty('当前没有未确认报价单','已提交报价单的全部品类确认后，会从本列表移出。');}
function v18DraftPanel(s){const drafts=v18PendingDrafts(s);return `<section class="v16-surface v18-drafts">${v16Title('未确认报价单','仅列出已提交、尚未全部获得客户确认的报价单',v18Btn('drafts',`查看全部 ${drafts.length} 份`))}<div>${v18DraftRows(drafts)}</div><p class="v16-footnote">按报价单编码计数；部分确认保留未确认品类。未提交报价单在「报价单列表」继续编辑。</p></section>`;}
function v18Stages(s){return `<section class="v16-surface v18-stages">${v16Title('流程进展','按业务阶段查看当前待办',v18Btn('flow','查看 PRD'))}<div class="v16-stages">${DF9_STAGES.map((stage,i)=>`<button data-v18="enter" data-kind="stage" data-index="${i}"><span class="v16-stage-no">${stage.num}</span><span>${stage.title}</span><strong>${s.pending.filter(t=>V18_STAGE_TYPES[i].includes(t.type)).length}</strong>${skyIcon('arrow')}</button>`).join('')}</div><p class="v16-footnote">当前范围共 ${s.pending.length} 项待处理待办。邀请函审核、公海跟进、设计单归入客户与设计阶段；不单列审批阶段。</p></section>`;}
function v18Shortcuts(){return `<section class="v16-surface">${v16Title('常用入口','从概览进入具体业务')}<div class="v16-shortcuts">${[['customers','users','客户管理'],['projects','brief','项目管理'],['new','file','新建报价'],['copy','rotate','复制报价单'],['drafts','file','报价单列表'],['clients','home','客户预览'],['mall','grid','商城选品'],['receipts','file','收款记录']].map(([key,icon,label])=>`<button data-v17="shortcut" data-target="${key}">${skyIcon(icon)}<span>${label}</span>${skyIcon('arrow')}</button>`).join('')}</div></section>`;}
pageHome=function(){const s=v17Scope(),focus=v18Focus(s),drafts=v18PendingDrafts(s);return `<div class="v16-home v17-home v18-home"><header class="v16-heading"><div><div class="v5-breadcrumb">工作空间 / 首页</div><h1>工作台</h1><p>${esc(V3.user)}，${new Date().getHours()<12?'上午':new Date().getHours()<18?'下午':'晚上'}好。查看进展，找到今天的重点。</p></div><div class="v17-header-end"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><div class="v17-scope" role="group" aria-label="数据范围">${[['related','与我相关'],['all','全部业务']].map(([k,l])=>`<button data-v17="scope" data-scope="${k}" class="${V17.scope===k?'on':''}" aria-pressed="${V17.scope===k}">${l}</button>`).join('')}</div></div></header><section class="v16-banner"><img src="${SKY_ASSETS.hero}" alt="敬城理想生活空间"><div><small>敬城 CRM · WORKSPACE</small><h2>每一步协作，都走向理想空间。</h2><p>关键进展在这里掌握，具体待办在待办中心处理。</p><button data-v18="enter" data-kind="mine">进入待办中心 <b>${s.mine.length}</b>${skyIcon('arrow')}</button></div><span class="v16-banner-sign">客户 · 设计 · 项目 · 交付</span></section><div class="v16-scope-line"><span>${skyIcon('users')} 当前范围：${v17ScopeName()}${V17.scope==='related'?' · '+esc(s.owner):' · 当前工作空间'}</span><small>我的待办归属本人，协作与报价单随范围变化</small></div><div class="v16-metrics v18-metrics">${[['mine','我的待办',s.mine.length,'项','当前可由本人直接推进'],['waiting','待协作待办',s.waiting.length,'项','由他人推进，或等待前置条件'],['drafts','未确认报价单',drafts.length,'份','已提交，待客户完成品类确认']].map(([key,label,n,unit,note])=>`<button data-v18="${key==='drafts'?'drafts':'enter'}" data-kind="${key}"><span>${label}${skyIcon('arrow')}</span><strong>${n}<small>${unit}</small></strong><p>${note}</p></button>`).join('')}</div><div class="v16-grid"><main><section class="v16-surface v18-focus">${v16Title('重点待办跟进','只提醒影响交接的事项，完整处理请进入待办中心',v18Btn('enter','查看全部 '+focus.length+' 项','data-kind="focus"'))}${v18FocusRows(focus)}<p class="v16-footnote">关注原因：前置条件受阻、客户公海风险、等待客户确认。停留时长不直接作为逾期判断。</p></section>${v18DraftPanel(s)}</main><aside>${v18Stages(s)}${v18Shortcuts()}<div class="v17-signature">${companyLogo()}<p>让理想空间成为日常</p></div></aside></div></div>`;};
RENDER.home=pageHome;
function v18Enter(kind,id,index){const s=v17Scope();let list=[],label='';if(kind==='mine'){list=s.mine;label='我的待办';}else if(kind==='waiting'){list=s.waiting;label='待协作待办';}else if(kind==='focus'){list=v18Focus(s).map(x=>x.t);label='重点待办跟进';}else if(kind==='single'){list=s.related.filter(t=>t.id===id);label=list.length?v18Name(list[0])+' · '+id:'所选待办';}else if(kind==='stage'){list=s.pending.filter(t=>V18_STAGE_TYPES[index]?.includes(t.type));label=DF9_STAGES[index]?.title||'流程阶段';}
 V18.context={ids:list.map(t=>t.id),label,scope:kind==='mine'?'本人待办 · '+s.owner:v17ScopeName()};todoStatus='待处理';todoFilter='全部';todoQuick='';todoProject='';todoSearch='';WK.sort='oldest';const old=document.getElementById('todoSearchInp');if(old)old.value='';openPage('todos');}
function v18ClearContext(){V18.context=null;todoStatus='待处理';todoFilter='全部';todoQuick='';todoProject='';todoSearch='';const old=document.getElementById('todoSearchInp');if(old)old.value='';openPage('todos');}
const v18SearchedBase=searchedTodos;
searchedTodos=function(){const rows=v18SearchedBase();return V18.context?rows.filter(t=>V18.context.ids.includes(t.id)):rows;};
const v18TodosBase=pageTodos;
pageTodos=function(){const box=document.createElement('div');box.innerHTML=v18TodosBase();
 for(const button of box.querySelectorAll('.wk-task-nav [data-filter]')){const label=button.querySelector('span');if(label)label.textContent=button.dataset.filter==='全部'?'全部待办':v18Name(button.dataset.filter);}
 const caps=box.querySelectorAll('.wk-task-nav .wk-nav-cap');for(const cap of caps)if(cap.textContent==='专项事项')cap.textContent='其他待办';
 const title=box.querySelector('.wk-panel-title h2');if(title){const span=title.querySelector('span');title.replaceChildren(document.createTextNode(todoFilter==='全部'?'全部待办':v18Name(todoFilter)),...(span?[span]:[]));}
 for(const row of box.querySelectorAll('.wk-task-row')){const id=row.dataset.todoId,t=visibleTodos().find(t=>t.id===id);if(!t)continue;const name=row.querySelector('.wk-task-title b');if(name){const subject=name.textContent;name.textContent=v18Name(t);if(subject!==v18Name(t)&&subject!==t.type)name.parentElement.insertAdjacentHTML('afterend',`<small class="v18-task-context">${esc(subject)}</small>`);}for(const span of row.querySelectorAll('.wk-task-meta span'))if(span.textContent===t.type)span.textContent=v18Name(t);row.dataset.todoName=v18Name(t);}
 const labels={pending:'待处理待办',done:'已处理待办',rejected:'已驳回待办'};for(const [key,label] of Object.entries(labels)){const el=box.querySelector(`[data-kpi="${key}"] .label`);if(el)el.textContent=label;}
 if(V18.context){const rows=visibleTodos().filter(t=>V18.context.ids.includes(t.id));box.querySelector('.wk-head')?.insertAdjacentHTML('afterend',`<div class="v18-center-context"><div><b>来自${esc(V18.context.source||'工作台')} · ${esc(V18.context.label)}</b><span>${esc(V18.context.scope)} · 已定位 ${rows.length} 项待办，可继续筛选并处理</span></div>${v18Btn('clear','查看全部待办')}</div>`);for(const key of ['pending','today','done','rejected']){const value=key==='today'?rows.filter(t=>t.status==='待处理'&&String(t.time||'').startsWith(todoDay())).length:rows.filter(t=>t.status===({pending:'待处理',done:'已处理',rejected:'已驳回'})[key]).length;const n=box.querySelector(`[data-kpi="${key}"] strong`);if(n)n.textContent=value;}}
 return box.innerHTML;
};RENDER.todos=pageTodos;
document.addEventListener('click',e=>{if(e.target.closest('[data-v5="nav"][data-page="todos"], [data-act="go:todos"], [data-v3="homeTodos"]'))V18.context=null;},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-v18]');if(!b)return;if(b.dataset.v18==='enter')v18Enter(b.dataset.kind,b.dataset.id,Number(b.dataset.index));if(b.dataset.v18==='clear')v18ClearContext();if(b.dataset.v18==='flow')openPage('prd');if(b.dataset.v18==='drafts'){const rows=v18PendingDrafts();v3Dialog('未确认报价单',`<div class="v18-draft-dialog"><p class="v16-list-scope">${v17ScopeName()} · ${rows.length} 份已提交报价单尚未全部获客户确认</p>${v18DraftRows(rows,Infinity)}</div>`);document.querySelector('#v3Dialog .v3-dialog')?.classList.add('v18-wide-dialog');}});
if(!V3.client&&pageKind(page)==='home')openPage('home');

/* Shared operating overview. Record counts and task counts remain separate. */
V17.scope='all';
const V19={expanded:false};
function v19Button(action,label,attrs='',className=''){return `<button class="v19-link ${className}" data-v19="${action}" ${attrs}>${label}</button>`;}
function v19Data(){
 const s=v17Scope(),ids=new Set(s.projects.map(p=>p[0]));
 const opps=OPPS.filter(o=>V17.scope==='all'||ids.has(o[4])||o[7]===s.owner);
 const submitted=v15Records().filter(([,m])=>V17.scope==='all'||ids.has(m.project));
 const drafts=v18PendingDrafts(s),sales=s.orders.filter(o=>o[2]==='销售订单');
 const risk=s.customers.filter(c=>isSeaRiskCustomer(c[1]));
 const task=types=>s.pending.filter(t=>types.includes(t.type));
 return {...s,opps,submitted,drafts,sales,risk,task};
}
function v19Collection(key,d=v19Data()){
 const records={customers:['客户档案',d.customers,'customers','位'],risk:['需跟进的公海风险客户',d.risk,'customers','位'],projects:['项目协同',d.projects,'projects','个'],opps:['品类商机',d.opps,'opps','条'],unrecorded:['尚未录单的商机',d.opps.filter(o=>o[12]==='未录单'),'opps','条'],submitted:['有效提交报价',d.submitted,'submitted','份'],sales:['销售订单',d.sales,'orders','笔']};
 if(records[key])return records[key];
 const names={needs:['客户待办'],design:['设计待办'],createProject:['创建项目待办'],allocate:['项目待办'],accept:['确认商机'],quote:['报价待办'],order:['订单待办'],pay:['收款待办'],stock:['备货待办'],sea:['公海跟进'],invite:['邀请函审核'],fee:['设计单']};
 if(key==='quoteWork')return ['报价待办',d.task(['报价待办']).filter(t=>!v16QuoteWaiting(t)),'tasks','项'];
 const types=names[key]||[],label=types.map(v18Name).join(' / ');
 return [label,d.task(types),'tasks','项'];
}
function v19ToTasks(rows,label){
 v3CloseDialog();V18.context={ids:rows.map(t=>t.id),label,scope:v17ScopeName()};
 todoStatus='待处理';todoFilter='全部';todoQuick='';todoProject='';todoSearch='';WK.sort='oldest';
 const old=document.getElementById('todoSearchInp');if(old)old.value='';openPage('todos');
}
function v19Stat(key,label,n,unit){return v19Button('list',`<span>${label}</span><strong>${n}<small>${unit}</small></strong>`,`data-key="${key}"`,'v19-stat');}
function v19Panorama(d){
 const stats=[[
  v19Stat('customers','客户档案',d.customers.length,'位'),v19Stat('design','设计待办',d.task(['设计待办']).length,'项')
 ],[
  v19Stat('projects','项目',d.projects.length,'个'),v19Stat('opps','品类商机',d.opps.length,'条')
 ],[
  v19Stat('submitted','有效提交报价',d.submitted.length,'份'),v19Button('drafts',`<span>待客户确认</span><strong>${d.drafts.length}<small>份</small></strong>`,'','v19-stat')
 ],[
  v19Stat('sales','销售订单',d.sales.length,'笔'),v19Stat('stock','备货待办',d.task(['备货待办']).length,'项')
 ]];
 const roles=['业务 · 设计师','PM · SM','SM · PM · 客户','SM · PM'],copy=['了解需求，交接设计资料','落实项目与品类责任','形成方案，跟进客户确认','转单、登记收款与备货'];
 return `<section class="v19-panorama"><div class="v19-section-label"><div><h2>业务全景</h2><span>从客户经营到空间交付</span></div>${v18Btn('flow','查看 PRD')}</div><div class="v19-stage-grid">${DF9_STAGES.map((stage,i)=>`<article class="v19-stage"><header><span>${stage.num}</span><h3>${stage.title}</h3>${skyIcon('arrow')}</header><p>${copy[i]}</p><div class="v19-stage-stats">${stats[i].join('')}</div><footer><span>${roles[i]}</span>${v18Btn('enter',`阶段待办 ${d.pending.filter(t=>V18_STAGE_TYPES[i].includes(t.type)).length} →`,`data-kind="stage" data-index="${i}"`)}</footer></article>`).join('')}</div><p class="v19-caption">业务数字按档案、项目、商机、报价及订单分别统计；标注「待办」的数字表示需要处理的工作。各品类可并行推进。</p></section>`;
}
function v19Section(title,sub,action){return `<header class="v19-card-head"><div><h2>${title}</h2><p>${sub}</p></div>${action||''}</header>`;}
function v19CustomerRows(rows,d,limit=3){
 return [...rows].sort((a,b)=>Number(isSeaRiskCustomer(b[1]))-Number(isSeaRiskCustomer(a[1]))||String(a[14]||'').localeCompare(String(b[14]||''))).slice(0,limit).map(c=>{
  const risk=isSeaRiskCustomer(c[1]),projects=d.projects.filter(p=>p[7]===c[1]),needs=d.pending.filter(t=>t.customer===c[1]&&['客户待办','设计待办'].includes(t.type));
  return `<article class="v19-record" data-customer-code="${esc(c[0])}"><div class="v19-record-title">${v19Button('customer',esc(c[1]),`data-name="${esc(c[1])}" title="${esc(c[1])}"`)}<span class="v19-badge ${risk?'amber':''}">${esc(c[13]||'跟进中')}</span></div><p>负责人 ${esc(c[4]||'待分配')} <span>· 最近跟进 ${esc(c[14]||'未记录')}</span></p><footer><small>${projects.length?'关联 '+projects.length+' 个项目':needs.length?'需求 / 设计正在跟进':'尚未关联项目'}</small>${risk?v19Button('customerTasks','跟进客户 →',`data-name="${esc(c[1])}"`):v19Button('customer','查看客户 →',`data-name="${esc(c[1])}"`)}</footer></article>`;
 }).join('')||v16Empty('当前范围暂无客户档案','可从客户管理建立档案并开始跟进。');
}
function v19ProjectFacts(p,d){return {opps:d.opps.filter(o=>o[4]===p[0]),quotes:d.submitted.filter(([,m])=>m.project===p[0]),drafts:d.drafts.filter(x=>x.m.project===p[0]),sales:d.sales.filter(o=>o[15]===p[0]),pending:d.pending.filter(t=>t.project===p[0])};}
function v19ProjectRows(rows,d,limit=3){
 return [...rows].sort((a,b)=>v19ProjectFacts(b,d).pending.length-v19ProjectFacts(a,d).pending.length).slice(0,limit).map(p=>{
  const f=v19ProjectFacts(p,d),accept=f.pending.filter(t=>t.type==='确认商机'),stock=f.pending.filter(t=>t.type==='备货待办'),pay=f.pending.filter(t=>t.type==='收款待办');
  const next=[accept.length?`${accept.length} 项商机待承接`:'',f.drafts.length?`${f.drafts.length} 份报价待客户确认`:'',pay.length?`${pay.length} 项收款待办`:'',stock.length?`${stock.length} 项备货待办`:''].filter(Boolean);
  return `<article class="v19-record v19-project" data-project-code="${esc(p[0])}"><div class="v19-record-title">${v19Button('project',esc(p[1]),`data-code="${esc(p[0])}" title="${esc(p[1])}"`)}<span class="v19-badge">${esc(p[4]||'项目')}</span></div><p>客户 ${esc(p[7])} · PM ${esc(p[9]||'待分配')}</p><div class="v19-project-chain"><span>商机 <b>${f.opps.length}</b></span><i>→</i><span>提交报价 <b>${f.quotes.length}</b></span><i>→</i><span>销售订单 <b>${f.sales.length}</b></span></div><footer><small>${esc(next.join(' · ')|| (f.pending.length?'有 '+f.pending.length+' 项待办正在推进':'暂无待处理交接'))}</small>${v19Button('project','查看协同 →',`data-code="${esc(p[0])}"`)}</footer></article>`;
 }).join('')||v16Empty('当前范围暂无项目','设计资料交接并确认立项后，在此查看跨品类协同。');
}
function v19OppRows(rows,limit=3){return [...rows].sort((a,b)=>Number(a[12]!=='未录单')-Number(b[12]!=='未录单')||String(b[18]||'').localeCompare(String(a[18]||''))).slice(0,limit).map(o=>`<article class="v19-record" data-opp-code="${esc(o[0])}"><div class="v19-record-title">${v19Button('opp',`${esc(o[3])} <small>${esc(o[0])}</small>`,`data-code="${esc(o[0])}"`)}<span class="v19-badge ${o[12]==='未录单'?'amber':''}">${esc(o[12]||o[2])}</span></div><p>${esc(v15ProjectName(o[4]))}</p><footer><small>SM ${esc(o[7]||'待分配')} · ${esc(o[2])}</small>${v19Button('opp','查看商机 →',`data-code="${esc(o[0])}"`)}</footer></article>`).join('')||v16Empty('当前范围暂无品类商机','SM 确认承接后，进入商机跟进。');}
function v19BusinessCards(d){return `<div class="v19-business-grid">
 <section class="v16-surface" data-business="customers">${v19Section('客户经营','关注跟进状态，衔接需求与项目',v19Button('list','全部客户 →','data-key="customers"'))}<div class="v19-mini-stats">${v19Button('list',`公海风险 <b>${d.risk.length}</b> 位`,'data-key="risk"')}${v19Button('list',`客户待办 <b>${d.task(['客户待办']).length}</b> 项`,'data-key="needs"')}</div>${v19CustomerRows(d.customers,d)}<div class="v19-card-foot">${v19Button('nav','邀请函管理','data-page="invite"')}${v19Button('nav','到店管理','data-page="arrival"')}${v19Button('nav','公海客户','data-page="sea"')}</div></section>
 <section class="v16-surface" data-business="projects">${v19Section('项目推进','把商机、方案和订单放回同一个项目',v19Button('list','全部项目 →','data-key="projects"'))}<div class="v19-mini-stats">${v19Button('list',`创建项目待办 <b>${d.task(['创建项目待办']).length}</b> 项`,'data-key="createProject"')}${v19Button('list',`项目待办 <b>${d.task(['项目待办']).length}</b> 项`,'data-key="allocate"')}</div>${v19ProjectRows(d.projects,d)}<div class="v19-card-foot"><span>按待处理交接数量排序 · 各品类独立推进</span></div></section>
 <section class="v16-surface" data-business="opps">${v19Section('商机推进','看品类责任与录单进展',v19Button('list','全部商机 →','data-key="opps"'))}<div class="v19-mini-stats">${v19Button('list',`未录单 <b>${d.opps.filter(o=>o[12]==='未录单').length}</b> 条`,'data-key="unrecorded"')}${v19Button('list',`确认商机待办 <b>${d.task(['确认商机']).length}</b> 项`,'data-key="accept"')}</div>${v19OppRows(d.opps)}<div class="v19-card-foot"><span>先展示未录单商机 · 承接待办单独统计</span></div></section>
 </div>`;}
function v19GuidanceGroups(d){return [
  ['sea','客户跟进',d.task(['公海跟进']).filter(t=>isSeaRiskCustomer(t.customer)),'客户负责人更新跟进，处理公海预警'],
  ['accept','商机承接',d.task(['确认商机']),'对应 SM 确认承接，继续品类报价'],
  ['drafts','报价确认',d.drafts,'PM 将对客链接发至 SCRM 项目群，跟进客户确认'],
  ['needs','设计需求',d.task(['客户待办']),'客户负责人整理需求与附件，交接给设计师'],
  ['design','设计交接',d.task(['设计待办']),'设计师承接需求，补齐空间资料并交给 PM'],
  ['createProject','立项确认',d.task(['创建项目待办']),'PM 核对设计交接资料，确认立项'],
  ['allocate','分配品类商机',d.task(['项目待办']),'PM 按品类落实 SM，发起商机确认'],
  ['quoteWork','方案报价',d.task(['报价待办']).filter(t=>!v16QuoteWaiting(t)),'SM 选品、编辑并提交报价，形成对客方案'],
  ['order','确认后转单',d.task(['订单待办']),'对应 SM 绑定商机并生成订单'],
  ['pay','收款登记',d.task(['收款待办']),'PM 按订单登记收款，继续衔接备货'],
  ['stock','备货交接',d.task(['备货待办']),'SM 补齐备货要求与计划日期'],
  ['invite','邀请函审核',d.task(['邀请函审核']),'审核人核对来访资料，完成审核'],
  ['fee','设计费用',d.task(['设计单']),'设计师补齐费用信息并创建费用订单']
 ].filter(([, ,rows])=>rows.length);}
function v19Guidance(d){
 const groups=v19GuidanceGroups(d),visible=V19.expanded?groups:groups.slice(0,3);
 return `<section class="v19-guidance"><div><h2>接下来推进什么</h2><p>从业务状态找到下一步</p>${groups.length>3?v19Button('guidance',V19.expanded?'收起提醒 ↑':`展开其他 ${groups.length-3} 类 ↓`,`aria-expanded="${V19.expanded}"`):''}</div><div class="v19-guidance-items">${visible.map(([key,label,rows,hint])=>v19Button(key==='drafts'?'drafts':'list',`<span>${label} <b>${rows.length}${key==='drafts'?'份':'项'}</b></span><small>${hint}</small>`,`data-key="${key}"`)).join('')||'<span class="v19-caught-up">当前没有待交接事项，可继续查看客户与项目进展。</span>'}</div></section>`;
}
function v19OrderRows(rows,limit=3){return rows.slice(0,limit).map(o=>`<article class="v19-record"><div class="v19-record-title">${v19Button('order',esc(o[0]),`data-project="${esc(o[15])}"`)}<span class="v19-badge">${esc(o[3])}</span></div><p>${esc(v15ProjectName(o[15]))} · ${esc(o[4])}</p><footer><small>订单金额 ${qMoney(qNum(o[10]))}</small>${v19Button('order','查看订单 →',`data-project="${esc(o[15])}"`)}</footer></article>`).join('')||v16Empty('当前范围暂无销售订单','客户确认后，由 SM 绑定商机并转单。');}
function v19Orders(d){return `<section class="v16-surface v19-orders">${v19Section('订单与交付','核对订单，衔接收款与备货',v19Button('list','销售订单 →','data-key="sales"'))}<div class="v19-mini-stats">${v19Button('list',`订单待办 <b>${d.task(['订单待办']).length}</b>`,'data-key="order"')}${v19Button('list',`收款待办 <b>${d.task(['收款待办']).length}</b>`,'data-key="pay"')}${v19Button('list',`备货待办 <b>${d.task(['备货待办']).length}</b>`,'data-key="stock"')}</div>${v19OrderRows(d.sales)}<div class="v19-card-foot">${v19Button('receipts','查看 CRM 收款记录 →')}<span>实际到账以财务系统为准</span></div></section>`;}
function v19DraftPanel(d){return `<section class="v16-surface v18-drafts v19-drafts">${v19Section('未确认报价单','PM 跟进客户反馈，SM 负责方案调整',v18Btn('drafts','全部 '+d.drafts.length+' 份'))}${v18DraftRows(d.drafts,2)}<div class="v19-card-foot"><span>已提交且尚未全部确认；调整后重新提交，客户再确认。</span>${v19Button('nav','报价单列表 →','data-page="drafts"')}</div></section>`;}
function v19Recent(d){
 const completed=d.related.filter(t=>t.status==='已处理'&&t.approveTime&&t.approveTime!=='-').map(t=>({time:t.approveTime,label:v18Name(t)+'已处理',by:t.owner,context:t.project&&t.project!=='-'?v15ProjectName(t.project):t.customer,action:'history',attr:`data-id="${esc(t.id)}"`}));
 const quotes=d.submitted.filter(([,m])=>m.submittedAt).map(([code,m])=>({time:m.submittedAt,label:'报价已提交 · V'+m.revision,by:DRAFTS.find(r=>r[0]===code)?.[3]||'',context:v15ProjectName(m.project),action:'draft',attr:`data-code="${esc(code)}"`}));
 const rows=[...completed,...quotes].sort((a,b)=>String(b.time).localeCompare(String(a.time))).slice(0,4);
 return `<section class="v16-surface v19-recent">${v19Section('最近业务动态','查看已记录的提交与处理结果')}<div>${rows.map(x=>`<article><span class="v19-event-dot"></span><div>${v19Button(x.action,esc(x.label),x.attr)}<p>${esc(x.context)} · ${esc(x.by)}</p><time>${esc(x.time)}</time></div></article>`).join('')||v16Empty('暂无近期交接记录','业务处理后，在此查看最近变化。')}</div></section>`;
}
pageHome=function(){const d=v19Data();return `<div class="v16-home v19-home"><header class="v19-heading"><div><div class="v5-breadcrumb">敬城 CRM / 工作空间</div><h1>工作台 <span>从每一次了解，到每一处交付</span></h1><p>${esc(V3.user)}，${new Date().getHours()<12?'上午':new Date().getHours()<18?'下午':'晚上'}好。看清业务全貌，让下一步有序发生。</p></div><div class="v19-header-actions">${v18Btn('enter',`我的待办 <b>${d.mine.length}</b> →`,'data-kind="mine"',true)}<small>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</small></div></header><div class="v19-scopebar"><div class="v17-scope" role="group" aria-label="数据范围">${[['all','全部业务'],['related','与我相关']].map(([k,l])=>`<button data-v17="scope" data-scope="${k}" class="${V17.scope===k?'on':''}" aria-pressed="${V17.scope===k}">${l}</button>`).join('')}</div><span>${V17.scope==='all'?'当前工作空间的业务记录':'本人负责客户及参与项目的相关记录'} · 我的待办始终归属本人</span></div>${v19Panorama(d)}${v19Guidance(d)}${v19BusinessCards(d)}<div class="v19-delivery-grid">${v19DraftPanel(d)}${v19Orders(d)}</div>${v19Recent(d)}<footer class="v19-quick"><span>常用入口</span>${[['customers','客户管理'],['projects','项目管理'],['opps','商机管理'],['new','新建报价'],['copy','复制报价单'],['mall','商城选品'],['clients','客户预览']].map(([k,l])=>`<button data-v17="shortcut" data-target="${k}">${l}</button>`).join('')}<small>让理想空间成为日常</small></footer></div>`;};RENDER.home=pageHome;
function v19List(key){
 const d=v19Data(),[title,rows,kind,unit]=v19Collection(key,d);if(kind==='tasks'){v19ToTasks(rows,title);return;}
 let body=kind==='customers'?v19CustomerRows(rows,d,Infinity):kind==='projects'?v19ProjectRows(rows,d,Infinity):kind==='opps'?v19OppRows(rows,Infinity):kind==='orders'?v19OrderRows(rows,Infinity):rows.map(([code,m])=>`<article class="v19-record"><b>${esc(DRAFTS.find(r=>r[0]===code)?.[1]||code)}</b><p>${esc(v15ProjectName(m.project))} · V${m.revision} · ${esc(m.submittedAt||'')}</p><footer><small>${esc(v3Status(m))}</small>${v19Button('draft','查看报价 →',`data-code="${esc(code)}"`)}</footer></article>`).join('');
 if(!rows.length)body=v16Empty('当前范围暂无记录','切换业务范围，或进入对应业务模块继续工作。');
 v3Dialog(title,`<div class="v19-dialog"><p class="v16-list-scope">${v17ScopeName()} · ${rows.length} ${unit}</p>${body}</div>`);
 document.querySelector('#v3Dialog .v3-dialog')?.classList.add('v19-wide-dialog');
}
function v19Project(code){
 const d=v19Data(),p=d.projects.find(p=>p[0]===code);if(!p)return;const f=v19ProjectFacts(p,d);
 const cats=[...new Set([...f.opps.map(o=>o[3]),...f.quotes.flatMap(([,m])=>m.categories||[]),...f.sales.map(o=>o[4]),...f.pending.flatMap(v16Cats)])];
 v3Dialog('项目协同',`<div class="v19-dialog"><div class="v19-project-summary"><h3>${esc(p[1])}</h3><p>${esc(p[0])} · 客户 ${esc(p[7])}</p><p>PM ${esc(p[9]||'待分配')} · 项目状态 ${esc(mgProjectState(code))}</p></div><h4>各品类推进情况</h4><div class="v19-category-grid">${cats.map(cat=>{
  const opps=f.opps.filter(o=>o[3]===cat),quotes=f.quotes.filter(([,m])=>m.categories.includes(cat)),sales=f.sales.filter(o=>o[4]===cat),pending=f.pending.filter(t=>v16Cats(t).includes(cat));
  return `<article><header><b>${esc(cat)}</b><span>SM ${esc(opps[0]?.[7]||quoteSmOf(cat))}</span></header><p>商机 ${opps.length} 条 · 提交报价 ${quotes.length} 份 · 销售订单 ${sales.length} 笔</p><small>${esc(quotes.length?quotes.map(([,m])=>m.confirmedCats?.includes(cat)?'客户已确认 V'+m.revision:'等待客户确认 V'+m.revision).join('；'):'暂无有效提交报价')}</small>${pending.length?`<footer>${v19Button('categoryTasks','定位 '+pending.length+' 项待办 →',`data-project="${esc(code)}" data-cat="${esc(cat)}"`)}</footer>`:''}</article>`;
 }).join('')||v16Empty('尚未建立品类协作','通过项目待办分配商机，落实对应 SM。')}</div><h4>当前交接与负责人 <span>${f.pending.length} 项</span></h4><div class="v19-handoffs">${f.pending.map(t=>`<article><div><b>${esc(v18Name(t))}</b><p>${esc(v16Cats(t).join(' / ')||'项目协作')} · ${esc(t.owner||'待分配')}</p><small>${esc(todoBlockedReason(t)|| (v16QuoteWaiting(t)?'PM 跟进客户反馈，SM 按需修改并重新提交':v16Next(t)))}</small></div>${v19Button('task','进入待办中心 →',`data-id="${esc(t.id)}"`)}</article>`).join('')||'<p class="v19-caption">当前没有待处理交接，可进入项目查看完整记录。</p>'}</div></div>`,`<button class="wk-btn" data-v3="closeDialog">关闭</button>${v19Button('projectArchive','进入项目档案',`data-code="${esc(code)}"`,'v16-btn primary')}`);
 document.querySelector('#v3Dialog .v3-dialog')?.classList.add('v19-wide-dialog');
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v19]');if(!b)return;const a=b.dataset.v19;
 if(a==='guidance'){V19.expanded=!V19.expanded;document.querySelector('.v19-guidance').outerHTML=v19Guidance(v19Data());}
 if(a==='list')v19List(b.dataset.key);
 if(a==='nav'){v3CloseDialog();openPage(b.dataset.page);}
 if(a==='customer'){v3CloseDialog();viewCustomer=b.dataset.name;cdTab='owner';openPage('custDetail');}
 if(a==='customerTasks'){const d=v19Data(),rows=d.pending.filter(t=>t.customer===b.dataset.name&&['公海跟进','客户待办','设计待办'].includes(t.type));if(rows.length)v19ToTasks(rows,'客户跟进 · '+b.dataset.name);else{viewCustomer=b.dataset.name;cdTab='owner';v3CloseDialog();openPage('custDetail');}}
 if(a==='project')v19Project(b.dataset.code);
 if(a==='projectArchive'||a==='order'){v3CloseDialog();archiveProject=b.dataset.code||b.dataset.project;pdTab=a==='order'?'order':'opp';archOpen=false;archEditable=false;openPage('detail');}
 if(a==='opp'){const o=OPPS.find(o=>o[0]===b.dataset.code);if(o){v3CloseDialog();viewOpp=o[0];archiveProject=o[4];openPage('oppDetail');}}
 if(a==='draft'){v3CloseDialog();v3DraftDetail(b.dataset.code);}
 if(a==='drafts'){const rows=v18PendingDrafts();v3Dialog('未确认报价单',`<div class="v18-draft-dialog"><p class="v16-list-scope">${v17ScopeName()} · ${rows.length} 份；PM 跟进客户确认</p>${v18DraftRows(rows,Infinity)}</div>`);document.querySelector('#v3Dialog .v3-dialog')?.classList.add('v18-wide-dialog');}
 if(a==='task'||a==='history'){const t=visibleTodos().find(t=>t.id===b.dataset.id);if(t){v19ToTasks([t],v18Name(t)+' · '+t.id);if(a==='history'){todoStatus='已处理';openPage('todos');}}}
 if(a==='categoryTasks'){v19ToTasks(v19Data().pending.filter(t=>t.project===b.dataset.project&&v16Cats(t).includes(b.dataset.cat)),v15ProjectName(b.dataset.project)+' · '+b.dataset.cat);}
 if(a==='receipts')v17Shortcut('receipts');
});
if(!V3.client&&pageKind(page)==='home')openPage('home');

/* A compact shared landing page; detail remains in the existing business views. */
function v20Button(action,label,attrs='',primary=false){return `<button class="v20-btn ${primary?'primary':''}" data-v20="${action}" ${attrs}>${label}</button>`;}
function v20Attention(d=v19Data()){
 const people=rows=>[...new Set(rows.map(t=>t.owner).filter(Boolean))].map(v16Name).join('、');
 const tasks=(key,title,rows,next)=>({key,title,rows,kind:'tasks',next:(people(rows)?people(rows)+' · ':'')+next});
 return [
  tasks('blocked',`${d.pending.filter(t=>todoBlockedReason(t)).length} 项工作等待前置条件`,d.pending.filter(t=>todoBlockedReason(t)),'查看原因，协调前置工作'),
  {key:'risk',title:`${d.risk.length} 位客户存在公海风险`,rows:d.risk,kind:'customers',next:[...new Set(d.risk.map(c=>v16Name(c[4])))].join('、')+' · 及时更新客户跟进'},
  tasks('handoff',`${d.task(['设计待办','创建项目待办']).length} 项设计与立项交接待处理`,d.task(['设计待办','创建项目待办']),'核对需求和设计资料，继续交接'),
  tasks('accept',`${d.task(['确认商机']).length} 项商机等待承接`,d.task(['确认商机']),'确认承接后，开始品类报价'),
  tasks('allocate',`${d.task(['项目待办']).length} 项工作待分配品类商机`,d.task(['项目待办']),'落实各品类方案经理'),
  tasks('delivery',`${d.task(['订单待办','收款待办','备货待办']).length} 项订单交接待推进`,d.task(['订单待办','收款待办','备货待办']),'继续转单、收款或备货'),
  tasks('invite',`${d.task(['邀请函审核']).length} 份邀请函待审核`,d.task(['邀请函审核']),'核对来访资料'),
  tasks('fee',`${d.task(['设计单']).length} 项设计费用待处理`,d.task(['设计单']),'补齐费用信息并创建订单')
 ].filter(x=>x.rows.length);
}
function v20AttentionRows(rows,limit=3){return rows.slice(0,limit).map(x=>`<article class="v20-attention-row" data-attention-key="${x.key}"><span class="v20-dot ${x.key==='risk'||x.key==='blocked'?'amber':''}"></span><div><b>${esc(x.title)}</b><p>${esc(x.next)}</p></div>${v20Button('attention',x.kind==='customers'?'看客户':'去跟进',`data-key="${x.key}"`)}</article>`).join('')||'<div class="v20-empty"><b>暂无其他协作提醒</b><p>客户与项目进度，可从上方业务概览查看。</p></div>';}
function v20Overview(d){
 const activeProjects=d.projects.filter(p=>d.pending.some(t=>t.project===p[0]));
 const tiles=[
  ['customers','客户',d.customers.length,'位',d.risk.length?`${d.risk.length} 位存在公海风险`:'暂无公海风险','users'],
  ['projects','项目',d.projects.length,'个',activeProjects.length?`${activeProjects.length} 个有待处理交接`:'暂无待处理交接','brief'],
  ['opps','商机',d.opps.length,'条',`${d.opps.filter(o=>o[12]==='未录单').length} 条尚未录单`,'chart'],
  ['submitted','报价',d.submitted.length,'份',`${d.drafts.length} 份待客户确认`,'file'],
  ['sales','订单',d.sales.length,'笔',`收款待办 ${d.task(['收款待办']).length} · 备货待办 ${d.task(['备货待办']).length}`,'grid']
 ];
 return `<section class="v20-overview" aria-label="业务概览"><header><h2>业务概览</h2><span>当前范围内的业务记录</span>${v18Btn('flow','查看 PRD →')}</header><div class="v20-metrics">${tiles.map(([key,title,n,unit,hint,icon])=>`<button data-v19="list" data-key="${key}" title="${key==='submitted'?'查看有效提交报价':key==='sales'?'查看销售订单':'查看'+title+'记录'}"><div><span>${title}</span>${skyIcon(icon)}</div><strong>${n}<small>${unit}</small></strong><p>${hint}</p></button>`).join('')}</div></section>`;
}
function v20Mine(d){const grouped=[...new Set(d.mine.map(t=>v18Name(t)))];return `<section class="v20-mine"><div class="v20-mine-title"><h2>我来处理</h2><span>${esc(v16Name(d.owner))}</span></div><div class="v20-mine-count"><strong>${d.mine.length}</strong><span>项待办可以继续推进</span></div><p>${d.mine.length?esc(grouped.slice(0,3).join(' · '))+(grouped.length>3?' 等 '+grouped.length+' 类工作':''):'当前没有需要你直接处理的待办。'}</p>${v18Btn('enter',d.mine.length?'进入待办中心 →':'查看待办中心 →','data-kind="mine"',true)}<small>在待办中心查看资料、筛选和办理</small></section>`;}
function v20DraftRows(drafts,limit=2){return drafts.slice(0,limit).map(d=>`<article class="v20-draft-row" data-pending-draft="${esc(d.code)}"><div class="v20-draft-name"><button data-v3="draftDetail" data-code="${esc(d.code)}">${esc(d.row[1])}</button><p>${esc(v15ProjectName(d.m.project))} <span>· V${d.m.revision}</span></p>${d.changed?'<small class="v20-unsent">有修改尚未提交</small>':''}</div><div class="v20-draft-owner"><span>${d.partial?'部分品类已确认':'待客户确认'}</span><p>${d.cats.map(cat=>esc(cat)+' · '+esc(v16Name(quoteSmOf(cat)))).join(' / ')}</p></div><div class="v20-draft-price"><strong>${qMoney(d.amount)}</strong><small>提交总额</small></div>${v15Button('preview','客户预览',`data-project="${esc(d.m.project)}"`,true)}</article>`).join('')||'<div class="v20-empty"><b>暂无未确认报价单</b><p>已提交报价全部确认后，会从这里移出。</p></div>';}
pageHome=function(){const d=v19Data(),attention=v20Attention(d);return `<div class="v16-home v20-home"><header class="v20-heading"><div><h1>工作台</h1><p>${esc(V3.user)}，${new Date().getHours()<12?'上午':new Date().getHours()<18?'下午':'晚上'}好。</p></div><div class="v20-heading-end"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><div class="v17-scope" role="group" aria-label="业务数据范围">${[['all','全部业务'],['related','与我相关']].map(([k,l])=>`<button data-v17="scope" data-scope="${k}" class="${V17.scope===k?'on':''}" aria-pressed="${V17.scope===k}">${l}</button>`).join('')}</div></div></header>${v20Overview(d)}<div class="v20-main"><section class="v20-attention v16-surface"><header class="v20-section-head"><h2>需要关注</h2>${attention.length>3?v20Button('more','查看全部 →'):''}</header>${v20AttentionRows(attention)}</section>${v20Mine(d)}</div><section class="v20-drafts v16-surface"><header class="v20-section-head"><h2>未确认报价单 <span>${d.drafts.length}</span></h2><div>${v19Button('nav','报价单列表','data-page="drafts"')}${v18Btn('drafts','查看全部 →')}</div></header>${v20DraftRows(d.drafts)}</section><footer class="v20-footer"><span>敬城 CRM · 让理想空间成为日常</span><div><button data-v17="shortcut" data-target="new">新建报价</button><i></i><button data-v17="shortcut" data-target="copy">复制报价单</button></div></footer></div>`;};RENDER.home=pageHome;
document.addEventListener('click',e=>{const b=e.target.closest('[data-v20]');if(!b)return;
 if(b.dataset.v20==='more'){v3Dialog('需要关注',`<div class="v20-attention-dialog"><p class="v16-list-scope">${v17ScopeName()}</p>${v20AttentionRows(v20Attention(),Infinity)}</div>`);document.querySelector('#v3Dialog .v3-dialog')?.classList.add('v19-wide-dialog');}
 if(b.dataset.v20==='attention'){const item=v20Attention().find(x=>x.key===b.dataset.key);if(!item)return;if(item.kind==='customers')v19List('risk');else v19ToTasks(item.rows,item.title);}
});
if(!V3.client&&pageKind(page)==='home')openPage('home');

/* Prototype organisation. Viewing a report never changes the signed-in account. */
const V21_REPORTS={
 '叶志松(Andy Ye)':['覃文康(Chum)','林嘉怡(中东设计师)','林晓','周景澄','陆星遥','陈奕宁'],
 '覃文康(Chum)':['陈景航','董文君']
};
const V21={auth:'',view:'team',stay:'all'};
function v21Reports(owner){const seen=new Set([owner]),out=[];function visit(name){for(const report of V21_REPORTS[name]||[]){if(seen.has(report))continue;seen.add(report);out.push(report);visit(report);}}visit(owner);return out;}
function v21SuperAdmin(){return V3.user==='Andy Ye'&&V3.demoSuperAdmin!==false;}
function v21CanOperate(t){return !!t&&(v21SuperAdmin()||t.owner===v17Owner());}
function v21Manager(){return v21SuperAdmin()||v21Reports(v17Owner()).length>0;}
function v21AllowedOwners(){const owner=v17Owner();return v21SuperAdmin()?[...new Set([owner,...TODOS.map(t=>t.owner),...CUSTOMERS.map(c=>c[4]),...PROJECTS.map(p=>p[9]),...OPPS.map(o=>o[7]),'总经办审批岗'].filter(Boolean))]:[owner,...v21Reports(owner)];}
function v21View(){const owner=v17Owner(),allowed=v21AllowedOwners();if(V21.auth!==owner){V21.auth=owner;V21.view=allowed.length>1?'team':owner;V21.stay='all';V18.context=null;}if(V21.view==='team'&&allowed.length===1||V21.view!=='team'&&!allowed.includes(V21.view))V21.view=owner;return V21.view;}
function v21Owners(){return v21View()==='team'?v21AllowedOwners():[V21.view];}
