todoStayHours=function(t){const start=parseTodoTime(v21Arrival(t));if(!start)return null;const end=t.status==='待处理'?Date.now():parseTodoTime(t.approveTime);return end?Math.max(0,Math.floor((end-start)/3600000)):null;};
