 const customerNames=new Set(CUSTOMERS.filter(c=>owners.has(c[4])).map(c=>c[1]));related.forEach(t=>{if(t.customer)customerNames.add(t.customer);});
 const pmIds=new Set(PROJECTS.filter(p=>owners.has(p[9])).map(p=>p[0]));
 const projectIds=new Set([...pmIds,...related.map(t=>t.project),...OPPS.filter(o=>owners.has(o[7])).map(o=>o[4])]);
 PROJECTS.forEach(p=>{if(CUSTOMERS.some(c=>owners.has(c[4])&&c[1]===p[7]))projectIds.add(p[0]);});
 const projects=PROJECTS.filter(p=>projectIds.has(p[0])),customers=CUSTOMERS.filter(c=>customerNames.has(c[1])||projects.some(p=>p[7]===c[1]));
 const opps=OPPS.filter(o=>owners.has(o[7])||pmIds.has(o[4]));
 const submitted=v15Records().filter(([code,m])=>pmIds.has(m.project)||(m.categories||[]).some(cat=>owners.has(quoteSmOf(cat)))||related.some(t=>t.draft===code||(t.drafts||[]).includes(code)));
 const drafts=submitted.map(([code,m])=>{const row=DRAFTS.find(r=>r[0]===code);if(!row)return null;const cats=(m.categories||[]).filter(c=>!m.confirmedCats.includes(c)&&m.bindings?.[c]?.revision!==m.revision);return cats.length?{code,row,m,cats,amount:v3DraftAmount(m.submitted),changed:v3HasUnsubmitted(code),partial:cats.length<m.categories.length}:null;}).filter(Boolean).sort((a,b)=>String(b.m.submittedAt||'').localeCompare(String(a.m.submittedAt||'')));
 const oppIds=new Set(opps.map(o=>o[0])),orderIds=new Set(related.map(t=>t.order).filter(Boolean));
 const orders=ORDERS.filter(o=>pmIds.has(o[15])||oppIds.has(orderOppOf(o))||orderIds.has(o[0]));
