skyProductDetails=function(t){const x=v28Rows().find(x=>x.space===t.dataset.space&&x[3]===t.dataset.sku&&x[0]===t.dataset.name),unquoted=t.dataset.unquoted==='true'||x?._v28Quoted===false;
 if(!unquoted)return v28Details(t);
 const {name,cat,sku,qty,space}=t.dataset;SKY.focus=t;V8_PLAN.lastProduct={...t.dataset};document.getElementById('dTitle').textContent=skyT('产品配置详情','Product specification');
 document.getElementById('dBody').innerHTML=`<div class="qpd v31-pending-detail"><div class="qpd-kicker">${skySpace(space)} / ${skyCat(cat)}</div><h3>${esc(skyProd(name))}</h3><div class="v28-drawer-unquoted">${skyT('未报价','Not quoted')}</div><div class="qpd-grid">${[[skyT('所在空间','Room'),skySpace(space)],[skyT('品类','Category'),skyCat(cat)]].map(([label,value])=>`<span>${label}</span><b>${esc(value)}</b>`).join('')}</div><p>${skyT('具体产品及报价待确定，暂不计入报价合计。','Product details and quotation are pending. This item is excluded from the quoted total.')}</p></div>`;
 document.getElementById('dFoot').innerHTML=`<button class="btn default" data-v8-plan="locate">${skyT('在平面图中定位','Locate on plan')}</button><button class="btn default" data-act="closeDrawer">${skyT('返回方案','Back to proposal')}</button>`;
 const drawer=document.getElementById('drawer');drawer.classList.add('on','quote-prod');drawer.classList.remove('wide');drawer.setAttribute('role','dialog');drawer.setAttribute('aria-modal','true');drawer.setAttribute('aria-labelledby','dTitle');drawer.querySelector('[data-act="closeDrawer"]').focus();
};
const v28Locate=v8LocateProduct;
v8LocateProduct=function(){const r=v28Locate();v28SyncSpace();return r;};
function v28Print(){const d=v28Data(),rows=d.allRows;document.getElementById('v28PrintDetails').innerHTML=`<h2>${skyT('产品报价明细','Itemized quotation')}</h2><table><thead><tr>${['空间','品类','产品 / SKU','数量','单价','小计'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${skySpace(x.space)}</td><td>${skyCat(x[1])}</td><td>${esc(skyProd(x[0]))}${x._v28Quoted?`<br>${esc(x[3])}`:''}</td><td>${esc(x[4])}</td><td>${x._v28Quoted?skyMoney(qNum(x[5])):skyT('未报价','Not quoted')}</td><td>${x._v28Quoted?skyMoney(qNum(x[2])):skyT('未报价','Not quoted')}</td></tr>`).join('')}</tbody></table><p>${skyT('全项目已报价总额','Project quotation')} ${skyMoney(d.projectAmount)}</p>`;window.print();}
document.addEventListener('click',e=>{const room=e.target.closest('[data-v28-room]'),product=e.target.closest('[data-v28-product]');if(product){if(!V8_PLAN.suppressClick){V8_PLAN.selected=product.dataset.key;v10PlanUpdateSelection();skyProductDetails(product);}return;}if(room)v28ChooseRoom(room.dataset.v28Room,room.classList.contains('v28-room-tab'));if(e.target.closest('[data-v28="print"]'))v28Print();});
window.addEventListener('click',e=>{const room=e.target.closest?.('[data-v8-plan="room"]');if(room&&clientQuoteOpen()){e.preventDefault();e.stopImmediatePropagation();v28ChooseRoom(room.dataset.room,false);}},true);
document.addEventListener('change',e=>{if(e.target.matches('[data-v28-category]')){QUOTE_UI.clientCat=e.target.value;v28RefreshPanel();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-v28-product],[data-v28-room][role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
if(V3.client&&clientQuoteOpen()){SKY.mode=location.hash==='#model'?'model':'plan';openClientQuoteView();}

/* One category scope shared by the spatial presentation and the itemized quotation. */
const V29_CLIENT={list:false,project:''};
function v29CategoryNames(quotes=projectQuoteRows(archiveProject)){
 return [...new Set([...clientCatTotals(quotes).map(c=>c.cat),...quotes.flatMap(q=>[...spaceAllCats(q,archiveProject),...(q.missing||[])])])];
}
ensureClientCat=function(quotes){if(!QUOTE_UI.clientCat||QUOTE_UI.clientCat!=='全部品类'&&!v29CategoryNames(quotes).includes(QUOTE_UI.clientCat))QUOTE_UI.clientCat='全部品类';return QUOTE_UI.clientCat;};
function v31Rooms(quotes=projectQuoteRows(archiveProject),cat=QUOTE_UI.clientCat){return quotes.filter(q=>!cat||cat==='全部品类'||spaceHasCat(q,cat,archiveProject)||(q.missing||[]).includes(cat));}
ensureClientSpace=function(quotes){const rooms=v31Rooms(quotes,ensureClientCat(quotes));if(!rooms.some(q=>q.space===QUOTE_UI.clientSpace))QUOTE_UI.clientSpace='all';if(V36_SPACE.room!=='all'&&!rooms.some(q=>q.space===V36_SPACE.room))V36_SPACE.room='all';return QUOTE_UI.clientSpace;};
function v29RowConfirmed(x,d){if(!x._v28Quoted)return false;return x[6]?.draftCode?v3Meta(x[6].draftCode).confirmedCats.includes(x[1]):catFullyConfirmed(d.quotes,x[1]);}
function v29Data(){const d=v28Data(),categories=d.all?d.categories:d.categories.filter(c=>c.cat===d.cat),rows=d.rows.filter(x=>d.all||x[1]===d.cat),query=SKY.search.trim().toLocaleLowerCase(),visibleRows=rows.filter(x=>!query||[x[0],skyProd(x[0]),x[1],skyCat(x[1]),x[3],x.space,skySpace(x.space)].join(' ').toLocaleLowerCase().includes(query)),confirmedRows=rows.filter(x=>v29RowConfirmed(x,d));return {...d,scopeCategories:categories,scopeRows:rows,visibleRows,scopeAmount:v28Amount(rows),visibleAmount:v28Amount(visibleRows),confirmedRows,confirmedAmount:v28Amount(confirmedRows)};}
function v29CategoryBadge(cat,d){const rows=d.allRows.filter(x=>x[1]===cat&&x._v28Quoted),confirmed=rows.filter(x=>v29RowConfirmed(x,d)),state=!rows.length?'pending':confirmed.length===rows.length?'approved':confirmed.length?'partial':'review',label={pending:skyT('未报价','Not quoted'),approved:skyT('已确认','Approved'),partial:skyT('部分确认','Part approved'),review:skyT('待确认','To review')}[state];return `<span class="v29-category-state ${state}">${label}</span>`;}
function v29CategoryBar(){const d=v29Data(),cats=['全部品类',...v29CategoryNames(d.quotes)];return `<nav class="v29-category-bar" aria-label="${skyT('品类筛选','Category filter')}"><span class="v29-filter-label">${skyIcon('grid')}${skyT('品类','Category')}</span><div class="v29-category-tabs">${cats.map(cat=>`<button data-v29-category="${esc(cat)}" class="${cat===d.cat?'on':''}" aria-pressed="${cat===d.cat}">${cat==='全部品类'?skyT('全部品类','All categories'):skyCat(cat)}${cat!=='全部品类'?v29CategoryBadge(cat,d):''}</button>`).join('')}</div><button class="v29-reset" data-v29="clear" ${d.all&&d.space==='all'&&!SKY.search?'disabled':''}>${skyT('重置筛选','Reset filters')}</button></nav>`;}
function v29ChooseCategory(cat){if(cat!=='全部品类'&&!v29CategoryNames().includes(cat))return;if(cat==='全部品类')v39ClearPlanFeedback();QUOTE_UI.clientCat=cat;SKY.search='';if(cat!=='全部品类')V12_VISUAL.marked=true;v28RefreshPanel();v29Sync();}
function v29Approval(d){const next=d.quoted.find(c=>!catFullyConfirmed(d.quotes,c.cat)&&!QUOTE_UI.clientSelected[c.cat]),disabled=d.done||d.unquoted||(d.all&&!next);return `<div class="v28-approval v29-approval"><div class="v28-approval-title"><b>${skyT('品类报价确认','Category quote approval')}</b><span>${skyT('已确认','Approved')} ${d.confirmed} / ${d.quoted.length} ${skyT('个已报价品类','quoted categories')}</span></div><div class="v28-approve-action"><span><small>${d.all?skyT('全项目已报价合计','Quoted project total'):skyCat(d.cat)+' · '+skyT('全部空间合计','All spaces total')}</small><b>${d.unquoted?skyT('未报价','Not quoted'):skyMoney(d.categoryAmount)}</b></span><button class="btn" id="skyConfirmButton" data-sky="review" ${disabled?'disabled':''}>${d.done?skyT('已确认','Approved'):d.unquoted?skyT('未报价','Not quoted'):d.all?skyT('开始确认','Review proposal'):skyT('确认报价','Approve quote')}${!disabled?skyIcon('arrow'):''}</button></div></div>`;}
function v29Summary(d){const quoted=d.scopeRows.filter(x=>x._v28Quoted),confirmedCats=d.scopeCategories.filter(c=>c.quoted.length&&c.quoted.every(x=>v29RowConfirmed(x,d)));return `<header class="v28-space-summary v29-space-summary"><div class="v28-panel-eyebrow">${d.room?esc(d.room.floor)+' / ':''}${skyT('空间报价','SPACE QUOTATION')}</div><div class="v28-space-title"><h2>${d.room?skySpace(d.room.space):skyT('全屋概览','Whole home')}</h2><span>${quoted.length} ${skyT('项已报价','quoted items')}</span></div><div class="v29-total-label">${d.all?skyT('全部品类已报价合计','Quoted total · All categories'):skyCat(d.cat)+' · '+skyT('已报价合计','Quoted total')}</div><strong class="v28-space-total">${quoted.length?skyMoney(d.scopeAmount):d.scopeCategories.length?skyT('未报价','Not quoted'):skyT('暂无配置','No selection')}</strong><div class="v30-confirmed-total"><span>${skyT('已确认金额','Approved amount')}</span><b>${quoted.length?skyMoney(d.confirmedAmount):'—'}</b></div><div class="v28-space-stats"><span>${skyT('已报价品类','Quoted categories')} <b>${d.scopeCategories.filter(c=>c.quoted.length).length}</b></span><span class="v30-confirmed-count">${skyT('已确认品类','Approved categories')} <b>${confirmedCats.length}</b></span><span>${skyT('未报价品类','Pending categories')} <b>${d.scopeCategories.filter(c=>!c.quoted.length).length}</b></span></div></header>`;}
function v29PanelGroups(d){return d.scopeCategories.map(c=>`<section class="v28-category" data-category="${esc(c.cat)}"><header><h3>${skyCat(c.cat)}</h3><span class="v28-category-count">${c.items.length?c.items.length+' '+skyT('项','items'):''}</span>${c.quoted.length?`<strong>${skyMoney(c.amount)}</strong>`:`<span class="v28-unquoted">${skyT('未报价','Not quoted')}</span>`}</header>${c.items.map(v28Product).join('')}${!c.items.length?`<p class="v28-category-empty">${skyT('该品类尚未提交产品报价','No product quotation has been submitted')}</p>`:''}</section>`).join('')||`<div class="v29-empty">${skyIcon('grid')}<b>${skyT('当前空间暂无该品类产品','No products in this room and category')}</b><button data-v29-category="全部品类">${skyT('查看全部品类','View all categories')}</button></div>`;}
function v29Panel(){if(V29_CLIENT.list)return '';const d=v29Data();return `${v29Summary(d)}<div class="v28-category-scroll" id="skyProducts"><div class="v28-list-heading"><b>${skyT('空间产品','Room products')}</b><label class="v28-product-search">${skyIcon('search')}<input id="skyProductSearch" type="search" value="${esc(SKY.search)}" placeholder="${skyT('搜索产品 / SKU','Search products / SKU')}" aria-label="${skyT('搜索产品','Search products')}"></label></div><p class="v28-search-empty" hidden>${skyT('未找到匹配产品','No matching products')}</p>${v29PanelGroups(d)}</div>`;}
v28Panel=v29Panel;
function v29Status(x,d){if(!x._v28Quoted)return skyT('未报价','Not quoted');return v29RowConfirmed(x,d)?skyT('已确认','Approved'):skyT('待确认','To review');}
function v29TableBody(d){return d.visibleRows.map(x=>`<tr data-v29-quote-row ${v28ProductAttributes(x)}><td><button class="v29-table-product" data-sky="product" ${v28ProductAttributes(x)}>${x._v28Quoted?`<span class="v28-product-image">${quoteImgSvg(x[3])}</span>`:''}<span><b>${esc(skyProd(x[0]))}</b>${x._v28Quoted?`<small>${esc(x[3])}</small>`:''}</span></button></td><td>${skySpace(x.space)}</td><td>${skyCat(x[1])}</td><td class="v29-number">${esc(x[4])}</td><td class="v29-number ${x._v28Quoted?'':'is-unquoted'}">${x._v28Quoted?skyMoney(qNum(x[5])):skyT('未报价','Not quoted')}</td><td class="v29-number ${x._v28Quoted?'':'is-unquoted'}"><b>${x._v28Quoted?skyMoney(qNum(x[2])):skyT('未报价','Not quoted')}</b></td><td><span class="v29-status ${!x._v28Quoted?'pending':v29RowConfirmed(x,d)?'approved':'review'}">${v29Status(x,d)}</span></td><td><button class="v29-table-detail" data-sky="product" ${v28ProductAttributes(x)}>${skyT('详情','Details')}</button></td></tr>`).join('')||`<tr><td colspan="8"><div class="v29-empty">${skyIcon('file')}<b>${SKY.search?skyT('未找到匹配产品','No matching products'):d.scopeCategories.length?skyT('当前品类尚未提交产品报价','No product quotation has been submitted'):skyT('当前空间暂无该品类产品','No products in this room and category')}</b>${SKY.search?`<button data-v29="clearSearch">${skyT('清除搜索','Clear search')}</button>`:`<button data-v29-category="全部品类">${skyT('查看全部品类','View all categories')}</button>`}</div></td></tr>`;}
function v29List(){const d=v29Data(),missing=d.scopeCategories.filter(c=>!c.items.length);return `<section class="v29-quote-list" id="skyQuoteDetails" aria-label="${skyT('报价清单','Itemized quotation')}"><header class="v29-list-head"><div><h2>${skyT('报价清单','Itemized quotation')}</h2><span>${d.room?skySpace(d.room.space):skyT('全部空间','All spaces')}<i>/</i>${skyCat(d.cat)}<i>/</i><span id="v29LineCount">${d.visibleRows.length}</span> ${skyT('项产品','items')}</span></div><label class="v28-product-search">${skyIcon('search')}<input id="skyProductSearch" type="search" value="${esc(SKY.search)}" placeholder="${skyT('搜索产品 / SKU','Search products / SKU')}" aria-label="${skyT('搜索产品','Search products')}"></label></header><div class="v29-table-scroll" tabindex="0" aria-label="${skyT('报价明细表，可横向滚动','Quotation table. Scroll horizontally for all columns')}"><table class="v29-quote-table"><thead><tr>${[skyT('产品 / 编号','Product / SKU'),skyT('空间','Room'),skyT('品类','Category'),skyT('数量','Qty'),skyT('单价','Unit price'),skyT('小计','Subtotal'),skyT('报价状态','Status'),skyT('操作','Action')].map((s,i)=>`<th ${[3,4,5].includes(i)?'class="v29-number"':''}>${s}</th>`).join('')}</tr></thead><tbody>${v29TableBody(d)}</tbody></table></div>${missing.length?`<div class="v29-missing-cats"><span>${skyT('未报价品类','Unquoted categories')}</span>${missing.map(c=>`<button data-v29-category="${esc(c.cat)}">${skyCat(c.cat)}</button>`).join('')}</div>`:''}</section>`;}
const v29Stage=skyStage;
skyStage=function(){return V29_CLIENT.list?v29List():v29Stage();};
