skyStudio=function(d){return `<section class="sky-studio v28-studio v32-studio" id="skyStudio"><div class="sky-studio-bar"><div class="v28-room-strip" aria-label="${skyT('空间选择','Room selection')}">${v28RoomButtons(d)}</div><div class="sky-stage-tools"><button data-sky="resetView" title="${skyT('重置视图','Reset view')}">${skyIcon('rotate')}</button><button data-sky="lightbox" title="${skyT('全屏查看','Expand view')}">${skyIcon('expand')}</button></div></div><div class="sky-canvas" id="skyCanvas">${skyStage()}</div><footer class="v28-stage-foot"><span><i></i>${skyT('点击空间查看报价 · 点击产品查看详情','Select a room for its quotation · Select a product for details')}</span><small>${skyT('概念布局 · 非施工图','Concept layout · Not for construction')}</small></footer></section>`;};
