function v29Sync(){
 const root=document.getElementById('clientQuoteView'),studio=document.getElementById('skyStudio');if(!root||!studio)return;root.classList.add('v28-client','v29-client');root.classList.toggle('v29-list-mode',V29_CLIENT.list);studio.classList.toggle('v29-show-list',V29_CLIENT.list);
 const view=V29_CLIENT.list?'list':SKY.mode;root.querySelectorAll('.v32-view-tabs [role="tab"]').forEach(b=>{const on=b.dataset.v32View===view;b.classList.toggle('on',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});const panel=root.querySelector('#skyShowcase');panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','v32-tab-'+view);
 root.querySelectorAll('[data-v29-category]').forEach(b=>{const on=b.dataset.v29Category===QUOTE_UI.clientCat;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));});
 root.querySelector('[data-v29="clear"]')?.toggleAttribute('disabled',QUOTE_UI.clientCat==='全部品类'&&QUOTE_UI.clientSpace==='all'&&!SKY.search);
 const cat=QUOTE_UI.clientCat;document.querySelectorAll('.v10-plan-object').forEach(el=>{el.classList.toggle('v29-other-category',cat!=='全部品类'&&el.dataset.cat!==cat);el.classList.toggle('v29-category-match',cat!=='全部品类'&&el.dataset.cat===cat);});
 studio.querySelectorAll('.v30-plan-room-label[data-room]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.room===QUOTE_UI.clientSpace)));
 const allowed=new Set(v31Rooms().map(q=>q.space));studio.querySelectorAll('[data-v28-room],.v30-plan-room-label[data-room]').forEach(el=>{const room=el.dataset.v28Room||el.dataset.room;el.style.display=room==='all'||allowed.has(room)?'':'none';});v28SyncSpace();
 if(V29_CLIENT.list){const tools=studio.querySelector('.sky-stage-tools');tools.className='sky-stage-tools v29-list-tools';tools.innerHTML=`<button data-v28="print">${skyIcon('print')}${skyT('导出完整清单','Export full quote')}</button>`;}
 else v13SyncRecognition();
}
const v29Open=openClientQuoteView;
