function v41EnsureVisible(nav){const rail=nav.querySelector('.v41-option-rail'),active=rail.querySelector('.on');if(active&&active.style.display!=='none'){const a=active.getBoundingClientRect(),r=rail.getBoundingClientRect();if(a.left<r.left)rail.scrollLeft-=r.left-a.left+2;else if(a.right>r.right)rail.scrollLeft+=a.right-r.right+2;}v41RailUpdate(nav);}
function v41WrapRail(rail,kind){
 let nav=rail.parentElement;if(nav.classList.contains('v41-option-nav'))return nav;
 const old=V41_NAV.rails.get(kind);old?.observer.disconnect();
 nav=document.createElement('div');nav.className=`v41-option-nav v41-${kind}-nav`;nav.dataset.v41Kind=kind;rail.before(nav);
 const pinned=rail.firstElementChild;pinned.classList.add('v41-pinned');rail.classList.add('v41-option-rail');
 nav.append(pinned);nav.insertAdjacentHTML('beforeend',`<button class="v41-scroll" data-v41-scroll="-1" aria-label="${skyT('向前翻页','Previous options')}">${v41Arrow(false)}</button>`);nav.append(rail);
 nav.insertAdjacentHTML('beforeend',`<button class="v41-scroll" data-v41-scroll="1" aria-label="${skyT('向后翻页','Next options')}">${v41Arrow(true)}</button><button class="v41-browse" data-v41-browse="${kind}" aria-haspopup="dialog" aria-expanded="false">${skyIcon('grid')}<span></span><small></small></button>`);
 nav.querySelectorAll('[data-v41-scroll]').forEach(b=>b.addEventListener('click',()=>rail.scrollBy({left:Number(b.dataset.v41Scroll)*Math.max(200,rail.clientWidth*.72),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})));
 nav.querySelector('[data-v41-browse]').addEventListener('click',e=>{if(V41_NAV.picker?.kind===kind)v41ClosePicker(true);else v41OpenPicker(kind,e.currentTarget);});
 rail.addEventListener('scroll',()=>v41RailUpdate(nav),{passive:true});
 const observer=new ResizeObserver(()=>{v41RailUpdate(nav);});observer.observe(rail);V41_NAV.rails.set(kind,{nav,observer});return nav;
}
function v41EnhanceNavigation(){
 for(const [kind,item]of V41_NAV.rails)if(!item.nav.isConnected){item.observer.disconnect();V41_NAV.rails.delete(kind);}
 if(V41_NAV.picker&&!V41_NAV.picker.el.isConnected)v41ClosePicker();
 const root=document.getElementById('clientQuoteView');if(!root||!clientQuoteOpen())return;
 for(const [kind,selector]of [['category','.v29-category-tabs'],['room','.v28-room-strip']]){
  const rail=root.querySelector(selector);if(!rail)continue;const nav=v41WrapRail(rail,kind),selected=kind==='category'?QUOTE_UI.clientCat:V36_SPACE.room,browse=nav.querySelector('.v41-browse'),count=kind==='category'?v29CategoryNames().length:v31Rooms().length;
  browse.querySelector('span').textContent=kind==='category'?skyT('品类目录','Categories'):skyT('空间目录','Rooms');browse.querySelector('small').textContent=count;
  browse.setAttribute('aria-label',(kind==='category'?skyT('浏览品类','Browse categories'):skyT('浏览空间','Browse rooms'))+' · '+count);
  if(nav.dataset.selection!==selected){nav.dataset.selection=selected;v41EnsureVisible(nav);}else v41RailUpdate(nav);
 }
 if(V41_NAV.picker)v41ClosePicker();
}
function v41PickerItems(kind){
 if(kind==='category'){const d=v29Data();return [{value:'全部品类',label:skyT('全部品类','All categories'),extra:''},...v29CategoryNames().map(cat=>({value:cat,label:skyCat(cat),extra:v29CategoryBadge(cat,d)}))];}
 return [{value:'all',label:skyT('全屋','Whole home'),extra:''},...v31Rooms().map(q=>({value:q.space,label:skySpace(q.space),extra:`<small class="v41-room-floor">${esc(q.floor||'')}</small>`}))];
}
function v41RenderChoices(){
 const p=V41_NAV.picker;if(!p)return;const term=p.el.querySelector('input').value.trim().toLocaleLowerCase(),selected=p.kind==='category'?QUOTE_UI.clientCat:V36_SPACE.room,items=p.items.filter(x=>(x.value+' '+x.label+' '+x.extra.replace(/<[^>]*>/g,' ')).toLocaleLowerCase().includes(term));
 p.el.querySelector('.v41-picker-grid').innerHTML=items.map(x=>`<button class="v41-picker-choice ${x.value===selected?'on':''}" data-v41-choice="${esc(x.value)}" aria-pressed="${x.value===selected}"><span>${esc(x.label)}</span>${x.extra}<i>${x.value===selected?'✓':''}</i></button>`).join('')||`<p class="v41-picker-empty">${skyT('未找到匹配选项','No matching options')}</p>`;
 p.el.querySelector('.v41-result-count').textContent=`${items.length} ${skyT('个选项','options')}`;
}
function v41PositionPicker(){const p=V41_NAV.picker;if(!p)return;if(!p.anchor.isConnected){v41ClosePicker();return;}const r=p.anchor.getBoundingClientRect(),w=Math.min(700,innerWidth-40);p.el.style.width=w+'px';p.el.style.left=Math.max(20,Math.min(r.right-w,innerWidth-w-20))+'px';p.el.style.top=r.bottom+10+'px';p.el.style.maxHeight=Math.max(220,innerHeight-r.bottom-30)+'px';}
function v41OpenPicker(kind,anchor){
 v41ClosePicker();const el=document.createElement('section');el.id='v41Picker';el.className='v41-picker';el.setAttribute('role','dialog');el.setAttribute('aria-label',kind==='category'?skyT('选择品类','Choose a category'):skyT('选择空间','Choose a room'));
 el.innerHTML=`<header><h3>${kind==='category'?skyT('品类目录','Categories'):skyT('空间目录','Rooms')}</h3><span class="v41-result-count" role="status"></span><button class="v41-picker-close" aria-label="${skyT('关闭','Close')}">${skyIcon('close')}</button></header><label class="v41-picker-search">${skyIcon('search')}<input type="search" autocomplete="off" placeholder="${kind==='category'?skyT('搜索品类','Search categories'):skyT('搜索空间 / 楼层','Search rooms / floor')}" aria-label="${skyT('搜索选项','Search options')}"></label><div class="v41-picker-grid"></div>`;
 document.getElementById('clientQuoteView').append(el);V41_NAV.picker={kind,el,anchor,items:v41PickerItems(kind)};anchor.setAttribute('aria-expanded','true');anchor.setAttribute('aria-controls','v41Picker');
 el.querySelector('input').addEventListener('input',v41RenderChoices);el.querySelector('.v41-picker-close').addEventListener('click',()=>v41ClosePicker(true));
 el.addEventListener('click',e=>{const b=e.target.closest('[data-v41-choice]');if(!b)return;const value=b.dataset.v41Choice;v41ClosePicker(true);if(kind==='category')v29ChooseCategory(value);else v28ChooseRoom(value,true);});
 v41RenderChoices();v41PositionPicker();if(matchMedia('(max-width:850px)').matches){el.tabIndex=-1;el.focus({preventScroll:true});}else el.querySelector('input').focus({preventScroll:true});
}
function v41ClosePicker(focus=false){const p=V41_NAV.picker;if(!p)return;V41_NAV.picker=null;p.anchor.setAttribute('aria-expanded','false');p.anchor.removeAttribute('aria-controls');p.el.remove();if(focus&&p.anchor.isConnected)p.anchor.focus({preventScroll:true});}
document.addEventListener('pointerdown',e=>{const p=V41_NAV.picker;if(p&&!p.el.contains(e.target)&&!p.anchor.contains(e.target))v41ClosePicker();},true);
window.addEventListener('keydown',e=>{if(document.querySelector('.q125-history-dialog[open],.q128-history-media-drawer[open]'))return;if(e.key==='Escape'&&V41_NAV.picker){e.preventDefault();e.stopImmediatePropagation();v41ClosePicker(true);}},true);
window.addEventListener('resize',v41PositionPicker);
const v41NavigationSync=v29Sync;v29Sync=function(){v41NavigationSync();v41EnhanceNavigation();};
v41EnhanceNavigation();

