/* A customer entry URL carries project identity and presentation settings only. */
function v58QuoteUrl(project){
 const page=new URL(location.href);
 if(!/^https?:$/.test(page.protocol)||/^(localhost|127\.0\.0\.1|\[::1\])$/.test(page.hostname))return '';
 page.search='';page.hash='';
 if(!page.pathname.endsWith('/')&&!/\/(?:index|client)(?:\.html)?$/i.test(page.pathname))page.pathname+='/';
 const url=new URL('client.html',page);url.searchParams.set('project',project);url.searchParams.set('currency',quoteFxCcy());url.searchParams.set('rate',String(quoteFxRate()));url.searchParams.set('lang','en');url.hash='plan';return url.href;
}
async function v58CopyQuote(project){
 if(!PROJECTS.some(p=>p[0]===project)||!projectQuoteRows(project).some(q=>q.products.length))return toast('请先提交该项目的报价');
 const url=v58QuoteUrl(project);if(!url)return toast('请打开发布后的网页再复制客户链接');let copied=false;
 try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);copied=true;}}catch(e){}
 if(!copied){const input=document.createElement('textarea');input.value=url;input.readOnly=true;input.style.cssText='position:fixed;top:0;left:0;opacity:0';document.body.append(input);input.select();try{copied=document.execCommand('copy');}catch(e){}input.remove();}
 if(copied){toast('链接已复制，可发送给客户，支持手机和电脑打开');return;}
 v3Dialog('复制客户链接',`<label class="v58-copy-fallback">客户报价链接<input id="v58ShareUrl" readonly value="${esc(url)}" aria-label="客户报价链接"></label><p>浏览器未允许自动复制，请选中链接后复制。</p>`,`<button class="wk-btn" data-v3="closeDialog">关闭</button>`);const input=document.getElementById('v58ShareUrl');input?.focus();input?.select();
}
