 const snapshot={...WK_CATALOG.find(p=>p.sku===x[3]),...(row.productSnapshot||x[6]?.productSnapshot||{})};
 const template=PIMS46.find(row._pims?.templateId||submitted?.templateId||submitted?.tpl||x[1]);
