/* Quotation exchange rates are CNY per 1 unit of the selected currency. */
(function(root){
 const currencies=[['USD','美元'],['EUR','欧元'],['GBP','英镑'],['AUD','澳元'],['CAD','加元'],['AED','阿联酋迪拉姆'],['SAR','沙特里亚尔'],['JPY','日元'],['HKD','港币'],['SGD','新加坡元'],['KES','肯尼亚先令'],['CNY','人民币']];
 const supported=ccy=>currencies.some(c=>c[0]===ccy),valid=value=>Number.isFinite(Number(value))&&Number(value)>0;
 let cache=null;
 function fromEr(data,ccy){
  if(data?.result!=='success'||data.base_code!=='USD'||!supported(ccy)||!valid(data.rates?.CNY)||!valid(data.rates?.[ccy])||!Number.isFinite(data.time_last_update_unix))throw Error('Invalid rate response');
  return {ccy,rate:ccy==='CNY'?1:Number((data.rates.CNY/data.rates[ccy]).toFixed(6)),date:new Date(data.time_last_update_unix*1000).toISOString().slice(0,10),source:'ExchangeRate-API',url:'https://www.exchangerate-api.com'};
 }
 function fromFrankfurter(data,ccy){if(data?.base?.toUpperCase()!==ccy||data.quote?.toUpperCase()!=='CNY'||!valid(data.rate)||!/^\d{4}-\d{2}-\d{2}$/.test(data.date))throw Error('Invalid rate response');return {ccy,rate:Number(Number(data.rate).toFixed(6)),date:data.date,source:'Frankfurter',url:'https://frankfurter.dev/'};}
 async function read(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),9000);try{const response=await fetch(url,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('Rate service unavailable');return await response.json();}finally{clearTimeout(timer);}}
 async function latest(ccy,force=false){
  ccy=ccy==='RMB'?'CNY':ccy;if(!supported(ccy))throw Error('Unsupported currency');if(ccy==='CNY')return {ccy,rate:1,date:'',source:'',url:''};
  if(!force&&cache&&Date.now()-cache.readAt<3600000&&cache.data.time_next_update_unix*1000>Date.now())return fromEr(cache.data,ccy);
  try{const data=await read('https://open.er-api.com/v6/latest/USD'),rate=fromEr(data,ccy);cache={data,readAt:Date.now()};return rate;}
  catch{try{return fromFrankfurter(await read('https://api.frankfurter.dev/v2/rate/'+ccy+'/CNY'),ccy);}catch{throw Error('暂时无法读取最新汇率，请手动填写或稍后重试。');}}
 }
 root.QUOTE_FX65={currencies,supported,valid,fromEr,fromFrankfurter,latest};
})(globalThis);

