function v65FxDialog(mode,project){
 if(!PROJECTS.some(p=>p[0]===project)||!projectQuoteRows(project).some(q=>q.products.length))return toast('请先提交该项目的报价');
 const currency=quoteFxCcy()==='RMB'?'CNY':quoteFxCcy(),current=QUOTE_FX65.supported(currency)?currency:'USD';
 v3Dialog(mode==='copy'?'复制客户报价链接':'客户预览设置',`<div class="q65-fx-form"><div class="q65-fx-project">${esc(findProject(project)[1])}</div><label for="q65Currency">报价币种</label><select id="q65Currency">${QUOTE_FX65.currencies.map(([c,n])=>`<option value="${c}" ${current===c?'selected':''}>${c} · ${n}</option>`).join('')}</select><div class="q65-fx-label"><label for="q65Rate">报价汇率</label><button type="button" id="q65Latest">读取最新汇率</button></div><div class="q65-fx-input"><span id="q65Base">1 ${current} =</span><input id="q65Rate" type="number" inputmode="decimal" min="0.000001" step="any" aria-label="报价汇率" value="${current==='CNY'?1:quoteFxRate()}"><span>CNY</span></div><div id="q65RateSource" class="q65-fx-source" role="status" aria-live="polite"></div><p class="q65-fx-error" id="q65RateError" role="alert"></p></div>`,`<button type="button" class="wk-btn" data-v3="closeDialog">取消</button><button type="button" class="wk-btn primary" id="q65Continue">${mode==='copy'?'生成并复制链接':'打开客户预览'}</button>`);
 const box=document.getElementById('v3Dialog');box.classList.add('q65-fx-dialog');const select=box.querySelector('#q65Currency'),input=box.querySelector('#q65Rate'),source=box.querySelector('#q65RateSource'),error=box.querySelector('#q65RateError'),next=box.querySelector('#q65Continue'),refresh=box.querySelector('#q65Latest');let request=0,reading=false,record=null;
 const ready=()=>{next.disabled=reading||!QUOTE_FX65.valid(input.value);refresh.disabled=reading||select.value==='CNY';input.disabled=select.value==='CNY';box.querySelector('#q65Base').textContent='1 '+select.value+' =';};
 async function readLatest(force=false){
  const sequence=++request,ccy=select.value;record=null;error.textContent='';if(ccy==='CNY'){input.value='1';reading=false;source.textContent='人民币原币报价';ready();return;}
  reading=true;source.textContent='正在读取最新汇率…';ready();
  try{const value=await QUOTE_FX65.latest(ccy,force);if(sequence!==request||!box.isConnected)return;record=value;input.value=String(value.rate);source.innerHTML=`<span>汇率日期 ${esc(value.date)}</span><a href="${esc(value.url)}" target="_blank" rel="noopener noreferrer">Rates by ${esc(value.source)}</a>`;}
  catch(e){if(sequence!==request||!box.isConnected)return;source.textContent=QUOTE_FX65.valid(input.value)?'当前为手动汇率':'';error.textContent=e.message;}
  finally{if(sequence===request&&box.isConnected){reading=false;ready();}}
 }
 input.addEventListener('input',()=>{++request;reading=false;record=null;error.textContent='';source.textContent='手动汇率';ready();});
 select.addEventListener('change',()=>{input.value='';readLatest();});refresh.addEventListener('click',()=>readLatest(true));
 next.addEventListener('click',async()=>{
  if(reading||!QUOTE_FX65.valid(input.value)){error.textContent='请输入大于 0 的有效汇率';return;}
  const ccy=select.value,rate=ccy==='CNY'?1:Number(input.value);QUOTE_UI.fx={ccy,rate,...(record?{date:record.date,source:record.source}:{source:'manual'})};archiveProject=project;v3CloseDialog();
  if(mode==='copy')return v65CopyWithFx(project);
  QUOTE_UI.clientCat=QUOTE_UI.cat||'全部品类';QUOTE_UI.clientSpace=(!QUOTE_UI.space||QUOTE_UI.space==='全部空间')?'all':QUOTE_UI.space;SKY.lang='en';openClientQuoteView();
 });
 box.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target===input){e.preventDefault();if(!next.disabled)next.click();}if(e.key==='Tab'){const controls=[...box.querySelectorAll('button:not(:disabled),input:not(:disabled),select,a')].filter(n=>n.getClientRects().length);if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus();}}});
 readLatest();
}
