 const conflict=v68AllocationConflict(data.project,data.cat,data.sm);if(conflict)throw new Error(conflict);
 if(OPPS.some(o=>o[4]===data.project&&o[3]===data.cat&&o[7]===data.sm&&o[2]!=='已转介绍'))throw new Error('该 SM 已有本项目本品类商机');
 if(TODOS.some(t=>t.project===data.project&&t.status==='待处理'&&(t.type==='确认商机'&&t.owner===data.sm&&(t.cat||t.smDept)===data.cat||V68_APPROVALS.includes(t.type)&&t.allocation?.cat===data.cat&&t.allocation.sm===data.sm)))throw new Error('该商机已有待处理申请，请先处理原待办');
