function v69Db(){return v69DbPromise||(v69DbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('george-crm-attachments',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(new Error('附件存储不可用，请检查浏览器设置'));}));}
async function v69FileStore(id,value){const db=await v69Db();return new Promise((resolve,reject)=>{const tx=db.transaction('files',value===undefined?'readonly':'readwrite'),store=tx.objectStore('files'),request=value===undefined?store.get(id):store.put(value,id);let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(new Error('附件保存失败，请检查浏览器存储空间'));});}
