function v69FileRows(files,key,editable){return files.map((file,i)=>`<div class="v69-file"><span class="v69-file-icon">${file.type?.startsWith('image/')?'▧':file.name?.split('.').pop()?.slice(0,4).toUpperCase()||'FILE'}</span><div><b title="${esc(file.name)}">${esc(file.name)}</b><small>${file.size?fileSize(file.size):'已关联'}${!file.id&&!file.url?' · 原文件未保存':''}</small></div><div class="v69-file-actions">${file.id||file.url?`<button type="button" data-v69-file="preview" data-key="${esc(key)}" data-index="${i}">${file.type?.startsWith('image/')||file.type==='application/pdf'?'预览':'下载'}</button>`:''}${editable?`<button type="button" data-v69-file="remove" data-key="${esc(key)}" data-index="${i}" aria-label="删除 ${esc(file.name)}">×</button>`:''}</div></div>`).join('');}
function v69UploadHtml(key,files=[],options={}){V69_UPLOADS.set(key,{files:files.slice(),options,busy:false});return `<div class="v69-uploader" data-v69-upload="${esc(key)}" tabindex="0" aria-label="${options.images?'上传同意截图':'上传附件'}"><div class="v69-drop"><span class="v69-upload-symbol">↑</span><div><b>拖拽文件到这里，或<button type="button" data-v69-pick="${esc(key)}">选择文件</button></b><small>${options.images?'上传 1 张同意截图，支持 JPG、PNG 等图片，最大 10 MB':'支持图片、PDF、文档、表格、图纸及视频；每个文件最大 20 MB'}</small></div><input type="file" data-v69-input="${esc(key)}" ${options.max===1?'':'multiple'} ${options.images?'accept="image/*"':''} hidden></div><div class="v69-upload-status" aria-live="polite"></div><div class="v69-file-list">${v69FileRows(files,key,true)}</div></div>`;}
function v69AttachmentList(files){if(!files?.length)return '';const key='readonly-'+(++v69AttachmentSeq);V69_UPLOADS.set(key,{files,options:{},busy:false});return `<div class="v69-read-attachments">${v69FileRows(files,key,false)}</div>`;}
function v69RefreshUpload(key,state){const box=[...document.querySelectorAll('[data-v69-upload]')].find(el=>el.dataset.v69Upload===key);if(!box||V69_UPLOADS.get(key)!==state)return;box.classList.toggle('is-busy',state.busy);box.querySelector('.v69-file-list').innerHTML=v69FileRows(state.files,key,true);box.querySelector('.v69-upload-status').textContent=state.busy?'正在保存附件…':state.error||'';box.querySelector('[data-v69-pick]').disabled=state.busy;state.options.changed?.(state.files);}
async function v69AddFiles(key,list){const state=V69_UPLOADS.get(key);if(!state||state.busy)return;state.busy=true;state.error='';v69RefreshUpload(key,state);const errors=[];
 for(const file of [...list]){try{if(state.files.length>=(state.options.max||10))throw Error('最多上传 '+(state.options.max||10)+' 个文件');if(state.files.some(f=>f.name===file.name&&f.size===file.size)){continue;}if(file.size>20*1024*1024)throw Error(file.name+' 超过 20 MB');if(state.options.images){const image=await v68ReadImage(file);state.files.push(image);}else{const id='attachment-'+crypto.randomUUID();await v69FileStore(id,file);state.files.push({id,name:file.name,size:file.size,type:file.type});}}catch(e){errors.push(e.message);}}
 state.busy=false;state.error=errors.join('；');v69RefreshUpload(key,state);
}
async function v69PreviewFile(key,index){try{const file=V69_UPLOADS.get(key)?.files[index];if(!file)return;let url=file.url,temporary=false;if(file.id){const blob=await v69FileStore(file.id);if(!blob)throw Error('此浏览器未保存该附件，请重新上传');url=URL.createObjectURL(blob);temporary=true;}if(!/^(blob:|data:image\/|https?:\/\/)/.test(url||''))throw Error('原附件不可用，请重新上传');
 const close=()=>{document.querySelector('.v69-file-view')?.remove();if(temporary)URL.revokeObjectURL(url);};
 if(file.type?.startsWith('image/')||file.type==='application/pdf'){const overlay=document.createElement('div');overlay.className='v69-file-view';overlay.innerHTML=`<section role="dialog" aria-modal="true" aria-label="附件预览"><header><b>${esc(file.name)}</b><button type="button" aria-label="关闭附件预览">×</button></header>${file.type==='application/pdf'?`<iframe title="${esc(file.name)}" src="${esc(url)}"></iframe>`:`<img alt="${esc(file.name)}" src="${esc(url)}">`}</section>`;overlay.querySelector('button').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};overlay.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();close();}};document.body.appendChild(overlay);overlay.querySelector('button').focus();}else{const link=document.createElement('a');link.href=url;link.download=file.name;link.click();if(temporary)setTimeout(()=>URL.revokeObjectURL(url),1000);}
 }catch(e){toast(e.message);}}
document.addEventListener('click',event=>{const pick=event.target.closest('[data-v69-pick]');if(pick){pick.closest('.v69-uploader').querySelector('input[type=file]').click();return;}const button=event.target.closest('[data-v69-file]');if(!button)return;const {key,index}=button.dataset,state=V69_UPLOADS.get(key);if(button.dataset.v69File==='remove'){if(state?.busy)return;state.files.splice(Number(index),1);state.error='';v69RefreshUpload(key,state);}else v69PreviewFile(key,Number(index));});
