// Display-only progress summaries. Task records remain the source of truth.
const V71_FLOW_RANK={'客户待办':0,'设计待办':1,'创建项目待办':2,'项目待办':3,'确认商机':4,'跨区域商机审批待办':4,'转介绍商机审批待办':4,'报价待办':5,'订单待办':6};
function v71FlowBranchKey(t){
 return v83FlowGroups(TODOS).find(g=>g.items.some(x=>x.id===t.id))?.key||'';
}
function v71RequestTasks(origin){
 return origin?v83FlowScope(origin).related.filter(t=>t.type!=='客户待办'):[];
}
function v71FlowLatest(tasks){
 // A generated downstream task may still be blocked after an upstream return.
 const eligible=tasks.filter(t=>Object.hasOwn(V71_FLOW_RANK,t.type)&&
  !(t.status==='待处理'&&typeof todoBlockedReason==='function'&&todoBlockedReason(t)));
 const available=eligible.length?eligible:tasks;
 const pending=available.filter(t=>t.status==='待处理');
 const list=pending.length?pending:available;
 return [...list].sort((a,b)=>(V71_FLOW_RANK[b.type]??-1)-(V71_FLOW_RANK[a.type]??-1)||
  String(b.time||'').localeCompare(String(a.time||'')))[0]||null;
}
function v71FlowStatus(tasks){
 const branches=v83FlowGroups(tasks);
 const latest=branches.length?branches.map(g=>v71FlowLatest(g.items)):[v71FlowLatest(tasks)];
 const states=latest.filter(Boolean).map(t=>t.status);
 return states.includes('待处理')?'待处理':states.includes('已驳回')?'已驳回':states.length&&states.every(s=>s==='已处理')?'已处理':'待处理';
}
function v71FlowStatusHtml(status){
 const tone=status==='已处理'?'done':status==='已驳回'?'rejected':'pending';
 return `<span class="v71-flow-status ${tone}" aria-label="处理状态：${esc(status)}">${esc(status)}</span>`;
}
function v71FilterFlowOptions(input){
 const panel=input.closest('.v71-flow-options'),query=input.value.trim().toLocaleLowerCase();
 let count=0;
 for(const button of panel.querySelectorAll('[data-act="dealFlowSwitch"]')){
  button.hidden=!button.dataset.search.includes(query);if(!button.hidden)count++;
 }
 panel.querySelector('.v71-flow-empty').hidden=count>0;
 panel.querySelector('.v71-flow-count').textContent=query?count+' / '+panel.dataset.total:panel.dataset.total;
}
const v71PreviousOpenFlow=openDealFlow;
openDealFlow=function(item,branch){
 if(!v21FlowAllowed(item))return toast('当前账号没有该流程的查看范围');
 const previous=document.querySelector('#mBody .v71-flow-options');
 const scope=item.id+'|'+(item.type==='客户待办'?V45_FLOW.requestId:v45RequestOf(item));
 const retained=previous?.dataset.scope===scope?{query:previous.querySelector('input').value,scroll:previous.querySelector('.deal-flow-switch').scrollTop}:null;
 const result=v71PreviousOpenFlow(item,branch),body=document.getElementById('mBody');
 if(!body)return result;
 const model=v83FlowModel(item,branch),requests=model.requests;
 if(requests.length){
  const cards=`<div class="v45-request-switch v71-request-switch" role="group" aria-label="客户需求">${requests.map((t,i)=>{
   const project=t.project&&t.project!=='-'?(PROJECTS.find(p=>p[0]===t.project)?.[1]||t.project):'';
   return `<button type="button" data-act="v45FlowRequest" data-id="${esc(item.id)}" data-request="${esc(t.id)}" class="${t.id===V45_FLOW.requestId?'on':''}" aria-pressed="${t.id===V45_FLOW.requestId}"><span class="v71-request-heading"><span>需求 ${requests.length-i}</span>${v71FlowStatusHtml(v71FlowStatus(v71RequestTasks(t)))}</span><b title="${esc(t.needInfo?.need||'空间方案需求')}">${esc(t.needInfo?.need||'空间方案需求')}</b>${project?`<small>${esc(project)}</small>`:''}</button>`;
  }).join('')}</div>`;
  const old=body.querySelector('.v45-request-switch');if(old)old.outerHTML=cards;else body.insertAdjacentHTML('afterbegin',cards);
 }
 const switcher=body.querySelector('.deal-flow-switch');
 if(switcher){
  const groups=model.groups;
  const panel=document.createElement('section');panel.className='v71-flow-options';panel.dataset.scope=item.id+'|'+(requests.length?V45_FLOW.requestId:v45RequestOf(item));panel.dataset.total=String(groups.length);
  panel.innerHTML=`<div class="v71-flow-options-head"><h3>品类商机 <span class="v71-flow-count">${groups.length}</span></h3><label class="v71-flow-search"><span class="v71-sr-only">搜索品类或 SM</span><input type="search" placeholder="搜索品类 / SM" autocomplete="off"></label></div>`;
  switcher.before(panel);panel.append(switcher);switcher.setAttribute('role','group');switcher.setAttribute('aria-label','品类商机');
  for(const button of switcher.querySelectorAll('button')){
   const group=groups.find(g=>g.key===button.dataset.key);if(!group)continue;
   const selected=button.classList.contains('on');button.setAttribute('aria-pressed',String(selected));
   button.dataset.search=(group.cat+' '+group.sm).toLocaleLowerCase();
   const status=v71FlowStatus(group.items);
   button.innerHTML=`<span class="v71-option-top"><strong>${esc(group.cat)}</strong>${v71FlowStatusHtml(status)}</span><span class="v71-option-sm" title="${esc(group.sm)}">${esc(group.sm||'未指定 SM')}</span>`;
  }
  panel.insertAdjacentHTML('beforeend','<p class="v71-flow-empty" role="status" hidden>没有匹配的品类或 SM</p>');
  const input=panel.querySelector('input');if(retained){input.value=retained.query;v71FilterFlowOptions(input);switcher.scrollTop=retained.scroll;}
  const note=panel.nextElementSibling;if(note?.classList.contains('deal-flow-note'))note.remove();
 }
 if(!retained)body.scrollTop=0;
 return result;
};
